/**
 * @file reclaim.c
 * @brief Emits the reclaim runtime: splices the bitmap-slab, zero-the-counts and
 *        regional-sweep C text into the generated file.
 *
 * Every line of the text is one entry of `RECLAIM_RT`, concatenated in emission order; the
 * concatenation is the runtime that really runs in the generated file. The text is cut per line
 * for two reasons: one literal above 4095 characters trips `-Woverlength-strings` (adjacent
 * literals are concatenated and count as one, so concatenating does not help), and this runtime
 * is readable generated output, where one line per entry reviews better than one escaped block.
 *
 * The shape and soundness obligations of the text itself are stated in the block comment at the
 * head of the text: they are criteria, not optimization.
 *
 * Emission is tiered: the title line of every section carries a stable label `[rt:name]`, and
 * this compile's tier decides whether the section is emitted at all (no frame-root chain means
 * no chain-pushing code; no counting means no counter arrays). Dropping a section is equivalent
 * to letting the preprocessor drop it, except that the generated file keeps no code this tier
 * can never reach.
 */

#include "reclaim.h"

#include <stdio.h>    /* snprintf: builds the tier macro names */
#include <stdlib.h>   /* getenv: called by the emitted runtime, not by this file */
#include <string.h>   /* strncmp/strstr/strchr/memcmp: tier scan and labels */

/** @brief Whether a section's label is emitted at this compile's tier.
 *
 * A section labelled `[rt:counters]` is emitted only in the counting tier and `[rt:chain]` only
 * once the frame-root chain is wired; every other section is always emitted. Dropping a section
 * leaves the semantics unchanged: that tier never reaches the code, so emitting it would only
 * add pages to read.
 *
 * @param line    one line of the runtime text.
 * @param timeOn  the counting tier is on.
 * @param chainOn the frame-root chain is emitted.
 * @return 1 to emit the section, 0 to drop it.
 */
static int rtSectionOn(const char *line, int timeOn, int chainOn) {
    const char *p = strstr(line, "[rt:");
    if (p == NULL) return 1;
    p += 4;
    const char *e = strchr(p, ']');
    if (e == NULL) return 1;
    size_t n = (size_t)(e - p);
    if (n == 8 && memcmp(p, "counters", 8) == 0) return timeOn;   /* counter arrays exist only in the counting tier */
    if (n == 5 && memcmp(p, "chain", 5) == 0) return chainOn;     /* the frame-root chain has no emitter pushing onto it */
    return 1;
}

/** @brief Match a tier-switch `#if`: one macro name, optionally negated, known at this
 *         compile.
 *
 * Returns 1 when the condition resolves (*val holds its truth value); the emitter then drops the
 * `#if` directive along with the branch it rules out. Conditions that do not resolve
 * (`#ifndef`, `#if X > N`, combinations) return 0 and are emitted verbatim, so the compiler and
 * -D still decide — those knobs switch behavior or run comparisons through -D overrides.
 *
 * @param p         condition text, with the leading `#if` already stripped.
 * @param noCount   value of EXTC_RC_NOCOUNT.
 * @param timeOn    value of EXTC_RC_TIME.
 * @param sweepFree value of EXTC_RC_SWEEP_FREE.
 * @param[out] val  receives the truth value of the condition when it resolves.
 * @return 1 if the condition resolves, 0 if it is left to the preprocessor.
 */
static int rtCfgIf(const char *p, int noCount, int timeOn, int sweepFree, int *val) {
    static const char *const suffixes[3] = { "NOCOUNT", "TIME", "SWEEP_FREE" };
    const int vals[3] = { noCount, timeOn, sweepFree };
    while (*p == ' ') p++;
    int neg = 0;
    if (*p == '!') { neg = 1; p++; while (*p == ' ') p++; }
    for (int k = 0; k < 3; k++) {
        /* The macro name is built from prefix + suffix instead of one whole literal: these are
         * macros the generated file defines, not switches of the compiler itself (a whole literal
         * would be taken for a new switch by the static scan of the switch table). */
        char name[32];
        int n = snprintf(name, sizeof name, "EXTC_RC_%s", suffixes[k]);
        if (n <= 0 || (size_t)n >= sizeof name) continue;
        if (strncmp(p, name, (size_t)n) != 0) continue;
        const char *q = p + n;
        while (*q == ' ' || *q == '\n' || *q == '\r') q++;
        if (*q != '\0') continue;
        *val = neg ? !vals[k] : vals[k];
        return 1;
    }
    return 0;
}
/* The emitted text, one line per entry. Every line carries its own newline, so the
 * concatenation is byte-identical to the source text. */
static const char *const RECLAIM_RT[] = {
    "/* ---- reclaim runtime: bitmap slab + holder counts + regional sweep [rt:head] ----\n",
    " *\n",
    " * Three of the four tiers the runtime provides (release the whole local place, zero the counts, regional sweep):\n",
    " *\n",
    " *   local    the parse region bump-allocates; leaving the scope rewinds the bump pointer, O(1);\n",
    " *   counts   holder counts attach only to **pointer assignment**; reaching zero returns the slot to the free chain at once;\n",
    " *   sweep    once a region's occupancy crosses the pressure line, mark from the roots + registration bitmap, then **scan 64-bit words in order** and free the unmarked ones.\n",
    " *\n",
    " * Shape: a payload rounds up to a slot in **8-byte** units (not a power of two: an 80-byte object takes an 80-byte slot), laid out contiguously in\n",
    " * EXTC_RC_SLAB_BITS-aligned slabs. Finding the slab from an object pointer is **one bitwise AND** (alignment means no table lookup);\n",
    " * finding the slot number is **one reciprocal multiply and shift** (see extc_rc_slotOf). Each slab has three\n",
    " * bitmaps (occupancy / mark / cross-region registration) + one holder count and one type number per slot; free slots are chained by slot number,\n",
    " * so allocation is O(1). The sweep does not chase pointers and does not free slot by slot.\n",
    " *\n",
    " * Soundness obligations (missing one dangles, so these are not optimizations):\n",
    " *\n",
    " *  1. **A fresh slot and a slot whose old value is overwritten are two operations.** A fresh slot holds the next free slot number; dereferencing that as an old pointer crashes;\n",
    " *     the compiler knows statically which it is, so there are two entry points: initRef only writes and bumps the target count, storeRef reads the old value.\n",
    " *  2. **The registration bitmap is persistent and deduplicated; the sweep does not clear it.** Clearing it forgets cross-region in-edges, and the next round frees objects that another region\n",
    " *     still points at.\n",
    " *  3. **Counts saturate in three stages, and the saturated value means unknown.** At the ceiling the count sticks and never decreases again, so it is never mistaken for zero; hand those to the sweep.\n",
    " *  4. **Marking walks pointer fields with the object's own type descriptor.** The allocation site hands the descriptor to the runtime with the slot (each slot stores one\n",
    " *     pointer); walking with the wrong descriptor, or treating a missing one as present, misses marks.\n",
    " *  5. **Releasing a slot must clear its registration bit.** Otherwise a new object reusing the slot looks live through the stale entry and is missed.\n",
    " *  6. **Only slots allocated by this runtime may be counted/registered/marked.** A pointer from a plate/pool/stack/C allocation is not such a slot;\n",
    " *     the bitwise AND in slabOf lands in unrelated memory, which segfaults. Every slab is entered at creation into a table sorted by base address,\n",
    " *     and count/register/mark first ask owns; a slot absent from the table (or already free) is skipped entirely.\n",
    " *  7. **When the host cannot be proved, the target region must leave the sweep.** The cross-region registration sits on the target and the source object does not know it,\n",
    " *     so it cannot be withdrawn; the static root table has no such slot either. Then mark the target's region as not swept (rather collect less),\n",
    " *     and never sweep as usual with incomplete seeds -- the entry point is `extc_rc_storeRefUnknown`.\n",
    " *\n",
    " * Two further criteria:\n",
    " *  - marking stops at an object outside the region and **does not write its mark bit** -- an object of another region left marked makes its\n",
    " *    next sweep skip it and free its children. Anything outside the region counts as live.\n",
    " *  - assigning a data field calls neither inc nor dec; only a change of reference touches a count.\n",
    " *\n",
    " * One boundary: counts move only on **in-edges**. When a slot reaches zero and is released, the targets it pointed at reach zero only after the emitter drops them\n",
    " * before the object dies (clear the field / unlink the chain); counts not dropped wait for the sweep to kill that section as a whole. This is on\n",
    " * the rather-collect-late side: a dead object only keeps others alive a little longer; it never dangles.\n",
    " *\n",
    " * Self-containment: this text depends only on <stdint.h> <stddef.h> <stdlib.h> <stdio.h>\n",
    " * and <string.h> (memset/memmove), already included at the top of the generated file, and names no user type (the allocation site hands the type layout to the runtime through an ExtcRcType\n",
    " * descriptor); every symbol is static.\n",
    " */\n",
    "\n",
    "#ifndef EXTC_RC_SLAB_BITS\n",
    "#define EXTC_RC_SLAB_BITS 20\n",
    "#endif\n",
    "#ifndef EXTC_RC_FLOOR\n",
    "#define EXTC_RC_FLOOR ((int64_t)1 << 20)\n",
    "#endif\n",
    "#ifndef EXTC_RC_SCALE_MAX\n",
    "#define EXTC_RC_SCALE_MAX ((int64_t)1 << 40)\n",
    "#endif\n",
    "/* Retreat factor after an empty sweep: one round finds nothing, so this whole-heap mark buys zero garbage; retreat hard.\n",
    " * The base is 2 (trigger line = max(2x live, floor)) times this factor, so one empty sweep puts the line at 8x the live set: a shape with a large live set\n",
    " * and little garbage skips a whole-heap mark that would trade the live set for a few MB; a shape with plenty of garbage\n",
    " * collects next round, which resets the factor to 0, so it only affects loads that really have no cycles. */\n",
    "#ifndef EXTC_RC_SCALE_MUL\n",
    "#define EXTC_RC_SCALE_MUL ((int64_t)4)\n",
    "#endif\n",
    "#ifndef EXTC_RC_HOLD_SAT\n",
    "#define EXTC_RC_HOLD_SAT 65535u\n",
    "#endif\n",
    "/* Per-component counting is off by default: the counting entry point is a no-op so no call site pays an increment.\n",
    " * The next section redefines it as a real increment when counting. */\n",
    "#if !EXTC_RC_TIME\n",
    "#define EXTC_RC_TICK(k) do { } while (0)\n",
    "#endif\n",
    "\n",
    "/* ---- Per-component counting (EXTC_RC_TIME=1): how many times each reclaim component is called [rt:counters] ---\n",
    " *\n",
    " * Counts calls, not time. A pair of clock reads bracketing a function body cannot contain it:\n",
    " *   - a pair of rdtsc reads per call costs more than the small operation being timed;\n",
    " *   - reading once per N calls and subtracting windows measures inclusive time -- several components report the same loop;\n",
    " *   - closing on function exit with the cleanup attribute gets scheduled near the declaration by the compiler;\n",
    " *   - cpuid serialization is itself expensive enough to swamp the measurement.\n",
    " * Time attribution therefore happens outside the program: run A/B on the same program with the whole reclaim on/off, or with one component resolved away.\n",
    " * What remains here is exact call counts, to answer which components are really reached and how many times each. */\n",
    "enum { EXTC_RC_NCOMP = 8 };\n",
    "static unsigned long long extc_rc_tc[EXTC_RC_NCOMP];\n",
    "static const char *const extc_rc_tname[EXTC_RC_NCOMP] = {\n",
    "    \"alloc\", \"storeReg\", \"storeOwned\", \"collect\", \"slabNew\", \"freeSlot\", \"regionNew\", \"reserved\" };\n",
    "static int extc_rc_tinit;\n",
    "static void extc_rc_treport(void) {\n",
    "    for (int i = 0; i < EXTC_RC_NCOMP; i++)\n",
    "        if (extc_rc_tc[i])\n",
    "            fprintf(stderr, \"[rccount] %-11s calls=%llu\\n\", extc_rc_tname[i], extc_rc_tc[i]);\n",
    "}\n",
    "#define EXTC_RC_TICK(k) do { \\\n",
    "    if (!extc_rc_tinit) { extc_rc_tinit = 1; atexit(extc_rc_treport); } \\\n",
    "    extc_rc_tc[k]++; \\\n",
    "} while (0)\n",
    "\n",

    "/* ---- Structs and constants: layout of the slot, slab and region tables [rt:types] ---\n",
    " *\n",
    " * Every later section reads and writes these fields. The type descriptor is the only source that knows which words are pointers at mark time (obligation 4),\n",
    " * so it is fixed before any code. */\n",
    "\n",
    "/* The reference-slot layout of a type: nptr reference fields at offsets off[k]. off points to a separate\n",
    " * uint32_t table, so the entry count has no ceiling. The allocation site hands the descriptor to the runtime with the slot, and marking walks the object's own\n",
    " * descriptor (obligation 4).\n",
    " *\n",
    " * A slot stores a **type number** (16 bits), not a descriptor pointer: a descriptor pointer is 8 bytes per slot, the largest per-slot metadata in this runtime.\n",
    " * The number-to-descriptor mapping lives in the slab's **small type table** `ttab` (deduplicated by pointer\n",
    " * equality) -- a slab is one size class, usually fed by one or two allocation sites, so a lookup is one comparison.\n",
    " * Number meaning: 0 = no descriptor (a data object, no reference fields); 1 = `EXTC_RC_CONSERVATIVE` (fallback,\n",
    " * always that one table cell); >=2 = a `ttab` index.\n",
    " *\n",
    " * EXTC_RC_CONSERVATIVE is the fallback descriptor: which words of the object are pointers is unknown, so marking scans every word of the slot\n",
    " * as a candidate pointer. It is used in one place: `alloc<T>(n)` where T has references -- the offsets of elements 1..n-1\n",
    " * change with a runtime count, which a static descriptor cannot express. Conservative marking only keeps too much, never misses. */\n",
    "typedef struct ExtcRcType {\n",
    "    uint32_t nptr;\n",
    "    const uint32_t *off;\n",
    "} ExtcRcType;\n",
    "#define EXTC_RC_CONSERVATIVE ((const ExtcRcType *)-1)\n",
    "/* Hash bucket count of the size-class table (a power of two): the allocation fallback looks up the has-a-free-slot slab chain by slot stride, see extc_rc_classBucket. */\n",
    "#define EXTC_RC_CLS_BUCKETS 32u\n",
    "\n",
    "typedef struct ExtcRcSlab ExtcRcSlab;\n",
    "typedef struct ExtcRcRegion ExtcRcRegion;\n",
    "\n",
    "struct ExtcRcSlab {\n",
    "    ExtcRcSlab   *next;      /* this region's slab chain */\n",
    "    ExtcRcRegion *region;    /* back pointer: a count reaching zero updates the region's occupied bytes */\n",
    "    uint64_t     *occ;       /* occupancy bitmap */\n",
    "    uint64_t     *mark;      /* mark bitmap (holds only this round's bits before and after each sweep of the region) */\n",
    "    uint64_t     *rsbit;     /* cross-region registration bitmap: this slab's slots are pointed at from another region */\n",
    "    uint16_t     *hold;      /* per slot: exact holder count */\n",
    "    uint16_t     *rscnt;     /* per slot: cross-region **in-edge** count (accounted on the source side). The bitmap cell is\n",
    "                              * a cache of at-least-one-live-edge-from-another-region: 0 to 1 sets the bit, 1 to 0 clears it;\n",
    "                              * when the source object dies or its region is dropped the edge is withdrawn at the source, so the bit does not stay\n",
    "                              * sticky (a sticky bit would make every round's new objects permanent seeds, so memory grows linearly). */\n",
    "    uint16_t     *tid;       /* per slot: type number (0 = no descriptor; 1 = fallback; >=2 = ttab index) */\n",
    "    const ExtcRcType **ttab; /* this slab's type table: number to descriptor, deduplicated by pointer equality, grows on demand */\n",
    "    uint32_t      ttabN, ttabCap;\n",
    "    uint16_t     *thash;     /* type-number hash index: descriptor pointer to ttab index (0 = empty). A slab with few\n",
    "                              * descriptors does not build it (a linear scan is faster); it is built past EXTC_RC_TTAB_LINEAR_MAX. */\n",
    "    uint32_t      thashCap;  /* index capacity (a power of two; 0 = not built) */\n",
    "    const ExtcRcType *lastTd; /* the last descriptor that landed in this slab: consecutive allocations of one type on one slab are the norm,\n",
    "                              * and a hit skips the type table lookup (hash probe included). Filled only after this slab's table insert succeeds. */\n",
    "    uint16_t      lastTid;   /* type number paired with lastTd */\n",
    "    char         *data;      /* start of the slot payload: in the slab's own block normally, separately malloc'd for a huge block */\n",
    "    int           big;       /* 1 = huge block: the payload is not in the slab and there is only 1 slot (see extc_rc_slabNew) */\n",
    "    int64_t       freelist;  /* head of the **reuse** chain (holds only released slots): a slot number, -1 = empty.\n",
    "                              * The chain's next slot number lives in each slot's tid[] (slot number + 1, 0 = end), not in the payload --\n",
    "                              * a released slot is cold, and writing an 8-byte header pointer into the payload pulls in the whole cache line (RFO).\n",
    "                              * See extc_rc_freeSlot. */\n",
    "    uint32_t      bump;      /* cursor over never-issued slots: [0, bump) issued, [bump, nslots) not yet */\n",
    "    size_t        ss;        /* slot stride (a multiple of 8, not a power of two): slot lookup from a pointer uses it */\n",
    "    uint64_t      rcp;       /* reciprocal of the slot stride (extc_rc_rcpOf): multiply and shift divides exactly */\n",
    "    uint32_t      nslots, nwords;\n",
    "    uint32_t      swEpoch;   /* the sweep round that last finished this slab (= the region's swId):\n",
    "                              * marking an allocation black only considers positions the cursor has not reached, and this decides it. */\n",
    "    ExtcRcSlab   *availNext; /* next block on this size class's has-a-free-slot chain (valid when avail=1); the head is in r->clsBkt */\n",
    "    int           avail;     /* 1 = already on this size class's chain (stops the same block being pushed twice, see extc_rc_classPush) */\n",
    "};\n",
    "\n",
    "/* Hash bucket node for the size-class to has-a-free-slot slab chain. The allocation path uses it to get the next usable block in O(1):\n",
    " * a linear search of the r->slabs chain for a same-size slab with a free slot degrades with the live block count -- 32 million allocations\n",
    " * over about 8000 blocks made every allocation O(live slabs), quadratic overall.\n",
    " * Entries are only added, never removed (the whole batch is freed when the region is destroyed), so no tombstones. */\n",
    "typedef struct ExtcRcClass {\n",
    "    size_t             ss;    /* slot stride (the key) */\n",
    "    ExtcRcSlab        *head;  /* chain of this class's slabs that may still have a free slot; full blocks stay on it (lazy pop) */\n",
    "    struct ExtcRcClass *next; /* next size class in the same hash bucket */\n",
    "} ExtcRcClass;\n",
    "\n",
    "struct ExtcRcRegion {\n",
    "    ExtcRcSlab *slabs;\n",
    "    ExtcRcSlab *bumpSlab;    /* parse region: the slab bump is currently in */\n",
    "    ExtcRcSlab *allocHot[32]; /* caches the most recent allocatable slab by size class (slot stride / 8); a miss goes to clsBkt */\n",
    "    ExtcRcClass *clsBkt[EXTC_RC_CLS_BUCKETS]; /* size class to has-a-free-slot slab chain (see extc_rc_classSlot) */\n",
    "    char       *bump, *bump_end;\n",
    "    int64_t     bytes;       /* occupied payload bytes, accounted in O(1) */\n",
    "    int64_t     allocBytes;  /* **monotonic** allocated bytes: the credit base for the full traversal */\n",
    "    int64_t     visitedBytes;/* allocBytes at the last O(live set) traversal */\n",
    "    int64_t     roundVisitedBytes;/* round-start credit: consumed only at round start/end, untouched by targeted frees */\n",
    "    int64_t     live;        /* live bytes after the last sweep: the trigger uses twice this */\n",
    "    int64_t     thr;         /* cached pressure threshold: `max(2 * live, floor) * scale` */\n",
    "    int64_t     floor;       /* lower bound of memory pressure */\n",
    "    int64_t     scale;       /* self-learned: multiplier from consecutive empty sweeps; 0 = not learned */\n",
    "    size_t      sweeps, freedSlots;\n",
    "    /* Stepped (interruptible) sweep cursor: which slab and word it reached; how many slots this round freed. */\n",
    "    int32_t     sweeping;\n",
    "    int32_t     swPad_;\n",
    "    ExtcRcSlab *swSlab;\n",
    "    uint32_t    swWord;\n",
    "    uint32_t    swId;        /* sweep round number: incremented by every sweepBegin */\n",
    "    size_t      swFreed;\n",
    "    int32_t     marking;     /* incremental marking in flight (the barrier is on and the sweep yields) */\n",
    "    int32_t     markDone;    /* the mark stack is empty (finishing needs the root table, so the trigger point does it) */\n",
    "    int64_t     markedBytes;  /* payload marked this round: written into live when marking completes */\n",
    "    int32_t     markTick;     /* batched progress: one step every N allocations */\n",
    "    int64_t     markStartAlloc;\n",
    "    size_t      wbDebt;      /* new gray objects shaded this round: the allocation site repays with interest (assist) */\n",
    "    ExtcRcSlab *seedSlab;   /* seed scan cursor: pushes in steps (mark start does not scan the whole region at once) */\n",
    "    uint32_t    seedWord;\n",
    "    uint64_t    seedBits;    /* unified budget: bits of the current word **not yet pushed**; the cursor stays on the same word (0 while W=0) */\n",
    "    int32_t     seedsDone;\n",
    "    int32_t     seedAny;     /* whether any bit of `rsbit` in this region was ever set (a seed was registered), so the cursor is worth walking;\n",
    "                              * with no bit ever set the whole rsbit scan is skipped (the 1024 words of an empty slab would be wasted work) */\n",
    "    int32_t     foreign;    /* whether any slot of this region was ever written a **cross-region** value (a foreign pointer). If none,\n",
    "                              * the old value read by an overwrite can only be null or same-region, so the old-value registration lookup can be skipped (the new value still must be looked up).\n",
    "                              * Set monotonically, never cleared: better to look up too often than to miss a withdrawal. */\n",
    "    int32_t     rid;\n",
    "    int32_t     noSweep;     /* a cross-region in-edge whose host cannot be traced, so this region is exempt from sweeping (rather collect less) */\n",
    "    int32_t     part;        /* this region **took part in rc** (it allocated an object or hosted an assignment) */\n",
    "    int32_t     owe;         /* an inner frame allocated into this region after the pressure line was crossed, so **the frame that owns it**\n",
    "                              * owes one sweep (subset B). Settled in extc_rc_checkOwed. */\n",
    "    void      **mstk;        /* mark stack (region-private, not global) */\n",
    "    size_t      msp, mscap;\n",
    "    /* Cursor for **segmented scanning** of a large object: the object being scanned + how far it got (descriptor index / conservative word index).\n",
    "     * It does not live on the mark stack: the write barrier pushes new force entries onto the stack between two steps, and a cursor entry on the stack would be\n",
    "     * buried or popped as the wrong object (not even safety survives that). Resuming therefore sits at the entry of `extc_rc_markStep`, and one step walks one segment;\n",
    "     * every stack-empty-means-marking-complete test (finish, markAdvance's markDone, the alloc drain guard,\n",
    "     * the various drain loops, settle's progress test) **must also read scanObj**. */\n",
    "    void       *scanObj;\n",
    "    uint32_t    scanOff;\n",
    "    uint32_t    scanPad_;\n",
    "};\n",
    "\n",
    "#define EXTC_RC_SLAB_SIZE ((size_t)1 << EXTC_RC_SLAB_BITS)\n",
    "#define EXTC_RC_SLAB_HDR  ((sizeof(ExtcRcSlab) + 63) & ~(size_t)63)\n",
    "/* A slab's **issued capacity** depends on the slot size instead of always being a full 1 MiB: the block size starts at EXTC_RC_SLAB_CHUNK_MIN\n",
    " * and doubles until it holds EXTC_RC_SLAB_SLOTS_MIN slots or reaches EXTC_RC_SLAB_SIZE.\n",
    " * See extc_rc_slabNew for details. */\n",
    "#define EXTC_RC_SLAB_CHUNK_MIN ((size_t)64 * 1024)\n",
    "#define EXTC_RC_SLAB_SLOTS_MIN ((size_t)1024)\n",
    "/* The reuse chain's next slot number is encoded in each slot's tid[] (uint16: slot number + 1, 0 = end), so a slot number must be below this\n",
    " * bound. The issued-capacity algorithm tops out at 8192 slots; the invariant is written as a criterion against configuration drift (the guard is in slabNew). */\n",
    "#define EXTC_RC_REUSE_MAX_SLOT 0xFFFEu\n",
    "/* Start of the slot payload. A normal slab's payload is in its own 1 MiB block (alignment means finding the slab from an object pointer is one\n",
    " * bitwise AND); a **huge block**'s payload is malloc'd separately and its start is recorded in the slab header. Both share one macro, so\n",
    " * bitmaps / counts / registration / descriptors / marking / sweeping all have a single code path. */\n",
    "#define EXTC_RC_SLAB_DATA(s) ((s)->data)\n",
    "\n",
    "/* ---- Small helpers on the hot path: always `static inline` [rt:helpers] ----\n",
    " *\n",
    " * They sit in every inc/dec/register/mark call, and `ownSlab` is a step every ownership proof walks:\n",
    " * one extra call/return is itself a measurable cost.\n",
    " *\n",
    " * `inline` only, not `always_inline`: forcing inlining expands the same batch of call sites, and on allocation-heavy shapes the\n",
    " * code grows and the instruction cache gets worse; leave it to the compiler's cost model -- flatten what should be flattened, keep what should be kept. */\n",
    "/* Finding the slab from an object pointer: slabs are EXTC_RC_SLAB_SIZE-aligned, so one bitwise AND. */\n",
    "__attribute__((unused)) static inline ExtcRcSlab *extc_rc_slabOf(void *p) {\n",
    "    return (ExtcRcSlab *)((uintptr_t)p & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1));\n",
    "}\n",
    "/* Slot index from an object pointer: not a shift -- the slot stride ss rounds to 8 bytes and is not a power of two\n",
    " * (an 80-byte object takes an 80-byte slot, avoiding the internal fragmentation of power-of-two rounding). This divides with **reciprocal multiply and shift**:\n",
    " * rcp = 2^42/ss + 1 gives a quotient error < 2^-22; off and ss are both multiples of 8, so the smallest nonzero fractional part is\n",
    " * 8/ss >= 2^-17, so the floor is always exact. Exhaustive in-domain criterion: tests/reclaim-perf/slotindex.c (wired into gate.sh),\n",
    " * which uses these two **emitted** functions directly instead of a second copy. */\n",
    "#define EXTC_RC_RCP_SHIFT 42\n",
    "__attribute__((unused)) static inline uint64_t extc_rc_rcpOf(size_t ss) {\n",
    "    return ((uint64_t)1 << EXTC_RC_RCP_SHIFT) / ss + 1;\n",
    "}\n",
    "/* Offset from a pointer to the payload start: **slot-head validation and indexing share one source** (computing it twice drifts). */\n",
    "__attribute__((unused)) static inline size_t extc_rc_offOf(const ExtcRcSlab *s, const void *p) {\n",
    "    return (size_t)((const char *)p - EXTC_RC_SLAB_DATA(s));\n",
    "}\n",
    "__attribute__((unused)) static inline size_t extc_rc_slotOfOff(const ExtcRcSlab *s, size_t off) {\n",
    "    return (size_t)(((uint64_t)off * s->rcp) >> EXTC_RC_RCP_SHIFT);\n",
    "}\n",
    "__attribute__((unused)) static inline size_t extc_rc_slotOf(ExtcRcSlab *s, void *p) {\n",
    "    return extc_rc_slotOfOff(s, extc_rc_offOf(s, p));\n",
    "}\n",
    "__attribute__((unused)) static inline uint64_t extc_rc_bit(size_t i) { return (uint64_t)1 << (i & 63); }\n",
    "__attribute__((unused)) static inline size_t extc_rc_word(size_t i) { return i >> 6; }\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_oops(const char *why) {\n",
    "    fprintf(stderr, \"trap: reclaim: %s\\n\", why);\n",
    "    exit(1);\n",
    "}\n",
    "\n",
    "/* ---- rc slab registry: only slots touched by extc_rc_alloc may be counted/marked [rt:slab] ----\n",
    " *\n",
    " * The language allows storing a pointer returned by a plate/pool/stack/C function into a reference slot (ref h.c, plate[..].data, the result of dl::sym).\n",
    " * Those pointers live in no slab; after slabOf's bitwise AND the read lands in unrelated memory (the plate's 4 GiB reservation\n",
    " * is not even committed), which segfaults outright.\n",
    " *\n",
    " * So every slab is entered into this table at creation and removed at release; counting and registration ask owns first.\n",
    " * The table is an open-addressing hash (linear probing, no tombstones): the key is the slab base (slabs are aligned to EXTC_RC_SLAB_SIZE,\n",
    " * so after dropping the low SLAB_BITS bits the bases cannot collide), and the cells hold slab pointers directly.\n",
    " * Add and remove are both O(1) amortized -- a sorted array would shift the upper half, and the shifted amount grows linearly with live blocks, so a whole-region release\n",
    " * would cost the square of the block count in total; the hash table has no such segment.\n",
    " * The common tier still goes through the direct-mapped hit cache below first (hit = take it, miss = probe).\n",
    " * Bump slabs are registered too: whether they qualify is decided by the occ bit (bump allocation does not set occ), so bump objects\n",
    " * are naturally excluded by owns. */\n",
    "/* Parallel safety: the registry is published per **generation**. The write side (slab create/release) is serialized under extc_rc_regLock;\n",
    " * readers (ownSlab / ownBig / slabOfInterior) are lock-free -- a reader atomically reads the current-generation pointer once, and the\n",
    " * (tab, cap, n) it obtained is always self-consistent. Growth = build a new generation then publish it; **old generations are never freed** (under parallelism another thread may\n",
    " * still be probing it; together, a few generations stay under twice the final table). After a probe misses, compare extc_rc_regSeq: if unchanged\n",
    " * the key really is not in the table; if changed, the read saw an old generation or an insert not yet published, so retry (see extc_rc_ownFind).\n",
    " * The write-side lock is touched only at slab create/release, never per allocation. */\n",
    "typedef struct ExtcRcReg { ExtcRcSlab **tab; size_t cap; size_t n; } ExtcRcReg;\n",
    "__attribute__((unused)) static ExtcRcReg extc_rc_ownReg0, extc_rc_bigReg0;      /* generation 0 (static) */\n",
    "__attribute__((unused)) static ExtcRcReg *extc_rc_ownCur = &extc_rc_ownReg0;    /* current generation: published pointer */\n",
    "static ExtcRcSlab **extc_rc_ownMirTab;   /* hot-path mirror: the current generation's tab (a hint only; a miss falls back to ownFind) */\n",
    "static size_t extc_rc_ownMirCap;         /* the current generation's cap; stored with RELEASE and read with ACQUIRE, so seeing the new cap implies seeing the new tab */\n",
    "__attribute__((unused)) static ExtcRcReg *extc_rc_bigCur = &extc_rc_bigReg0;\n",
    "__attribute__((unused)) static uint32_t extc_rc_regSeq;   /* incremented on every add/remove/generation change: readers use it to detect retries */\n",
    "__attribute__((unused)) static int extc_rc_regLock;\n",
    "__attribute__((unused)) static inline void extc_rc_regLockAcq(void) {\n",
    "    while (__atomic_exchange_n(&extc_rc_regLock, 1, __ATOMIC_ACQUIRE)) { }\n",
    "}\n",
    "__attribute__((unused)) static inline void extc_rc_regUnlock(void) {\n",
    "    __atomic_store_n(&extc_rc_regLock, 0, __ATOMIC_RELEASE);\n",
    "}\n",
    "/* The registry's **hit cache** (direct-mapped, fixed capacity): a cell is a hit when it holds exactly a slab base.\n",
    " *\n",
    " * Why it exists: `ownSlab` is on the hot path of inc/dec/register/marking, and those shapes have only a\n",
    " * few slabs, so every probe recomputes on the same few addresses. The hit cache turns the \"common\" tier into one array read;\n",
    " * misses and collisions always fall back to registry probing, so **the result is word-for-word the same as with no cache** (the cache affects speed only, never the decision).\n",
    " *\n",
    " * Covers normal slabs only: a huge block's payload is malloc'd separately and located through the huge-block table, unrelated to this.\n",
    " * A cell stores the slab pointer itself; deletion clears only a cell that still holds exactly this slab,\n",
    " * so a cell overwritten by a later slab never wipes someone else's entry, and no cell keeps a released slab. */\n",
    "#define EXTC_RC_OWNMAP_BITS 12\n",
    "#define EXTC_RC_OWNMAP_SIZE (1u << EXTC_RC_OWNMAP_BITS)\n",
    "__attribute__((unused)) static ExtcRcSlab *extc_rc_ownMap[EXTC_RC_OWNMAP_SIZE];\n",
    "/* One \"last block\" cache: `ownMap`'s hit path still hashes and indexes (on real shapes that is the\n",
    " * bulk of the cache misses). This reuses the last verified slab by **base equality** -- semantically identical to no cache: a hit still passes\n",
    " * slot-boundary validation, and a failed check still falls back to `ownBig`. It must be cleared when a slab is released (see `ownDel`). */\n",
    "/* Last-block cache: **thread-local**. Parallel workers each have their own slab set; sharing it would let one thread\n",
    " * treat another thread's region object as a slab of this thread (a wrong decision across the region boundary). */\n",
    "static _Thread_local ExtcRcSlab *extc_rc_ownHot;\n",
    "__attribute__((unused)) static size_t extc_rc_ownHashOf(const void *base) {\n",
    "    return (size_t)(((uintptr_t)base >> EXTC_RC_SLAB_BITS) * 2654435761u)\n",
    "           & (EXTC_RC_OWNMAP_SIZE - 1);\n",
    "}\n",
    "\n",
    "/* Table key: the base address itself for a normal slab; the payload address (s->data) for a huge block. */\n",
    "__attribute__((unused)) static const void *extc_rc_ownKeyOf(const ExtcRcSlab *s) {\n",
    "    return s->big ? (const void *)s->data : (const void *)s;\n",
    "}\n",
    "/* Probe start cell: a normal slab's key is SLAB_BITS-aligned, a huge block's key is 16-byte aligned by malloc;\n",
    " * the two alignments are shifted accordingly, multiplied by the Knuth constant, and the low log2(cap) bits taken (capacity is a power of two). */\n",
    "__attribute__((unused)) static size_t extc_rc_ownProbeOf(const void *key, int big, size_t cap) {\n",
    "    uintptr_t h = big ? ((uintptr_t)key >> 4) : ((uintptr_t)key >> EXTC_RC_SLAB_BITS);\n",
    "    return (size_t)(h * 2654435761u) & (cap - 1);\n",
    "}\n",
    "/* Probe: returns the address of \"the cell holding this key\" or \"the empty cell it should occupy when inserted\". Load factor <= 1/2, so a probe\n",
    " * always meets an empty cell and never wraps a whole lap. */\n",
    "__attribute__((unused)) static ExtcRcSlab **extc_rc_ownSlotOf(ExtcRcSlab **tab, size_t cap,\n",
    "                                                              const void *key, int big) {\n",
    "    size_t i = extc_rc_ownProbeOf(key, big, cap);\n",
    "    while (tab[i] && extc_rc_ownKeyOf(tab[i]) != key) i = (i + 1) & (cap - 1);\n",
    "    return &tab[i];\n",
    "}\n",
    "/* Rehash: double the capacity (an empty table starts at 64 / 16) and re-probe the current generation's entries into the new table under the new mask.\n",
    " * Old generations are **never freed**: under parallelism another thread may still be probing one (a published pointer read before growth).\n",
    " * Publishing is done by the caller under the lock (see ownAdd / ownDel); this only builds the new generation. */\n",
    "__attribute__((unused)) static ExtcRcReg *extc_rc_ownNextReg(ExtcRcReg *cur, int big) {\n",
    "    size_t oc = cur->cap, nc = oc ? oc * 2 : (big ? 16u : 64u);\n",
    "    ExtcRcReg *nr = (ExtcRcReg *)calloc(1, sizeof *nr);\n",
    "    ExtcRcSlab **nt = (ExtcRcSlab **)calloc(nc, sizeof *nt);\n",
    "    if (!nr || !nt) extc_rc_oops(\"slab registry allocation failed\");\n",
    "    for (size_t i = 0; i < oc; i++) {\n",
    "        if (!cur->tab[i]) continue;\n",
    "        size_t j = extc_rc_ownProbeOf(extc_rc_ownKeyOf(cur->tab[i]), big, nc);\n",
    "        while (nt[j]) j = (j + 1) & (nc - 1);\n",
    "        nt[j] = cur->tab[i];\n",
    "    }\n",
    "    nr->tab = nt; nr->cap = nc; nr->n = cur->n;\n",
    "    return nr;\n",
    "}\n",
    "/* Backshift after deletion: linear probing has no tombstones, so deleting a cell means moving the later entries of the probe chain back,\n",
    " * otherwise a lookup stops early at the hole. Move condition (Knuth): the entry's start cell is not on the circular\n",
    " * run from \"hole i to its position j\", so a lookup starting from its start cell would still meet i first. */\n",
    "__attribute__((unused)) static void extc_rc_ownErase(ExtcRcSlab **tab, size_t cap,\n",
    "                                                     size_t i, int big) {\n",
    "    size_t j = i;\n",
    "    for (;;) {\n",
    "        j = (j + 1) & (cap - 1);\n",
    "        if (!tab[j]) break;\n",
    "        size_t h = extc_rc_ownProbeOf(extc_rc_ownKeyOf(tab[j]), big, cap);\n",
    "        int move = (i <= j) ? (h <= i || h > j) : (h <= i && h > j);\n",
    "        if (move) { tab[i] = tab[j]; i = j; }\n",
    "    }\n",
    "    tab[i] = (ExtcRcSlab *)0;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_ownAdd(ExtcRcSlab *s) {\n",
    "    extc_rc_regLockAcq();\n",
    "    if (s->big) {   /* huge blocks are registered by payload address in the second table */\n",
    "        ExtcRcReg *rg = extc_rc_bigCur;\n",
    "        if (!rg->cap || (rg->n + 1) * 2 > rg->cap) {\n",
    "            rg = extc_rc_ownNextReg(rg, 1);\n",
    "            __atomic_store_n(&extc_rc_bigCur, rg, __ATOMIC_RELEASE);\n",
    "        }\n",
    "        *extc_rc_ownSlotOf(rg->tab, rg->cap, s->data, 1) = s;\n",
    "        rg->n++;\n",
    "        __atomic_fetch_add(&extc_rc_regSeq, 1, __ATOMIC_RELEASE);\n",
    "        extc_rc_regUnlock();\n",
    "        return;\n",
    "    }\n",
    "    ExtcRcReg *rg = extc_rc_ownCur;\n",
    "    if (!rg->cap || (rg->n + 1) * 2 > rg->cap) {\n",
    "        rg = extc_rc_ownNextReg(rg, 0);\n",
    "        __atomic_store_n(&extc_rc_ownCur, rg, __ATOMIC_RELEASE);\n",
    "        __atomic_store_n(&extc_rc_ownMirTab, rg->tab, __ATOMIC_RELAXED);\n",
    "        __atomic_store_n(&extc_rc_ownMirCap, rg->cap, __ATOMIC_RELEASE);\n",
    "    }\n",
    "    *extc_rc_ownSlotOf(rg->tab, rg->cap, s, 0) = s;\n",
    "    rg->n++;\n",
    "    extc_rc_ownMap[extc_rc_ownHashOf(s)] = s;   /* hit cache: overwrites a colliding entry, but does not affect the decision */\n",
    "    __atomic_fetch_add(&extc_rc_regSeq, 1, __ATOMIC_RELEASE);\n",
    "    extc_rc_regUnlock();\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_ownDel(ExtcRcSlab *s) {\n",
    "    extc_rc_regLockAcq();\n",
    "    if (s->big) {\n",
    "        ExtcRcReg *rg = extc_rc_bigCur;\n",
    "        if (rg->cap) {\n",
    "            ExtcRcSlab **slot = extc_rc_ownSlotOf(rg->tab, rg->cap, s->data, 1);\n",
    "            if (*slot == s) {\n",
    "                extc_rc_ownErase(rg->tab, rg->cap, (size_t)(slot - rg->tab), 1);\n",
    "                rg->n--;\n",
    "            }\n",
    "        }\n",
    "        __atomic_fetch_add(&extc_rc_regSeq, 1, __ATOMIC_RELEASE);\n",
    "        extc_rc_regUnlock();\n",
    "        return;\n",
    "    }\n",
    "    if (extc_rc_ownHot == s) extc_rc_ownHot = (ExtcRcSlab *)0;\n",
    "    ExtcRcReg *rg = extc_rc_ownCur;\n",
    "    if (rg->cap) {\n",
    "        ExtcRcSlab **slot = extc_rc_ownSlotOf(rg->tab, rg->cap, s, 0);\n",
    "        if (*slot == s) {\n",
    "            extc_rc_ownErase(rg->tab, rg->cap, (size_t)(slot - rg->tab), 0);\n",
    "            rg->n--;\n",
    "        }\n",
    "    }\n",
    "    if (extc_rc_ownMap[extc_rc_ownHashOf(s)] == s)\n",
    "        extc_rc_ownMap[extc_rc_ownHashOf(s)] = (ExtcRcSlab *)0;\n",
    "    __atomic_fetch_add(&extc_rc_regSeq, 1, __ATOMIC_RELEASE);\n",
    "    extc_rc_regUnlock();\n",
    "}\n",
    "\n",
    "/* Look up a key in the registry: **lock-free reader**. The write side may be rehashing or inserting, so after a probe misses, check extc_rc_regSeq:\n",
    " * unchanged means this is the current generation and the key really is not in the table; changed means the read saw an old generation or an insert not yet published\n",
    " * so retry. The (tab, cap) obtained from one published-pointer read is always self-consistent, so a \"new table with old capacity\" out-of-bounds access cannot happen.\n",
    " * After the retry bound, take the lock and check once more: only a few dozen races with the write side ever get there. */\n",
    "/* Cold path (reached only on a fast-probe miss or a concurrent generation change): marked noinline -- inlining it into the three hot paths would bloat them; chase is 1.6% more Ir. */\n",
    "__attribute__((unused, noinline)) static ExtcRcSlab *extc_rc_ownFind(const void *key, int big) {\n",
    "    for (int tries = 0;; tries++) {\n",
    "        uint32_t seq = __atomic_load_n(&extc_rc_regSeq, __ATOMIC_ACQUIRE);\n",
    "        ExtcRcReg *rg = __atomic_load_n(big ? &extc_rc_bigCur : &extc_rc_ownCur, __ATOMIC_ACQUIRE);\n",
    "        if (rg->cap) {\n",
    "            ExtcRcSlab *s = *extc_rc_ownSlotOf(rg->tab, rg->cap, key, big);\n",
    "            if (s) return s;   /* skip:reg-hit */\n",
    "        }\n",
    "        if (seq == __atomic_load_n(&extc_rc_regSeq, __ATOMIC_ACQUIRE)) return (ExtcRcSlab *)0;   /* skip:reg-settled */\n",
    "        if (tries >= 32) break;   /* skip:reg-race */\n",
    "    }\n",
    "    extc_rc_regLockAcq();\n",
    "    ExtcRcReg *rg = __atomic_load_n(big ? &extc_rc_bigCur : &extc_rc_ownCur, __ATOMIC_ACQUIRE);\n",
    "    ExtcRcSlab *s = rg->cap ? *extc_rc_ownSlotOf(rg->tab, rg->cap, key, big) : (ExtcRcSlab *)0;\n",
    "    extc_rc_regUnlock();\n",
    "    return s;\n",
    "}\n",
    "/* Hot-path mirror: the current generation's (tab, cap) exposed as two globals. A fast probe then needs only two global reads (same as before the concurrency rework),\n",
    " * instead of reading the generation pointer and dereferencing it twice. Publication order is tab before cap (cap stored with RELEASE), readers read cap with ACQUIRE,\n",
    " * so \"seeing the new cap\" always means seeing the new tab; on the old cap both the old and new tab fit (a generation only grows), so no out-of-bounds.\n",
    " * The mirror is only a **hint**: a probe miss always falls back to extc_rc_ownFind's seq protocol, and reading a stale one never mistakes \"not in the table\". */\n",
    "/* Lock-free fast probe: the hot path comes here first. On a miss, use seq to tell \"authoritatively absent\" from \"the write side just moved\"; only the latter calls ownFind. */\n",
    "__attribute__((unused)) static inline ExtcRcSlab *extc_rc_ownProbeFast(const void *key, int big) {\n",
    "    if (big) {\n",
    "        ExtcRcReg *rg = __atomic_load_n(&extc_rc_bigCur, __ATOMIC_ACQUIRE);\n",
    "        if (!rg->cap) return (ExtcRcSlab *)0;   /* skip:lookup-probe */\n",
    "        return *extc_rc_ownSlotOf(rg->tab, rg->cap, key, 1);\n",
    "    }\n",
    "    /* Hot path: two global reads probe one cell (equivalent to before the concurrency rework).\n",
    "     * A miss has two causes: really not an rc slot (the common case: an arena pointer in a conservative scan), or the write side just inserted/rehashed and was not seen yet.\n",
    "     * extc_rc_regSeq distinguishes them: unchanged before and after the probe means the miss is authoritative, return 0 directly (no function call);\n",
    "     * changed, fall back to extc_rc_ownFind's seq retry protocol. */\n",
    "    uint32_t s0 = __atomic_load_n(&extc_rc_regSeq, __ATOMIC_ACQUIRE);\n",
    "    size_t cap = extc_rc_ownMirCap;\n",
    "    ExtcRcSlab *s = cap ? *extc_rc_ownSlotOf(extc_rc_ownMirTab, cap, key, 0) : (ExtcRcSlab *)0;\n",
    "    if (s || __atomic_load_n(&extc_rc_regSeq, __ATOMIC_ACQUIRE) == s0) return s;   /* skip:lookup-probe */\n",
    "    return extc_rc_ownFind(key, 0);\n",
    "}\n",
    "\n",
    "/* If this pointer lands in a **registered rc slab** and is exactly a slot head, return that slab, else 0.\n",
    " *\n",
    " * A normal slab uses its own alignment relation (one bitwise AND + one registry probe), so this path has the same instruction count as\n",
    " * without huge blocks; only huge blocks (payload not in an aligned block) fall to exact matching in the second table; they have\n",
    " * one slot and accept only the slot head. Both paths accept only slot heads: a pointer into an object always returns 0 (the next soundness obligation). */\n",
    "__attribute__((unused)) static ExtcRcSlab *extc_rc_ownBig(void *p) {\n",
    "    ExtcRcReg *rg = __atomic_load_n(&extc_rc_bigCur, __ATOMIC_ACQUIRE);\n",
    "    if (!rg->cap) return (ExtcRcSlab *)0;   /* skip:lookup-probe */\n",
    "    /* Same protocol as the normal table's fast probe: read seq, probe a cell, read seq again on a miss -- unchanged means\n",
    "     * \"authoritatively absent\" (really not a huge block); changed means the write side just inserted/rehashed, so use ownFind's retry.\n",
    "     * Without this check, under parallelism a **just-registered** huge block could be treated as \"not in the table\", hence as outside the region\n",
    "     * (the conservative direction: retain more, never miss a collection), but that is an accidental behavior difference, not the design. */\n",
    "    uint32_t s0 = __atomic_load_n(&extc_rc_regSeq, __ATOMIC_ACQUIRE);\n",
    "    ExtcRcSlab *s = *extc_rc_ownSlotOf(rg->tab, rg->cap, p, 1);\n",
    "    if (!s && __atomic_load_n(&extc_rc_regSeq, __ATOMIC_ACQUIRE) != s0) s = extc_rc_ownFind(p, 1);\n",
    "    if (!s) return (ExtcRcSlab *)0;   /* skip:lookup-probe */\n",
    "    return (uintptr_t)s->data == (uintptr_t)p ? s : (ExtcRcSlab *)0;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static inline ExtcRcSlab *extc_rc_ownSlab(void *p) {\n",
    "    /* A null pointer is not checked separately: p == 0 means base == 0, and no key 0 exists in the map cell, registry or huge-block table\n",
    "     * (neither a slab base nor a huge-block payload address can be 0), so every probe level misses and ownBig returns 0 too;\n",
    "     * the result is identical byte for byte to an explicit check, minus one comparison per call (2 Ir on the hot path). */\n",
    "    void *base = (void *)((uintptr_t)p & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1));\n",
    "    ExtcRcSlab *hot = extc_rc_ownHot;\n",
    "    if (hot && (void *)hot == base) {          /* skip:own-hot */\n",
    "        size_t off = extc_rc_offOf(hot, p);\n",
    "        size_t k = extc_rc_slotOfOff(hot, off);\n",
    "        if (k < hot->nslots && k * hot->ss == off) return hot; /* skip:own-hot */\n",
    "        return extc_rc_ownBig(p);\n",
    "    }\n",
    "    ExtcRcSlab *s = extc_rc_ownMap[extc_rc_ownHashOf(base)];\n",
    "    /* `s` must be nonzero: `base` can be 0 (a small non-pointer integer sitting in a field, which `unlinkChildren` reads\n",
    "     * as a candidate reference) -- the empty map cell is 0 too, so \"equal\" is not \"hit\". */\n",
    "    if (s && (void *)s == base) {            /* hit: s is exactly slabOf(p) */\n",
    "        size_t off = extc_rc_offOf(s, p);\n",
    "        size_t k = extc_rc_slotOfOff(s, off);\n",
    "        if (k < s->nslots && k * s->ss == off) { extc_rc_ownHot = s; return s; }   /* skip:lookup-probe */\n",
    "        return extc_rc_ownBig(p);\n",
    "    }\n",
    "    {   /* miss/collision: probe the registry (open addressing), semantics identical to \"take the candidate then validate\" */\n",
    "        s = extc_rc_ownProbeFast(base, 0);\n",
    "        if (s) {\n",
    "            size_t off = extc_rc_offOf(s, p);\n",
    "            size_t k = extc_rc_slotOfOff(s, off);\n",
    "            if (k < s->nslots && k * s->ss == off) { extc_rc_ownHot = s; return s; }   /* skip:lookup-probe */\n",
    "        }\n",
    "    }\n",
    "    return extc_rc_ownBig(p);\n",
    "}\n",
    "/* A slab-of copy dedicated to the marking step: the body is **word-for-word the same** as the other one, only forced inline.\n",
    " *\n",
    " * Why copy instead of marking the other one always_inline: that path would inline it at **every** call site,\n",
    " * and shapes like cross_region lose two tenths when bloated elsewhere (register pressure); see the\n",
    " * corresponding docs/changelog entry. The marking step is the hottest call site in the runtime, so it alone gets a copy.\n",
    " *\n",
    " * The two bodies must stay word-for-word identical: tools/check_ownslab_body.py compares them after normalizing the function name,\n",
    " * so changing one and forgetting the other turns the battery red. */\n",
    "__attribute__((unused)) static inline __attribute__((always_inline)) ExtcRcSlab *extc_rc_ownSlabMark(void *p) {\n",
    "    /* A null pointer is not checked separately: p == 0 means base == 0, and no key 0 exists in the map cell, registry or huge-block table\n",
    "     * (neither a slab base nor a huge-block payload address can be 0), so every probe level misses and ownBig returns 0 too,\n",
    "     * the result is identical byte for byte to an explicit check, minus one comparison per call (2 Ir on the hot path). */\n",
    "    void *base = (void *)((uintptr_t)p & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1));\n",
    "    ExtcRcSlab *hot = extc_rc_ownHot;\n",
    "    if (hot && (void *)hot == base) {          /* skip:own-hot */\n",
    "        size_t off = extc_rc_offOf(hot, p);\n",
    "        size_t k = extc_rc_slotOfOff(hot, off);\n",
    "        if (k < hot->nslots && k * hot->ss == off) return hot; /* skip:own-hot */\n",
    "        return extc_rc_ownBig(p);\n",
    "    }\n",
    "    ExtcRcSlab *s = extc_rc_ownMap[extc_rc_ownHashOf(base)];\n",
    "    /* `s` must be nonzero: `base` can be 0 (a small non-pointer integer sitting in a field, which `unlinkChildren` reads\n",
    "     * as a candidate reference) -- the empty map cell is 0 too, so \"equal\" is not \"hit\". */\n",
    "    if (s && (void *)s == base) {            /* hit: s is exactly slabOf(p) */\n",
    "        size_t off = extc_rc_offOf(s, p);\n",
    "        size_t k = extc_rc_slotOfOff(s, off);\n",
    "        if (k < s->nslots && k * s->ss == off) { extc_rc_ownHot = s; return s; }   /* skip:lookup-probe */\n",
    "        return extc_rc_ownBig(p);\n",
    "    }\n",
    "    {   /* miss/collision: probe the registry (open addressing), semantics identical to \"take the candidate then validate\" */\n",
    "        s = extc_rc_ownProbeFast(base, 0);\n",
    "        if (s) {\n",
    "            size_t off = extc_rc_offOf(s, p);\n",
    "            size_t k = extc_rc_slotOfOff(s, off);\n",
    "            if (k < s->nslots && k * s->ss == off) { extc_rc_ownHot = s; return s; }   /* skip:lookup-probe */\n",
    "        }\n",
    "    }\n",
    "    return extc_rc_ownBig(p);\n",
    "}\n",
    "\n",
    "/* An rc-allocated slot that is **still occupied** is the only thing allowed to be counted/registered/marked. */\n",
    "__attribute__((unused)) static int extc_rc_owns(void *p) {\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(p);\n",
    "    if (!s) return 0;   /* skip:not-own */\n",
    "    size_t k = extc_rc_slotOf(s, p);\n",
    "    return (s->occ[extc_rc_word(k)] & extc_rc_bit(k)) != 0;\n",
    "}\n",
    "\n",
    "/* Slot size: round up in **8-byte** units, at least enough for the 8-byte slot head of the free chain.\n",
    " * Not a power of two: power-of-two rounding makes an 80-byte object take a 128-byte slot (+60% internal fragmentation);\n",
    " * rounding by 8 means a batch of payloads leaves no remainder per stride (a 24-byte object takes 24 bytes, not 8 more).\n"
    " * 8 is **sufficient** granularity: the largest natural alignment in the language is 8 -- the builtin types are only i8..i64 / u8..u64 / f32 / f64 / bool\n"
    " * (BUILTIN_NAMES in src/types/types.c), and structs / enums / arrays / references / function pointers / dyn are all built from them\n"
    " * (there are no vector or 128-bit kinds in TypeKind in src/ast/ast.h), so no payload needs a larger alignment;\n"
    " * slot indexing uses reciprocal multiply and shift (see extc_rc_rcpOf), which does not require a power-of-two stride anyway. */\n",
    "/* Why force inline: an allocation site often has a constant n (sizeof a type); after inlining the slot stride here is a constant, so\n",
    " * `memset(p, 0, ss)` can expand into fixed-length inline stores instead of a libc call per allocation;\n",
    " * dynamic-n call sites also save a call/return (criterion: check_slot_unit pins the signature and the slot-size rule). */\n",
    "__attribute__((unused)) static inline __attribute__((always_inline)) size_t extc_rc_slotSize(size_t n) {\n",
    "    size_t s = (n + 7) & ~(size_t)7;\n",
    "    if (s <= 16 && n > 16) extc_rc_oops(\"slot size overflow\");   /* only possible if n itself overflowed */\n",
    "    return s > 16 ? s : 16;\n",
    "}\n",
    "\n",
    "/* Type number: register a descriptor into this slab's small type table and return the per-slot number (see ExtcRcSlab's tid).\n",
    " * Deduplicated by **pointer equality** -- a descriptor is a block-scope static const emitted by the allocation site, unique for the whole process\n",
    " * and never moves, so one comparison suffices. If the table is full (65k distinct descriptors crammed into one slab) it traps: silently falling back to 0\n",
    " * would make marking skip this object's reference fields, hence free it early -- an **unsafe** direction; better to fail loudly on the spot.\n",
    " *\n",
    " * Deduplicated lookup has two paths: a slab with few descriptors (the common case: one size class usually gets one or two allocation sites) scans linearly;\n",
    " * past EXTC_RC_TTAB_LINEAR_MAX a 16-bit open-addressing index is built (descriptor pointer to ttab index),\n",
    " * after which every allocation is O(1) and independent of the number of types this slab has seen -- when generic monomorphization crams a thousand allocation sites into\n",
    " * one size class, the linear scan becomes dozens of instructions per allocation. */\n",
    "#define EXTC_RC_TTAB_LINEAR_MAX 8u\n",
    "__attribute__((unused)) static size_t extc_rc_ttabProbeOf(const ExtcRcType *td, size_t cap) {\n",
    "    return (size_t)(((uintptr_t)td >> 3) * 2654435761u) & (cap - 1);\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_ttabIndexBuild(ExtcRcSlab *s, size_t cap) {\n",
    "    uint16_t *nt = (uint16_t *)calloc(cap, sizeof *nt);\n",
    "    if (!nt) extc_rc_oops(\"slab type index allocation failed\");\n",
    "    for (uint32_t k = 2; k < s->ttabN; k++) {\n",
    "        size_t i = extc_rc_ttabProbeOf(s->ttab[k], cap);\n",
    "        while (nt[i]) i = (i + 1) & (cap - 1);\n",
    "        nt[i] = (uint16_t)k;\n",
    "    }\n",
    "    free(s->thash);\n",
    "    s->thash = nt;\n",
    "    s->thashCap = (uint32_t)cap;\n",
    "}\n",
    "__attribute__((unused)) static uint16_t extc_rc_typeIdxSlow(ExtcRcSlab *s, const ExtcRcType *td) {\n",
    "    if (s->thash) {   /* index built: one probe (load factor <= 1/2, so an empty cell exists) */\n",
    "        size_t i = extc_rc_ttabProbeOf(td, s->thashCap);\n",
    "        while (s->thash[i]) {\n",
    "            uint16_t k = s->thash[i];\n",
    "            if (s->ttab[k] == td) return k;   /* skip:ttab-hit */\n",
    "            i = (i + 1) & (s->thashCap - 1);\n",
    "        }\n",
    "    } else {\n",
    "        for (uint32_t k = 2; k < s->ttabN; k++) if (s->ttab[k] == td) return (uint16_t)k;\n",
    "    }\n",
    "    if (s->ttabN == 0xFFFFu) extc_rc_oops(\"slab type table overflow\");\n",
    "    if (s->ttabN == s->ttabCap) {\n",
    "        uint32_t nc = s->ttabCap * 2;\n",
    "        const ExtcRcType **nt = (const ExtcRcType **)realloc(s->ttab, nc * sizeof *nt);\n",
    "        if (!nt) extc_rc_oops(\"slab type table allocation failed\");\n",
    "        s->ttab = nt;\n",
    "        s->ttabCap = nc;\n",
    "    }\n",
    "    uint16_t k = (uint16_t)s->ttabN;\n",
    "    s->ttab[k] = td;\n",
    "    s->ttabN++;\n",
    "    if (!s->thash) {\n",
    "        if (s->ttabN - 2u > EXTC_RC_TTAB_LINEAR_MAX) extc_rc_ttabIndexBuild(s, 32u);\n",
    "    } else if (s->ttabN - 2u > s->thashCap / 2u) {\n",
    "        extc_rc_ttabIndexBuild(s, (size_t)s->thashCap * 2u);\n",
    "    } else {\n",
    "        size_t i = extc_rc_ttabProbeOf(td, s->thashCap);\n",
    "        while (s->thash[i]) i = (i + 1) & (s->thashCap - 1);\n",
    "        s->thash[i] = k;\n",
    "    }\n",
    "    return k;\n",
    "}\n",
    "__attribute__((unused)) static inline uint16_t extc_rc_typeIdx(ExtcRcSlab *s, const ExtcRcType *td) {\n",
    "    if (!td) return 0;   /* data object: no reference fields to walk */   /* skip:no-desc */\n",
    "    if (td == s->lastTd) return s->lastTid;   /* skip:type-hot */\n",
    "    /* Number 1 is always the fallback descriptor, bypassing the table lookup. */\n",
    "    uint16_t k = (uint16_t)(td == EXTC_RC_CONSERVATIVE ? 1u : (uint32_t)extc_rc_typeIdxSlow(s, td));\n",
    "    s->lastTd = td;   /* filled after the table insert succeeds: consecutive same-type allocations on one slab look up only the first */\n",
    "    s->lastTid = k;\n",
    "    return k;\n",
    "}\n",
    "/* Number to descriptor. Number 0 is null (no reference fields). Each slot stores only 2 bytes, at the cost of one extra table read here;\n",
    " * the table usually has one or two entries, and the mark/release paths walk the pointer fields by descriptor anyway. */\n",
    "__attribute__((unused)) static inline const ExtcRcType *extc_rc_typeOf(const ExtcRcSlab *s, size_t i) {\n",
    "    uint16_t k = s->tid[i];\n",
    "    return k ? s->ttab[k] : (const ExtcRcType *)0;\n",
    "}\n",
    "\n",
    "/* Allocate a slab.\n",
    " *\n",
    " * Slots round to 8 bytes. A slab's **issued capacity** (cap x slot size) follows the slot size: the block size starts at\n",
    " * EXTC_RC_SLAB_CHUNK_MIN and doubles until it holds EXTC_RC_SLAB_SLOTS_MIN slots or reaches\n",
    " * EXTC_RC_SLAB_SIZE -- alignment and \"finding the slab from a pointer is one bitwise AND\" still hold; the only difference is how many slots\n",
    " * each slab issues (with a fixed 1 MiB, every size class wasted up to 1 MiB). When a slot is too big for one slab\n",
    " * to hold two (slot > (1 MiB - header)/2 ~ 512 KiB) it does **not** trap: the header stays, the payload is malloc'd\n",
    " * separately and nslots = 1 -- call it a **huge block**. It is not a second reclaim path: bitmaps, per-slot type descriptor,\n",
    " * holder count, cross-region registration, marking and sweeping all go through the functions above; the only difference is **where the payload is**\n",
    " * (`EXTC_RC_SLAB_DATA`). So a huge block is neither swept as garbage nor missed. */\n",
    "__attribute__((unused)) static ExtcRcSlab *extc_rc_slabNew(ExtcRcRegion *r, size_t slotSize) {\n",
    "    EXTC_RC_TICK(4);   /* per-component timing (`EXTC_RC_TIME=1`) */\n",
    "    size_t chunk = EXTC_RC_SLAB_CHUNK_MIN;\n",
    "    /* Configuration may set the block size below CHUNK_MIN (EXTC_RC_SLAB_BITS < 16): clamp the start into the block first,\n",
    "     * otherwise chunk can be no smaller than the block size and cap would compute more slots than the block holds, writing out of bounds. */\n",
    "    if (chunk > EXTC_RC_SLAB_SIZE) chunk = EXTC_RC_SLAB_SIZE;\n",
    "    while (chunk < EXTC_RC_SLAB_SIZE && chunk / slotSize < EXTC_RC_SLAB_SLOTS_MIN)\n",
    "        chunk <<= 1;   /* cold path, at most 4 times; compare by division to avoid overflow in the slotSize product */\n",
    "    size_t cap = (chunk - EXTC_RC_SLAB_HDR) / slotSize;\n",
    "    int big = (cap < 2);   /* fewer than two fit, so the payload is malloc'd separately and the slab holds 1 slot */\n",
    "    ExtcRcSlab *s;\n",
    "    size_t nslots;\n",
    "    if (big) {\n",
    "        s = (ExtcRcSlab *)calloc(1, sizeof(ExtcRcSlab));\n",
    "        if (!s) extc_rc_oops(\"oversized slot header allocation failed\");\n",
    "        s->data = (char *)malloc(slotSize);\n",
    "        if (!s->data) extc_rc_oops(\"oversized slot allocation failed\");\n",
    "        nslots = 1;\n",
    "    } else {\n",
    "        s = (ExtcRcSlab *)aligned_alloc(EXTC_RC_SLAB_SIZE, EXTC_RC_SLAB_SIZE);\n",
    "        if (!s) extc_rc_oops(\"slab allocation failed\");\n",
    "        memset(s, 0, EXTC_RC_SLAB_HDR);\n",
    "        s->data = (char *)s + EXTC_RC_SLAB_HDR;\n",
    "        nslots = cap;\n",
    "    }\n",
    "    s->region = r;\n",
    "    s->big = big;\n",
    "    s->ss = slotSize;\n",
    "    s->rcp = extc_rc_rcpOf(slotSize);\n",
    "    s->nslots = (uint32_t)nslots;\n",
    "    if (s->nslots > EXTC_RC_REUSE_MAX_SLOT)\n",
    "        extc_rc_oops(\"slab slot count exceeds the reuse-chain encoding limit\");\n",
    "    s->nwords = (uint32_t)((nslots + 63) / 64);\n",
    "/* The three bitmaps are **traversed in order as a whole** (mark / sweep / whole-region drop), so they must be cleared wholesale: calloc.\n",
    " * The two 16-bit per-slot arrays are the opposite: **only occupied slots are read** (every accessor checks occ first), so malloc them and\n",
    " * clear per slot at allocation time -- calloc clears the whole span eagerly, and when it lands on the heap (only a large mapping goes through mmap lazily)\n",
    " * those hundreds of KB in small shapes become RSS at once. */\n",
    "    s->occ   = (uint64_t *)calloc(s->nwords, sizeof(uint64_t));\n",
    "    s->mark  = (uint64_t *)calloc(s->nwords, sizeof(uint64_t));\n",
    "    s->rsbit = (uint64_t *)calloc(s->nwords, sizeof(uint64_t));\n",
    "/* `hold` (the 2-byte per-slot holder count) is needed only **with counting on**; with counting off it is pure overhead\n",
    " * (~29k instructions on a slab of 16 B slots). When off, not even the pointer is allocated. */\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "    s->hold  = (uint16_t *)malloc(nslots * sizeof(uint16_t));\n",
    "#endif\n",
    "    s->tid   = (uint16_t *)malloc(nslots * sizeof(uint16_t));\n",
    "    s->ttabCap = 8;\n",
    "    s->ttabN = 2;\n",
    "    s->ttab  = (const ExtcRcType **)calloc(s->ttabCap, sizeof(ExtcRcType *));\n",
    "    if (s->ttab) s->ttab[1] = EXTC_RC_CONSERVATIVE;   /* number 1 is fixed: the fallback descriptor */\n",
    "#if EXTC_RC_NOCOUNT\n",
    "    if (!s->occ || !s->mark || !s->rsbit || !s->tid || !s->ttab)\n",
    "#else\n",
    "    if (!s->occ || !s->mark || !s->rsbit || !s->hold || !s->tid || !s->ttab)\n",
    "#endif\n",
    "        extc_rc_oops(\"slab metadata allocation failed\");\n",
    "/* **Not** pre-chaining the whole block into the free list: a slab can have many slots, and chaining costs more than a whole round of\n",
    " * allocation for most programs -- a small load would pay a huge fixed cost per slab creation.\n",
    " * Instead \"never-issued slots go through bump, only released slots enter freelist\": the chain is maintained only on real reuse.\n",
    " *\n",
    " * Chunked refill (push `EXTC_RC_CHUNK` slots when the chain empties) is the alternative: it saves a few pointer hops on heavy shapes,\n",
    " * but both judged metrics are slightly worse, so under the ratchet rule (tighten only) this version stays. */\n",
    "    s->freelist = -1;   /* empty head: the chain's next slot number lives in each slot's tid[] (see extc_rc_freeSlot) */\n",
    "    s->bump = 0;\n",
    "    extc_rc_ownAdd(s);        /* from this moment the slab's slots may be counted/marked */\n",
    "    return s;\n",
    "}\n",
    "\n",
    "/* Size-class hash: the key is ss / 8, multiplied by the Knuth constant, taking the **high 5 bits** as the bucket. The low bits\n",
    " * (ss/8 = 2,4,6...) distribute poorly for consecutive small keys, so they are not used. */\n",
    "__attribute__((unused)) static size_t extc_rc_classBucket(size_t ss) {\n",
    "    return (size_t)(((uint64_t)(ss >> 3) * 0x9E3779B97F4A7C15ull) >> 59);\n",
    "}\n",
    "/* Look up a size class; create one on the spot when none was allocated (cold path, one malloc per size class). */\n",
    "__attribute__((unused)) static ExtcRcClass *extc_rc_classNeed(ExtcRcRegion *r, size_t ss) {\n",
    "    size_t b = extc_rc_classBucket(ss);\n",
    "    ExtcRcClass *c = r->clsBkt[b];\n",
    "    while (c && c->ss != ss) c = c->next;\n",
    "    if (!c) {\n",
    "        c = (ExtcRcClass *)calloc(1, sizeof(ExtcRcClass));\n",
    "        if (!c) extc_rc_oops(\"size-class entry allocation failed\");\n",
    "        c->ss = ss;\n",
    "        c->next = r->clsBkt[b];\n",
    "        r->clsBkt[b] = c;\n",
    "    }\n",
    "    return c;\n",
    "}\n",
    "/* Look up without creating: the allocation fallback uses it. NULL means this size class has no block yet. */\n",
    "__attribute__((unused)) static ExtcRcClass *extc_rc_classSlot(const ExtcRcRegion *r, size_t ss) {\n",
    "    ExtcRcClass *c = r->clsBkt[extc_rc_classBucket(ss)];\n",
    "    while (c && c->ss != ss) c = c->next;\n",
    "    return c;\n",
    "}\n",
    "/* Push a slab with a free slot onto the size class's chain head. Called only when !avail, so a block on the chain never enters twice. */\n",
    "__attribute__((unused)) static void extc_rc_classPush(ExtcRcRegion *r, ExtcRcSlab *s) {\n",
    "    ExtcRcClass *c = extc_rc_classNeed(r, s->ss);\n",
    "    s->availNext = c->head;\n",
    "    c->head = s;\n",
    "    s->avail = 1;\n",
    "}\n",
    "\n",
    "/* Number of regions that have participated in rc. Monotonic: once a second region participates, the assignment fast path is off for good. */\n",
    "__attribute__((unused)) static size_t extc_rc_partN;\n",
    "\n",
    "/* Record that \"this region has participated in rc\". Criterion: with **only one region participating**, every rc object is inside it and\n",
    " * the assignment host must be it too, so no cross-region edge is possible and the whole lookup+registration on the assignment path can be skipped.\n",
    " * Unlike \"was anything registered\", this flag is maintained **unconditionally** by allocation and assignment, so the fast path cannot starve it. */\n",
    "__attribute__((unused)) static inline void extc_rc_notePart(ExtcRcRegion *r) {\n",
    "    if (r && !r->part) { r->part = 1; extc_rc_partN++; }\n",
    "}\n",
    "/* Stepped sweep: the allocation path needs it, but the sweep body is defined later. Each step sweeps at most 8 words (64 slots/word). */\n",
    "#ifndef EXTC_RC_SWEEP_BUDGET\n",
    "#define EXTC_RC_SWEEP_BUDGET 8\n",
    "#endif\n",
    "static int extc_rc_sweepStep(ExtcRcRegion *r, uint32_t budget);\n",
    "static void extc_rc_settle(ExtcRcRegion *r);\n",
    "/* Each macro gets its own `#ifndef`: tuning one (`cc -D...`) must not drag in the others -- a single\n",
    " * `#ifndef EXTC_RC_MARK_STEP` around four macros skips the other three whenever any one is defined. */\n",
    "#ifndef EXTC_RC_SEED_PUSHES\n",
    "#define EXTC_RC_SEED_PUSHES 256  /* how many **seed slots** one step pushes at most */\n",
    "#endif\n",
    "#ifndef EXTC_RC_SEED_WORDS\n",
    "#define EXTC_RC_SEED_WORDS 512  /* how many rsbit words one step **scans** at most (a separate seed-scan budget: word scanning must not stretch a step; too large and step time drifts with the slab, too small and a long slab is not scanned in one round) */\n",
    "#endif\n",
    "#ifndef EXTC_RC_MARK_EVERY\n",
    "#define EXTC_RC_MARK_EVERY 64        /* every how many allocations marking advances */\n",
    "#endif\n",
    "#ifndef EXTC_RC_MARK_WINDOW\n",
    "#define EXTC_RC_MARK_WINDOW (2 << 20)  /* window cap: past this many bytes of drift, boost (x8) */\n",
    "#endif\n",
    "#ifndef EXTC_RC_MARK_STEP\n",
    "#define EXTC_RC_MARK_STEP 8       /* base step: every allocation point advances at least this many objects */\n",
    "#endif\n",
    "#ifndef EXTC_RC_MARK_BATCH_MAX\n",
    "#define EXTC_RC_MARK_BATCH_MAX 256   /* **ceiling** on one `markAdvance` budget (the last window bound; larger lengthens a step's pause, smaller breaks the prefetch batch) */\n",
    "#endif\n",
    "#ifndef EXTC_RC_MARK_BATCH_POP\n",
    "#define EXTC_RC_MARK_BATCH_POP 200  /* pop this many objects first, prefetch them together, then scan one by one (breaks the LIFO serial pointer chain);\n",
    "                                    * the batch width also **steers traversal order**: step boundaries move with it, so collects and peak RSS move too;\n",
    "                                    * the trade-off: wall clock / step total / peak RSS pull against each other */\n",
    "#endif\n",
    "#if EXTC_RC_MARK_BATCH_POP > EXTC_RC_MARK_BATCH_MAX\n",
    "#error \"EXTC_RC_MARK_BATCH_POP exceeds EXTC_RC_MARK_BATCH_MAX\"\n",
    "#endif\n",
    "static int extc_rc_wb;   /* gate screen: count of participants in an in-flight mark (>0 keeps it on). The write side uses __atomic_fetch_add/sub: with several threads each region begins/finishes separately, and a plain ++/-- drops updates (parallel workers did occasionally underflow and crash).\n",
    "                         * Kept a plain int: _Atomic turns every hot-path read of if (!extc_rc_wb ...) into a compiler barrier, costing 33.8M Ir more (+8.8%) for chase at -O2 under callgrind; a plain aligned word read is one load on x86,\n",
    "                         * so the gate is only an optimization (the real decision is the object's own region's marking); briefly reading a stale 0 costs at most one extra scan. */\n",
    "/* Count add/sub go through noinline cold functions: the lock prefix + memory barrier of __atomic_fetch_add\n",
    " * would make GCC treat extc_rc_wb as \"may change at any time\", forcing the hot path to reload on every if (!extc_rc_wb ...) --\n",
    " * owed_home shows +2.56M Ir (+1.76%) at -O2 callgrind. Wrapping them noinline moves the barrier\n",
    " * into the cold function: owed_home is back to 146.58M (still +1.1%, same source as the registry generation change). */\n",
    "__attribute__((unused, noinline)) static int extc_rc_wbAdd(int d) {\n",
    "    return __atomic_fetch_add(&extc_rc_wb, d, __ATOMIC_RELAXED);\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_finish(ExtcRcRegion *r);   /* the allocation path's finish needs it */\n",
    "static size_t extc_rc_markStep(ExtcRcRegion *r, size_t budget);\n",
    "/* Slice pause accounting: the cost of each `markStep` / `sweepStep` (active while `EXTC_RC_PAUSE=1`).\n",
    " * `max_us` has a **long tail** (preemption/scheduling makes two runs of the same build differ by several times), so a window criterion uses\n",
    " * **over-threshold step count / quantile proxy** (the threshold buckets below); `max` is reference only, or a fallback upper bound. */\n",
    "static long long extc_rc_stepMax, extc_rc_stepTotal, extc_rc_stepN;\n",
    "static long long extc_rc_stepB1us, extc_rc_stepB4us, extc_rc_stepB16us, extc_rc_stepB64us,\n",
    "                 extc_rc_stepB256us, extc_rc_stepB1ms, extc_rc_stepBge1ms;\n",
    "static long long extc_rc_pauseNow(void);\n",
    "static int extc_rc_pauseOn;\n",
    "/* Per-step **work** (deterministic, independent of scheduling): objects walked / `rsbit` words scanned / seeds pushed.\n",
    " * Counts only **bounded hot-path steps** (`budget <= EXTC_RC_MARK_BATCH_MAX`): contract drains (budget=inf) are\n",
    " * unlimited by design. `walk_max/scan_max/push_max` plus the `>16/>64/>256` threshold buckets give the distribution. */\n",
    "static long long extc_rc_wN, extc_rc_wWalkMax, extc_rc_wScanMax, extc_rc_wPushMax;\n",
    "static long long extc_rc_wWalkO16, extc_rc_wWalkO64, extc_rc_wWalkO256;\n",
    "static long long extc_rc_wScanO16, extc_rc_wScanO64, extc_rc_wScanO256;\n",
    "static long long extc_rc_wPushO16, extc_rc_wPushO64, extc_rc_wPushO256;\n",
    "/* **Per-part attribution of the worst step** (`EXTC_RC_PAUSE=1`): records the entry/budget/counters of the step that took longest.\n",
    " * Purpose: decide whether the worst slice is \"walk/scan/push stacked\" or \"one part hitting its budget\"; `why` names the entry\n",
    " * (`step` hot path / `settle` settling / `collect` contract / `release` targeted release / `finish` finish /\n",
    " * `alloc` allocation point) -- an unbounded drain (budget=inf) appeared only as one timing line under `[step]`, hiding who triggered it. */\n",
    "__attribute__((unused)) static const char *extc_rc_why = \"?\";\n",
    "static long long extc_rc_worstNs, extc_rc_worstBudget, extc_rc_worstPops, extc_rc_worstMarked;\n",
    "static long long extc_rc_worstWords, extc_rc_worstPushes, extc_rc_worstSwWords, extc_rc_worstSwFreed;\n",
    "static const char *extc_rc_worstWhy = \"-\";\n",
    "static const char *extc_rc_worstKind = \"-\";\n",
    "/* **Unbounded steps** (mark: budget > BATCH_MAX; sweep: drain path) are listed separately: they are not bounded by work, but must\n",
    " * be visible in `[work]`, otherwise \"unbounded\" reads as \"this step did no work\". */\n",
    "static long long extc_rc_wUbN, extc_rc_wUbWalkMax, extc_rc_wUbScanMax, extc_rc_wUbPushMax;\n",
    "static long long extc_rc_wUbSwN, extc_rc_wUbSwWordsMax, extc_rc_wUbSwFreedMax;\n",
    "/* Unbounded mark drains are counted by **entry**: `settle`/`collect`/`release`/other. The criterion asks\n",
    " * \"who triggered an unbounded drain inside a hot loop\", so the entry dimension matters more than the total. */\n",
    "static long long extc_rc_ubSettleN, extc_rc_ubCollectN, extc_rc_ubReleaseN, extc_rc_ubOtherN;\n",
    "/* Per-step **total** (walk+scan+push, the observed form of the unified budget) and the **assist share** (how much of this budget\n",
    " * the `wbDebt` debt boost took). `extc_rc_stepAssist` is written by the allocation/settle entries before calling `markStep`. */\n",
    "static long long extc_rc_wTotMax, extc_rc_wAssistMax;\n",
    "static long long extc_rc_slowUs = -1;   /* `EXTC_RC_SLOWSTEP=<us>`: log every slow step (-1 = not probed) */\n",
    "/* **Mark stack high-water mark** (deterministic): `mscap` only grows, so a sample is the peak. When shading by `wbDebt` outpaces draining,\n",
    " * the stack grows without bound (`markPush`'s `realloc` runs inside `markStep`, so a \"bounded step\" of 16 objects can\n",
    " * spend 16 ms), so walk/scan/push alone would misjudge it as \"bounded\". This line is the criterion for that failure mode. */\n",
    "static long long extc_rc_mscapMax, extc_rc_mspMax;\n",
    "__attribute__((unused)) static size_t extc_rc_stepAssist;\n",
    "__attribute__((unused)) static inline void extc_rc_workNote(size_t walk, size_t scan, size_t push) {\n",
    "    extc_rc_wN++;\n",
    "    if ((long long)walk > extc_rc_wWalkMax) extc_rc_wWalkMax = (long long)walk;\n",
    "    if ((long long)scan > extc_rc_wScanMax) extc_rc_wScanMax = (long long)scan;\n",
    "    if ((long long)push > extc_rc_wPushMax) extc_rc_wPushMax = (long long)push;\n",
    "    if ((long long)(walk + scan + push) > extc_rc_wTotMax) extc_rc_wTotMax = (long long)(walk + scan + push);\n",
    "    if ((long long)extc_rc_stepAssist > extc_rc_wAssistMax) extc_rc_wAssistMax = (long long)extc_rc_stepAssist;\n",
    "    if (walk > 16) extc_rc_wWalkO16++;\n",
    "    if (walk > 64) extc_rc_wWalkO64++;\n",
    "    if (walk > 256) extc_rc_wWalkO256++;\n",
    "    if (scan > 16) extc_rc_wScanO16++;\n",
    "    if (scan > 64) extc_rc_wScanO64++;\n",
    "    if (scan > 256) extc_rc_wScanO256++;\n",
    "    if (push > 16) extc_rc_wPushO16++;\n",
    "    if (push > 64) extc_rc_wPushO64++;\n",
    "    if (push > 256) extc_rc_wPushO256++;\n",
    "}\n",
    "__attribute__((unused)) static inline void extc_rc_stepNote(long long d) {\n",
    "    extc_rc_stepTotal += d; extc_rc_stepN++;\n",
    "    if (d > extc_rc_stepMax) extc_rc_stepMax = d;\n",
    "    if (d < 1000) extc_rc_stepB1us++; else if (d < 4000) extc_rc_stepB4us++;\n",
    "    else if (d < 16000) extc_rc_stepB16us++; else if (d < 64000) extc_rc_stepB64us++;\n",
    "    else if (d < 256000) extc_rc_stepB256us++; else if (d < 1000000) extc_rc_stepB1ms++;\n",
    "    else extc_rc_stepBge1ms++;\n",
    "}\n",
    "#ifndef EXTC_RC_ASSIST_CAP\n",
    "#define EXTC_RC_ASSIST_CAP 512   /* per-step assist cap: however much debt there is, a step must not become a full mark */\n",
    "#endif\n",
    "/* ---- Unified work budget (`EXTC_RC_WORK_BUDGET`, default 0 = off) [rt:budget] ----\n",
    " *\n",
    " * off (0): the three budgets are **independent** -- walk (`MARK_BATCH_MAX`), seed word scan (`SEED_WORDS`),\n",
    " * seed pushes (`SEED_PUSHES`) -- and the three **stack in one step**; the `wbDebt` boost is counted separately.\n",
    " * on (W>0): the three plus assist share **one total** `W` (walk 1 object = 1, scan 1 word = 1,\n",
    " * push 1 slot = 1), deducted from one counter `wleft` in `markStep`; it stops at 0 (the seed phase deducts too).\n",
    " * So one step's total work is **bounded by construction to <= W**, independent of scheduling and checkable verbatim by the gate.\n",
    " *\n",
    " * `EXTC_RC_WORK_BUDGET` comes from a C compile-time `-D` (the generated file has an `#ifndef` fallback), so scanning W does not need\n",
    " * rebuilding the compiler. */\n",
    "#ifndef EXTC_RC_WORK_BUDGET\n",
    "#define EXTC_RC_WORK_BUDGET 0   /* 0 = off: three separate budgets; >0 = one total W per step */\n",
    "#endif\n",
    "/** @brief Budget of this step: base step + debt, **capped** (the window-bound guarantee). */\n",
    "__attribute__((unused)) static size_t extc_rc_stepBudget(const ExtcRcRegion *r) {\n",
    "    size_t d = r->wbDebt > 64 ? 64 : r->wbDebt;   /* at most 64 debts repaid per allocation (shading ~1-2/allocation, so drain>=shade still holds) */\n",
    "    extc_rc_stepAssist = d;   /* assist share: the debt boost (counted in the same total under the unified budget) */\n",
    "    return EXTC_RC_MARK_STEP + d;\n",
    "}\n",
    "/* Batched advance + window cap: one step every EXTC_RC_MARK_EVERY allocations; past the window it boosts. */\n",
    "/* Inline: every dispatch point on the allocation path goes through here, and -O1 does not inline across call sites, so each pass adds a call/return;\n",
    " * the body is only a counter decrement and a capped computation, so inlining it into the allocation body barely grows. */\n",
    "__attribute__((unused)) static inline __attribute__((always_inline)) void extc_rc_markAdvance(ExtcRcRegion *r) {\n",
    "    if (--r->markTick > 0) return;   /* skip:mark-tick */\n",
    "    extc_rc_why = \"advance\";\n",
    "    r->markTick = EXTC_RC_MARK_EVERY;\n",
    "    size_t _debt = r->wbDebt > EXTC_RC_ASSIST_CAP ? EXTC_RC_ASSIST_CAP : r->wbDebt;\n",
    "    size_t b = (size_t)EXTC_RC_MARK_EVERY * EXTC_RC_MARK_STEP + _debt;   /* debt cap (the purpose of ASSIST_CAP) */\n",
    "    extc_rc_stepAssist = _debt;   /* assist share (counted in the same total under the unified budget) */\n",
    "    if (r->allocBytes - r->markStartAlloc > EXTC_RC_MARK_WINDOW) b *= 8;\n",
    "    if (b > EXTC_RC_MARK_BATCH_MAX) b = EXTC_RC_MARK_BATCH_MAX;   /* last window bound: a step's budget may never be unlimited */\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "    if (b > EXTC_RC_WORK_BUDGET) b = EXTC_RC_WORK_BUDGET;   /* under the unified budget the walk budget may not exceed the total either */\n",
    "#endif\n",
    "    extc_rc_markStep(r, b);\n",
    "    r->wbDebt = 0;\n",
    "    if (r->seedsDone && !r->msp && !r->scanObj) r->markDone = 1;\n",
    "}\n",
    "/* Allocation-point expansion: the allocation body is only a few dozen instructions, and **every allocation point** calls it once. Without expansion each allocation pays\n",
    " * a call plus frame push/pop (-O1: about 13.5 Ir per allocation, close to a third of the allocation cost); with expansion the compiler can also fold the constant\n",
    " * n (size class, zeroing length become immediates). The cost is one copy of the allocation body per allocation point (about 2.7 KB of\n",
    " * machine code): a program with unusually many allocation points can pass -DEXTC_RC_ALLOC_INLINE=0 to trade back size (that variant is declared noinline\n",
    " * so only one function body remains and each allocation pays one more call/return), word-for-word identical semantics.\n",
    " * Attributes go through a macro and the signature exists once: two signatures would give the same function two opening braces, and the structural gate that splits function bodies by brace balance\n",
    " * (check_foreign_skip) would then count the following bodies as part of it.\n",
    " * Criterion: check_alloc_hot pins this switch, the attribute macro and the noinline exit (removing either turns it red). */\n",
    "#ifndef EXTC_RC_ALLOC_INLINE\n",
    "#define EXTC_RC_ALLOC_INLINE 1\n",
    "#endif\n",
    "#if EXTC_RC_ALLOC_INLINE\n",
    "#define EXTC_RC_ALLOC_DECL __attribute__((always_inline)) inline\n",
    "#else\n",
    "#define EXTC_RC_ALLOC_DECL __attribute__((noinline))\n",
    "#endif\n",
    "__attribute__((unused)) static EXTC_RC_ALLOC_DECL void *extc_rc_alloc(ExtcRcRegion *r, size_t n, const ExtcRcType *td) {\n",
    "    EXTC_RC_TICK(0);   /* per-component timing (`EXTC_RC_TIME=1`) */\n",
    "    extc_rc_notePart(r);\n",
    "    /* Stepped continuation sweep; obligation 7: a dropped region is never scanned again (not one byte). */\n",
    "    if (r->sweeping) {\n",
    "        extc_rc_why = \"alloc\";   /* slow-step attribution: only this branch advances the sweep on an allocation's behalf; mark advance writes\n",
    "                                    * \"advance\" itself and finish/collect write their own, so there is no unconditional store at entry\n",
    "                                    * (one store saved per allocation; the `why` in `[step]`/`[worst]` logs is unchanged word for word). */\n",
    "        if (r->noSweep) r->sweeping = 0;   /* skip:nosweep-abandon */\n",
    "        else extc_rc_sweepStep(r, EXTC_RC_SWEEP_BUDGET);\n",
    "    }\n",
    "    if (r->marking) {\n",
    "        if (r->msp != 0 || !r->seedsDone || r->scanObj) extc_rc_markAdvance(r);   /* batched advance */\n",
    "        /* The finish guard is hoisted to the call site: the first line of finish is exactly this test (here inside the marking branch,\n",
    "         * only seedsDone/msp differ), and most allocation-point calls are just call + return + early exit\n",
    "         * (once per allocation while marking). Testing in place saves that call; the guard inside finish stays as\n",
    "         * defence in depth (other entries do not come through here). */\n",
    "        if (r->seedsDone && r->msp == 0 && !r->scanObj) extc_rc_finish(r);   /* once done, **close the barrier on the spot**: otherwise this round would idle for tens of thousands of allocations */\n",
    "    }\n",
    "    size_t ss = extc_rc_slotSize(n);\n",
    "    size_t ac = ss / 8;   /* size class = slot stride / 8 (the slot stride is guaranteed to be a multiple of 8) */\n",
    "    ExtcRcSlab **hot = ac < 32 ? &r->allocHot[ac] : (ExtcRcSlab **)0;\n",
    "    ExtcRcSlab *s = hot ? *hot : (ExtcRcSlab *)0;\n",
    "    /* Do not verify s->ss == ss: allocHot is written only by this function (the only write is *hot = s below), and s can only\n",
    "     * come from classSlot(r, ss) or slabNew(r, ss) -- both bind the same size class, and a block's slot stride never changes in its life\n",
    "     * so a cached block belongs to the same size class. Saves one comparison per allocation (criterion: check_alloc_hot pins \"no repeated size check\"). */\n",
    "    if (!s || (s->freelist < 0 && s->bump >= s->nslots)) {\n",
    "        /* Fallback: one \"has a free slot\" chain per size class, take the head in O(1) -- not a linear search of r->slabs\n",
    "         * (with many live slabs that was O(live slabs) per allocation; see the comment above extc_rc_classNeed).\n",
    "         * The chain may hold blocks that have become full (popping is lazy), so skip them first; each block is popped at most once, amortized O(1). */\n",
    "        ExtcRcClass *c = extc_rc_classSlot(r, ss);\n",
    "        s = c ? c->head : (ExtcRcSlab *)0;\n",
    "        while (s && s->freelist < 0 && s->bump >= s->nslots) {\n",
    "            c->head = s->availNext;\n",
    "            s->avail = 0;   /* off the chain */\n",
    "            s = c->head;\n",
    "        }\n",
    "    }\n",
    "    if (!s) {\n",
    "        s = extc_rc_slabNew(r, ss);\n",
    "        s->next = r->slabs;\n",
    "        r->slabs = s;\n",
    "        extc_rc_classPush(r, s);   /* new block onto the size-class chain: later fetch is O(1) */\n",
    "    }\n",
    "    if (hot) *hot = s;\n",
    "    size_t i;\n",
    "    if (s->freelist >= 0) {                   /* reuse: the next slot number lives in tid[] (+1 encoding) */\n",
    "        i = (size_t)s->freelist;\n",
    "        s->freelist = (int64_t)s->tid[i] - 1;  /* 0 = end of chain; the payload takes no part in the reuse chain (see extc_rc_freeSlot) */\n",
    "    } else {\n",
    "        i = (size_t)s->bump++;                /* never issued yet: advance the cursor */\n",
    "        if (s->rscnt) s->rscnt[i] = 0;         /* new slot: in-edge count starts at 0 (lazy allocation: with no table there can be no in-edges) */\n",
    "    }\n",
    "    char *p = EXTC_RC_SLAB_DATA(s) + i * s->ss;\n",
    "    memset(p, 0, ss);                         /* a fresh allocation reads as 0: language promise, and a precondition for marking */\n",
    "    size_t wi = extc_rc_word(i);   /* compute the word coordinate once: occupancy/mark/sweep all need it */\n",
    "    uint64_t bi = extc_rc_bit(i);\n",
    "    s->occ[wi] |= bi;\n",
    "    if (r->marking) s->mark[wi] |= bi;   /* allocated during marking means marked black */\n",
    "    /* An allocation during sweep is marked black, **only at positions the cursor has not reached yet**: scanned positions are never looked at again,\n",
    "     * so marking them would leave a stale bit nobody clears (the next mark round does not clear the bitmap). */\n",
    "    if (r->sweeping && s->swEpoch != r->swId\n",
    "        && (s != r->swSlab || wi >= r->swWord))\n",
    "        s->mark[wi] |= bi;\n",
    "    s->tid[i] = extc_rc_typeIdx(s, td);   /* a 2-byte number per slot, not an 8-byte pointer */\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "    s->hold[i] = 0;\n",
    "#endif\n",
    "    r->bytes += (int64_t)ss;\n",
    "    r->allocBytes += (int64_t)ss;\n",
    "    return p;\n",
    "}\n",
    "\n",
    "/* ---- Source-side bookkeeping: counting and undoing cross-region in-edges [rt:xregion] ----\n",
    " *\n",
    " * `rsbit` is a **cache** of \"this target slot has live in-edges from another region\", maintained by each slot's `rscnt`: 0 to 1\n",
    " * sets the bit, 1 to 0 clears it, and the saturated value (\"many edges\") sticks and is never decremented -- the same soundness rule as the holder count.\n",
    " *\n",
    " * The count is transferred in three places:\n",
    " *   1. `extc_rc_storeRefOwned`: one assignment replaces one edge (old value decremented, new value incremented), for **cross-region** edges only;\n",
    " *   2. `extc_rc_freeSlot`: freeing an object drops the cross-region edges it holds (the object is gone, so are the edges);\n",
    " *   3. `extc_rc_regionFree`: dropping a whole region decrements in bulk the cross-region edges held by objects in that region **that are still live**.\n",
    " * So the number of registered bits equals the current number of live cross-region edges, decoupled from the number of rounds (a scheme that only sets bits and never clears them would let seeds build up to every object).\n",
    " * The cost is a pass over the pointer fields of the region's slots when the region is dropped (O(live slots of this region)), without scanning the whole table and without touching other regions. */\n",
    "/* Registration/undo counters: `rs_live = inc - dec` is the current number of live cross-region edges; `rs_hwm` is its high-water mark.\n",
    " * The criterion looks at the **high-water mark**: when undo keeps up, it is bounded only by the sweep trigger threshold (memory pressure), independent of the number of rounds.\n",
    " * With EXTC_RC_STATS=1 these numbers are printed at process exit. */\n",
    "__attribute__((unused)) static int64_t extc_rc_rsIncN, extc_rc_rsDecN, extc_rc_rsHwm;\n",
    "/* Count and slot count of targeted release on overwrite (`extc_rc_storeRefOwnedRelease`). Statistics only: the criterion must show that\n",
    " * release **really frees something** (a no-op has to be visible too). Printed by `EXTC_RC_STATS=1` like the `rs_*` numbers. */\n",
    "__attribute__((unused)) static int64_t extc_rc_relN, extc_rc_relSlots;\n",


    "\n",
    "__attribute__((unused)) static ExtcRcRegion *extc_rc_regionOfOwn(void *p) {\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(p);\n",
    "    return s ? s->region : (ExtcRcRegion *)0;\n",
    "}\n",
    "\n",
    "/* Run-time guard for the cross-region old-value invariant (**compile-time** switch, off by default so the default build pays nothing):\n",
    " * at the points that skip the old-value lookup because \"this region has no foreign pointers\", recompute the old value's region and count it;\n",
    " * if \"the old value is a foreign pointer that was never registered\" really occurs, the foreign invariant is broken, so the count is non-zero (the gate turns red).\n",
    " * The criterion requires checks>0 and bad==0: **not reaching the guard (checks==0) must also fail**, it may not masquerade as green. */\n",
    "#ifndef EXTC_RC_FOREIGN_GUARD\n",
    "#define EXTC_RC_FOREIGN_GUARD 0\n",
    "#endif\n",
    "#if EXTC_RC_FOREIGN_GUARD\n",
    "static long long extc_rc_fgChecks, extc_rc_fgBad;\n",
    "static void extc_rc_fgDump(void) { fprintf(stderr, \"[fg] checks=%lld bad=%lld\\n\", extc_rc_fgChecks, extc_rc_fgBad); }\n",
    "static void extc_rc_fgArm(void) { static int _a; if (!_a) { _a = 1; atexit(extc_rc_fgDump); } }\n",
    "#endif\n",
    "/* `rscnt` (per-slot cross-region in-edge count) is **lazily allocated**: a slab that never sees a registration never builds the table\n",
    " * so a shape that never crosses regions saves the whole table (2 B per slot). */\n",
    "static void extc_rc_rsAlloc(ExtcRcSlab *s) {\n",
    "    if (s->rscnt) return;   /* skip:rscnt-have */\n",
    "    s->rscnt = (uint16_t *)calloc((size_t)s->nslots, sizeof(uint16_t));\n",
    "    if (!s->rscnt) extc_rc_oops(\"rscnt allocation failed\");\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_rsInc(void *t) {\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(t);\n",
    "    if (!s) return;   /* skip:not-own */\n",
    "    size_t i = extc_rc_slotOf(s, t);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return;   /* skip:occ-free */\n",
    "    extc_rc_rsAlloc(s);\n",
    "    if (s->rscnt[i] == EXTC_RC_HOLD_SAT) return;          /* saturated: sticks, never wrongly decremented to zero */   /* skip:sat-inc */\n",
    "    if (s->rscnt[i]++ == 0) { s->rsbit[extc_rc_word(i)] |= extc_rc_bit(i); s->region->seedAny = 1; }\n",
    "    extc_rc_rsIncN++;\n",
    "    if (extc_rc_rsIncN - extc_rc_rsDecN > extc_rc_rsHwm) extc_rc_rsHwm = extc_rc_rsIncN - extc_rc_rsDecN;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_rsDec(void *t) {\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(t);\n",
    "    if (!s) return;   /* skip:not-own */\n",
    "    size_t i = extc_rc_slotOf(s, t);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return;   /* skip:occ-free */\n",
    "    if (!s->rscnt || s->rscnt[i] == 0 || s->rscnt[i] == EXTC_RC_HOLD_SAT) return;   /* skip:sat-dec */\n",
    "    if (--s->rscnt[i] == 0) s->rsbit[extc_rc_word(i)] &= ~extc_rc_bit(i);\n",
    "    extc_rc_rsDecN++;\n",
    "}\n",
    "\n",
    "/* Cross-region bookkeeping for an already-resolved slab: saves the repeated `ownSlab` lookup in each entry.\n",
    " * Criterion identical to `extc_rc_rsInc`/`rsDec` point by point (occupied bit, saturation sticks, bitmap maintenance),\n",
    " * except that \"find the slab\" is left to the caller -- the caller already looked up the same pointer anyway. */\n",
    "__attribute__((unused)) static void extc_rc_rsIncSlab(ExtcRcSlab *s, void *t) {\n",
    "    size_t i = extc_rc_slotOf(s, t);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return;   /* skip:occ-free */\n",
    "    extc_rc_rsAlloc(s);\n",
    "    if (s->rscnt[i] == EXTC_RC_HOLD_SAT) return;   /* skip:sat-inc */\n",
    "    if (s->rscnt[i]++ == 0) { s->rsbit[extc_rc_word(i)] |= extc_rc_bit(i); s->region->seedAny = 1; }\n",
    "    extc_rc_rsIncN++;\n",
    "    if (extc_rc_rsIncN - extc_rc_rsDecN > extc_rc_rsHwm) extc_rc_rsHwm = extc_rc_rsIncN - extc_rc_rsDecN;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_rsDecSlab(ExtcRcSlab *s, void *t) {\n",
    "    size_t i = extc_rc_slotOf(s, t);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return;   /* skip:occ-free */\n",
    "    if (!s->rscnt || s->rscnt[i] == 0 || s->rscnt[i] == EXTC_RC_HOLD_SAT) return;   /* skip:sat-dec */\n",
    "    if (--s->rscnt[i] == 0) s->rsbit[extc_rc_word(i)] &= ~extc_rc_bit(i);\n",
    "    extc_rc_rsDecN++;\n",
    "}\n",
    "\n",
    "/* A slot that is **about to stop being an object**: undo by source the edges it holds into other regions. Fields and type descriptor\n",
    " * must still be intact when reading, so every call site runs before the free-chain store and the descriptor clear. */\n",
    "__attribute__((unused)) static void extc_rc_unlinkChildren(ExtcRcSlab *s, size_t i) {\n",
    "    char *p = EXTC_RC_SLAB_DATA(s) + i * s->ss;\n",
    "    const ExtcRcType *t = extc_rc_typeOf(s, i);\n",
    "    if (t == EXTC_RC_CONSERVATIVE) {\n",
    "        size_t words = s->ss / sizeof(void *);\n",
    "        for (size_t w = 0; w < words; w++) {\n",
    "            void *c = ((void **)p)[w];\n",
    "            if (c) { ExtcRcSlab *cs = extc_rc_ownSlab(c); if (cs && cs->region != s->region) extc_rc_rsDecSlab(cs, c); }\n",
    "        }\n",
    "        return;\n",
    "    }\n",
    "    if (!t) return;   /* skip:no-desc */\n",
    "    for (uint32_t k = 0; k < t->nptr; k++) {\n",
    "        void *c = *(void **)(p + t->off[k]);\n",
    "        if (c) { ExtcRcSlab *cs = extc_rc_ownSlab(c); if (cs && cs->region != s->region) extc_rc_rsDecSlab(cs, c); }\n",
    "    }\n",
    "}\n",
    "\n",
    "/* Head insertion on the free chain is the only step on the release path that **must be per slot** (each slot's link value differs); the sweep's bulk free\n",
    " * (extc_rc_freeSlotWord) reuses this section too. See the freeSlot comment below: the link value goes into tid[], not the payload. */\n",
    "__attribute__((unused)) static void extc_rc_freeSlotLink(ExtcRcSlab *s, size_t i) {\n",
    "    if (extc_rc_rsIncN) extc_rc_unlinkChildren(s, i);   /* undo its cross-region edges first (the fields are still intact);\n",
    "                                                         * with no registration ever made there is nothing to undo */\n",
    "    s->tid[i] = (uint16_t)(s->freelist + 1);   /* head insertion: store the old slot number (0 = end of chain) */\n",
    "    s->freelist = (int64_t)i;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_freeSlot(ExtcRcSlab *s, size_t i) {\n",
    "    EXTC_RC_TICK(5);   /* per-component timing (`EXTC_RC_TIME=1`) */\n",
    "    extc_rc_freeSlotLink(s, i);   /* head insertion. The link value goes into tid[] rather than the payload: a freed slot is cold, and writing those 8\n",
    "                                   * payload bytes pulls the whole cache line in (RFO) -- the sweep then pays one more last-level store miss\n",
    "                                   * per slot freed; tid[] is a dense 2-byte-per-slot metadata array, so writing it\n",
    "                                   * touches no extra memory (this entry is written below anyway).\n",
    "                                   * Encoding: slot number + 1 (0 = end of chain); limit in EXTC_RC_REUSE_MAX_SLOT. */\n",
    "    size_t wi = extc_rc_word(i);   /* occupancy and registration bit share one word: compute the coordinate once */\n",
    "    uint64_t bi = extc_rc_bit(i);\n",
    "    s->occ[wi]   &= ~bi;\n",
    "    s->rsbit[wi] &= ~bi;   /* obligation 5: leave no stale entry */\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "    s->hold[i] = 0;\n",
    "#endif\n",    "    if (s->rscnt) s->rscnt[i] = 0;\n",

    "    s->region->bytes -= (int64_t)s->ss;\n",
    "    s->region->freedSlots++;   /* definition: **every** freeSlot counts (counting only at sweep end would miss\n",
    " * the count-to-zero releases on the hot path, so the accessor would report 0) */\n",
    "    if (!s->avail) extc_rc_classPush(s->region, s);   /* a free slot again: push back onto the size-class chain (see extc_rc_alloc) */\n",
    "}\n",
    "\n",
    "/* Word-wise bulk free during sweep: all slots in a dead word are released together. Of the per-slot steps only \"head insertion\" differs per slot\n",
    " * (the link value differs); occupancy bit, registration bit, byte accounting, freedSlots and the size-class push happen once per word --\n",
    " * during sweep there is no allocation and no reader of these fields, so doing them per slot would just repeat the same work 64 times.\n",
    " * unlinkChildren still runs per slot (it reads the slot's fields), but the \"no registration ever made\" branch is hoisted out of the word loop:\n",
    " * in the default build rsIncN is always 0, so that whole section never runs. Returns the number of released slots. */\n",
    "__attribute__((unused)) static size_t extc_rc_freeSlotWord(ExtcRcSlab *s, size_t w, uint64_t dead) {\n",
    "    size_t base = w * 64;\n",
    "    uint64_t bits = dead;\n",
    "    if (extc_rc_rsIncN) {\n",
    "        uint64_t _u = dead;\n",
    "        while (_u) {\n",
    "            uint32_t b = (uint32_t)__builtin_ctzll(_u);\n",
    "            _u &= _u - 1;\n",
    "            extc_rc_unlinkChildren(s, base + b);\n",
    "        }\n",
    "    }\n",
    "    {\n",
    "        uint64_t _d = dead;\n",
    "        while (_d) {\n",
    "            uint32_t b = (uint32_t)__builtin_ctzll(_d);\n",
    "            _d &= _d - 1;\n",
    "            size_t i = base + b;\n",
    "            s->tid[i] = (uint16_t)(s->freelist + 1);\n",
    "            s->freelist = (int64_t)i;\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "            s->hold[i] = 0;\n",
    "#endif\n",
    "        }\n",
    "    }\n",
    "    if (s->rscnt) {\n",
    "        uint64_t _r = dead;\n",
    "        while (_r) {\n",
    "            uint32_t b = (uint32_t)__builtin_ctzll(_r);\n",
    "            _r &= _r - 1;\n",
    "            s->rscnt[base + b] = 0;\n",
    "        }\n",
    "    }\n",
    "    s->occ[w] &= ~bits;\n",
    "    s->rsbit[w] &= ~bits;   /* obligation 5: leave no stale entry */\n",
    "    size_t n = (size_t)__builtin_popcountll(bits);\n",
    "    s->region->bytes -= (int64_t)n * (int64_t)s->ss;\n",
    "    s->region->freedSlots += n;\n",
    "    if (!s->avail) extc_rc_classPush(s->region, s);\n",
    "    return n;\n",
    "}\n",
    "\n",
    "/* ---- `EXTC_RC_NOCOUNT=1`: the counting entries become no-ops [rt:nocount] ----------------------\n",
    " *\n",
    " * Marking/sweeping **do not depend on counts** -- `extc_rc_mark` starts from root slots and registered cross-region seeds and descends via each slot's type\n",
    " * descriptor, `extc_rc_sweep` releases unmarked occupied slots; the only role of counting is \"reclaim as soon as the count hits zero\".\n",
    " * With counting off, garbage-dense shapes are still swept within a fixed number of rounds, peak memory does not grow and semantics are unchanged, while the hot path\n",
    " * loses a whole set of ever-increasing reference-count bookkeeping. **`EXTC_RC_NOCOUNT=1` is the default: the counting entries are compiled out entirely** --\n",
    " * reclamation relies on region sweeping alone; only `EXTC_RC_NOCOUNT=0` restores \"counting + early reclaim\". */\n",
    "#if EXTC_RC_NOCOUNT\n",
    "__attribute__((unused)) static void extc_rc_holdUpdSlab(ExtcRcSlab *s, void *p, int delta) {\n",
    "    (void)s; (void)p; (void)delta;\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_holdUpd(void *p, int delta) {\n",
    "    (void)p; (void)delta;\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_inc(void *p) { (void)p; }\n",
    "__attribute__((unused)) static void extc_rc_dec(void *p) { (void)p; }\n",
    "#else\n",
    "/* Holder count for an already-resolved slab: `extc_rc_holdUpd` without the \"find the slab\" step.\n",
    " * Obligations identical to `holdUpd` point by point (occupied bit, saturation sticks, reclaim on the spot when it hits zero). */\n",
    "__attribute__((unused)) static void extc_rc_holdUpdSlab(ExtcRcSlab *s, void *p, int delta) {\n",
    "    size_t i = extc_rc_slotOf(s, p);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return;   /* free slot: not a live object */   /* skip:occ-free */\n",
    "    if (delta > 0) {\n",
    "        if (s->hold[i] != EXTC_RC_HOLD_SAT) s->hold[i]++;\n",
    "        return;\n",
    "    }\n",
    "    if (s->hold[i] == 0 || s->hold[i] == EXTC_RC_HOLD_SAT) return;   /* skip:hold-zero */\n",
    "    s->hold[i]--;\n",
    "    if (s->hold[i] == 0) extc_rc_freeSlot(s, i);\n",
    "}\n",
    "\n",
    "/* Counting recognises **only rc slots allocated by this runtime that are still occupied**. Pointers from the board/pool/stack/C are not such slots and\n",
    " * are skipped entirely here -- that is the guard (when the origin of the pointer is unknown, not one byte is touched). */\n",
    "__attribute__((unused)) static void extc_rc_holdUpd(void *p, int delta) {\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(p);\n",
    "    if (!s) return;   /* skip:not-own */\n",
    "    size_t i = extc_rc_slotOf(s, p);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return;   /* free slot: not a live object */   /* skip:occ-free */\n",
    "    if (delta > 0) {\n",
    "        if (s->hold[i] != EXTC_RC_HOLD_SAT) s->hold[i]++;   /* obligation 3: stick at the ceiling */\n",
    "        return;\n",
    "    }\n",
    "    if (s->hold[i] == 0 || s->hold[i] == EXTC_RC_HOLD_SAT) return;  /* saturated value is never decremented */   /* skip:hold-zero */\n",
    "    s->hold[i]--;\n",
    "    if (s->hold[i] == 0) extc_rc_freeSlot(s, i);            /* reclaim on the spot when it hits zero */\n",
    "}\n",
    "\n",
    "/* Counting hooks only pointer assignments: data-field stores do not go through these two. */\n",
    "__attribute__((unused)) static void extc_rc_inc(void *p) { extc_rc_holdUpd(p, +1); }\n",
    "__attribute__((unused)) static void extc_rc_dec(void *p) { extc_rc_holdUpd(p, -1); }\n",
    "#endif\n",
    "\n",
    "/* New slot: write and increment the target. **Never reads the old value** (obligation 1). */\n",
    "static void extc_rc_markPush(ExtcRcRegion *r, void *o);\n",
    "/* Barrier-only push: low bit of the pointer set means \"must be scanned even if already marked black\". Slot pointers are 8-byte aligned\n",
    " * (`extc_rc_slotSize` rounds to 8, `data` is 64-aligned), so the low bit is free and no new state is needed. */\n",
    "__attribute__((unused)) static void extc_rc_markPushForce(ExtcRcRegion *r, void *o);\n",
    "/* Barrier body (cold half): shade the \"new value\" (Dijkstra incremental update). Only white objects of the region that is **currently marking**\n",
    " * need shading; the allocation side has \"allocate means mark black\", so no new white objects appear inside a marking window.\n",
    " *\n",
    " * It is called only when a mark **is really in flight** (the decision is in the inline wrapper extc_rc_shade) -- assignments overwhelmingly happen\n",
    " * outside marking, and that side should not even build a stack frame. */\n",
    "/* ---- Shading cache: one record of {pointer -> already black} [rt:shade-cache] ----------------\n",
    " *\n",
    " * Most barrier calls are just \"this object is already black, ask again\": over one whole-region reclaim the shade hit rate is\n",
    " * close to 72%, and every hit costs ownSlab + slotOf + two bitmap reads. On a hit the only lawful answer is\n",
    " * \"do nothing\", so it can be remembered.\n",
    " *\n",
    " * Invalidation uses a **generation number**, but the number does not take a second word: it is **rotated into the hash cell index**. The cell index is\n",
    " * (address >> 3) + extc_rc_shadeGen, so the same pointer lands in a **different cell in a different generation**, hence one cell holding\n",
    " * one pointer (8 bytes) is enough: \"same cell, same pointer\" can only come from the same generation, so a hit is **exact**. The generation number\n",
    " * wraps every 2048 generations: `extc_rc_shadeNextGen` clears the whole table before the wrap, so old records are gone after it.\n",
    " *\n",
    " * The invalidation contract is unchanged: every path in the core that clears a mark bit calls `extc_rc_shadeNextGen()` (round start, sweep start,\n",
    " * the whole-span clear of a narrowing sweep, whole-region release). The invariant is still \"within one generation a slot's mark bit only goes 0 to 1\" --\n",
    " * a hit means that cell was black **in this generation**, so it is still black: skipping the barrier and the slow path (including ownSlab) does not change\n",
    " * the reachable set. Slot release (freeSlot) does not clear the mark bit, so it does not break this invariant either.\n",
    " *\n",
    " * Cost: 2048 x 8 B of static memory + one hash and store per slow path + a 16 KB clear every 2048 generations\n",
    " *(8 bytes amortized per generation). The hash takes high address bits (slots are 8-byte aligned, so the low 3 bits are always 0), direct-mapped,\n",
    " * collision overwrite is fine: this is a **hint**, not a cache, and a miss just takes the slow path again. */\n",
    "typedef struct ExtcRcShadeCell { uintptr_t v; } ExtcRcShadeCell;\n",
    "static uint64_t extc_rc_shadeGen = 1;\n",
    "static ExtcRcShadeCell extc_rc_shadeCache[2048];\n",
    "static inline size_t extc_rc_shadeHash(void *v) {\n",
    "    return (size_t)((((uintptr_t)v >> 3) + (uintptr_t)extc_rc_shadeGen) & 2047u);\n",
    "}\n",
    "static inline int extc_rc_shadeKnown(void *v) {\n",
    "    return extc_rc_shadeCache[extc_rc_shadeHash(v)].v == (uintptr_t)v;\n",
    "}\n",
    "static inline void extc_rc_shadeRemember(void *v) {\n",
    "    extc_rc_shadeCache[extc_rc_shadeHash(v)].v = (uintptr_t)v;\n",
    "}\n",
    "/* Advance the generation number by one; clear the table before wrapping (see above). All four mark-clearing paths call only this, no hand-written gen++. */\n",
    "static inline void extc_rc_shadeNextGen(void) {\n",
    "    if ((++extc_rc_shadeGen & 2047u) == 0u) memset(extc_rc_shadeCache, 0, sizeof extc_rc_shadeCache);\n",
    "}\n",
    "/* Cache self-check (off by default, -DEXTC_RC_SHADE_GUARD=1 enables): on a hit, redo the slow path's \"really still black\" test,\n",
    " * count bad when it is not black. It verifies exactly the invalidation contract \"every path that clears a mark bit bumps the generation\" -- miss one and\n",
    " * the cache treats a white object as black and skips reachable objects (the next sweep frees them). */\n",
    "#ifndef EXTC_RC_SHADE_GUARD\n",
    "#define EXTC_RC_SHADE_GUARD 0\n",
    "#endif\n",
    "#if EXTC_RC_SHADE_GUARD\n",
    "static long long extc_rc_sgHits, extc_rc_sgBad;\n",
    "static void extc_rc_sgDump(void) {\n",
    "    fprintf(stderr, \"[sg] hits=%lld bad=%lld\\n\", extc_rc_sgHits, extc_rc_sgBad);\n",
    "}\n",
    "static void extc_rc_sgArm(void) {\n",
    "    static int _a;\n",
    "    if (!_a) { _a = 1; atexit(extc_rc_sgDump); }\n",
    "}\n",
    "static void extc_rc_sgVerify(void *v) {\n",
    "    extc_rc_sgArm();\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(v);\n",
    "    int ok = 0;\n",
    "    if (s && s->region) {\n",
    "        size_t i = extc_rc_slotOf(s, v);\n",
    "        ok = (s->mark[extc_rc_word(i)] & extc_rc_bit(i)) != 0;\n",
    "    }\n",
    "    extc_rc_sgHits++;\n",
    "    if (!ok) extc_rc_sgBad++;\n",
    "}\n",
    "#endif\n",
    "__attribute__((unused, noinline)) static void extc_rc_shadeSlow(void *v) {   /* cold half: never inline -- the inline decision tilts as runtime code grows; it can wobble by 1.6% Ir */\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(v);\n",
    "    /* `!extc_rc_wb` is already screened above, so `wb > 0` implies \"at least one region is marking\". With **exactly one** participating region\n",
    "     * that region is it, so `s->region->marking` is always true and this dependent read is redundant; only with several regions is a per-region test needed. */\n",
    "    if (!s || !s->region || (extc_rc_partN > 1 && !s->region->marking)) return;   /* skip:shade-outside */\n",
    "    size_t i = extc_rc_slotOf(s, v);\n",
    "    uint64_t bit = extc_rc_bit(i);\n",
    "    /* Ask first \"is it already black\": the vast majority of calls exit here, saving one `occ` bitmap read. Swapping the order does not change the result\n",
    "     * (with `occ == 0` both orders return), it is a pure ordering change. */\n",
    "    if (s->mark[extc_rc_word(i)] & bit) { extc_rc_shadeRemember(v); return; }   /* skip:shade-black */\n",
    "    if (!(s->occ[extc_rc_word(i)] & bit)) return;   /* skip:shade-free */\n",
    "    s->mark[extc_rc_word(i)] |= bit;\n",
    "    extc_rc_shadeRemember(v);   /* just marked black: the next barrier on the same pointer skips the whole section */\n",
    "    s->region->wbDebt++;   /* record debt: this step is marking work created by the mutator */\n",
    "    extc_rc_markPushForce(s->region, v);   /* a shaded object must be scanned once */\n",
    "}\n",
    "/* Barrier wrapper: inlined into every assignment point -- when no mark is in flight (the common case) two tests and out, without even a call;\n",
    " * only an in-flight mark pays one more call into the cold half. */\n",
    "__attribute__((unused)) static inline void extc_rc_shade(void *v) {\n",
    "    if (!extc_rc_wb || !v) return;   /* skip:shade-off */\n",
    "#if EXTC_RC_SHADE_GUARD\n",
    "    if (extc_rc_shadeKnown(v)) { extc_rc_sgVerify(v); return; }   /* skip:shade-known */\n",
    "#else\n",
    "    if (extc_rc_shadeKnown(v)) return;   /* skip:shade-known */\n",
    "#endif\n",
    "    extc_rc_shadeSlow(v);\n",
    "}\n",
    "/* Delete barrier (no-count tier only): in the no-count tier a **local slot** is not shaded (see initRef / initRefNoHold /\n",
    " * storeRefLocal); protection moves to the overwritten **old edge** -- shade the old value before overwriting a heap slot. Without it,\n",
    " * \"read a white object from a not-yet-scanned object, that edge is then deleted on the heap, and the white object is left with the local slot as its only source\"\n",
    " * would be judged dead when marking finishes.\n",
    " * When no mark is in flight (wb == 0) it costs one predicted-taken branch: not even *slot is read. */\n",
    "__attribute__((unused)) static inline void extc_rc_shadeOld(void *const *slot) {\n",
    "#if EXTC_RC_NOCOUNT\n",
    "    if (!extc_rc_wb || !slot) return;   /* skip:old-off */\n",
    "    extc_rc_shade(*slot);\n",
    "#else\n",
    "    (void)slot;\n",
    "#endif\n",
    "}\n",
    "/* Once per object initialization: -O1 does not inline across call sites, so every init point pays one more call+return.\n",
    " * Forced inline puts `*slot = v` and inc at the call site; a constant self-assignment point like `initRef(&p, p)` is folded away too. */\n",
    "__attribute__((unused)) static inline __attribute__((always_inline)) void extc_rc_initRef(void **slot, void *v) {\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "    extc_rc_shade(v);   /* no-count tier: local slots carry no barrier (shadeOld shades the deleted old edge instead) */\n",
    "#endif\n",
    "    *slot = v;\n",
    "    extc_rc_inc(v);\n",
    "}\n",
    "/* `...NoHold`: only store the slot, no increment. Call sites are chosen by the \"this frame will not settle\" analysis result (`planRcNoDec`) --\n",
    " * that function's dynamic range contains no `dec`, so omitting this `+1` never leaves an object one settle short. */\n",
    "__attribute__((unused)) static inline __attribute__((always_inline)) void extc_rc_initRefNoHold(void **slot, void *v) {\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "    extc_rc_shade(v);   /* no-count tier: local slots carry no barrier */\n",
    "#endif\n",
    "    *slot = v;\n",
    "}\n",
    "\n",
    "/* Overwrite an old value: read old + write + target increment + old decrement. Assigning the same value takes this path too, net change zero. */\n",
    "__attribute__((unused)) static void extc_rc_storeRef(void **slot, void *v) {\n",
    "    if (!slot) return;   /* skip:slot-null: no slot to update */\n",
    "    extc_rc_shade(v);\n",
    "    void *old = *slot;\n",
    "    extc_rc_shadeOld(slot);   /* delete barrier: an overwrite deletes the old edge */\n",
    "    *slot = v;\n",
    "    extc_rc_inc(v);\n",
    "    extc_rc_dec(old);\n",
    "}\n",
    "/* Assignment whose host region is **given statically by the caller**: saves the `ownSlab(owner)` lookup.\n",
    " *\n",
    " * Call sites: the host is a local object `new`'d in this function that is never reassigned (codegen's `rcFresh*` table).\n",
    " * The region is that allocation point's `regionOf` result -- byte-for-byte the same as the runtime lookup, just without the lookup.\n",
    " * Logic identical to `storeRefOwned` point by point (old decrement, new increment, cross-region registration). */\n",
    "/* Assignment where value and host are **in the same region** (proved at compile time), so this edge cannot cross regions:\n",
    " * registration, region comparison and two `ownSlab` lookups are all unnecessary. Only the write plus (in the count tier) the holder count.\n",
    " * Emitted and called in the no-count tier only: with counting on, `storeRefOwnedReg` still needs those two lookups for the holder count. */\n",
    "#if EXTC_RC_NOCOUNT\n",
    "__attribute__((unused)) static inline void extc_rc_storeRefSameRegion(void **slot, void *v) {   /* skip:same-region */\n",
    "    if (!slot) return;   /* skip:slot-null: no slot to update */\n",
    "    extc_rc_shadeOld(slot);\n",
    "    extc_rc_shade(v);\n",
    "    *slot = v;\n",
    "}\n",
    "#endif\n",
    "__attribute__((unused)) static inline void extc_rc_storeRefOwnedReg(void **slot, void *v,\n",
    "                                                                   ExtcRcRegion *host) {\n",
    "    extc_rc_shade(v);\n",
    "    EXTC_RC_TICK(1);   /* per-component timing (`EXTC_RC_TIME=1`) */\n",
    "    extc_rc_shadeOld(slot);   /* delete barrier: local slots have no barrier, so the old edge must be shaded at the delete point */\n",
    "    if (slot) {\n",
    "#if EXTC_RC_NOCOUNT\n",
    "        /* **Only one region participates in rc**, so cross-region edges are impossible (see the note in `notePart`), and on the assignment\n",
    "         * path the two `ownSlab` lookups and the region comparison are all skipped -- that was the most expensive stretch of the assignment path.\n",
    "         * The host's participation is **not recorded on the assignment side**: every rc slot's region recorded participation unconditionally\n",
    "         * when it was born (`extc_rc_alloc`); looking the region up again here would just pay another `ownSlab` (invariants R2/R3,\n",
    "         * see `tools/check_note_part.py`). */\n",
    "        if (extc_rc_partN > 1) {\n",
    "            ExtcRcSlab *sv = v ? extc_rc_ownSlab(v) : (ExtcRcSlab *)0;\n",
    "            /* Cross-region guard: **the new value must still be looked up** (the first cross-region write is what sets foreign);\n",
    "             * the old value can have a registration to undo only if \"a foreign pointer has appeared in this region\", so otherwise skip that lookup. */\n",
    "            if (host && sv && sv->region != host) { extc_rc_rsIncSlab(sv, v); host->foreign = 1; }\n",
    "            if (host && host->foreign) { void *old = *slot; ExtcRcSlab *sold = old ? extc_rc_ownSlab(old) : (ExtcRcSlab *)0; if (sold && sold->region != host) extc_rc_rsDecSlab(sold, old); }\n",
    "#if EXTC_RC_FOREIGN_GUARD\n",
    "            if (host && !host->foreign) { void *old = *slot; if (old) { extc_rc_fgChecks++; { ExtcRcSlab *_gs = extc_rc_ownSlab(old); if (_gs && _gs->region != host) extc_rc_fgBad++; } } }\n",
    "#endif\n",
    "        }\n",
    "#else\n",
    "        void       *old  = *slot;\n",
    "        ExtcRcSlab *sold = old ? extc_rc_ownSlab(old) : (ExtcRcSlab *)0;\n",
    "        ExtcRcSlab *sv   = v   ? extc_rc_ownSlab(v)   : (ExtcRcSlab *)0;\n",
    "        if (host) {\n",
    "            if (sv && sv->region != host) { extc_rc_rsIncSlab(sv, v); host->foreign = 1; }\n",
    "            if (host->foreign && sold && sold->region != host) extc_rc_rsDecSlab(sold, old);\n",
    "        }\n",
    "#endif\n",
    "        *slot = v;\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "        if (sv)   extc_rc_holdUpdSlab(sv, v, +1);\n",
    "        if (sold) extc_rc_holdUpdSlab(sold, old, -1);\n",
    "#endif\n",
    "        return;\n",
    "    }\n",
    "    /* NULL slot: there is no slot to update. */\n",
    "}\n",
    "\n",
    "/* ---- Source-side bookkeeping entries for cross-region edges + counting statistics [rt:xentry] ----\n",
    " *\n",
    " * `owner` is **the object that holds this slot** (`a->f = v` passes `a`, `*p = v` passes `p`); for something that is not a slot of this\n",
    " * runtime (a local variable, a board/pool/stack pointer) it passes null and registration does not apply -- references there are covered by the trigger point's root table.\n",
    " * Only **cross-region** edges move counters: the same edge inside one region is reached by that region's own marking, so no seed is needed.\n",
    " * The statistic `rs_live = rsInc - rsDec` is the current number of live cross-region edges; with `EXTC_RC_STATS=1` one line is printed\n",
    " * at process exit, to show it does not grow without bound with the number of rounds. */\n",
    "__attribute__((unused)) static void extc_rc_statsDump(void) {\n",
    "    fprintf(stderr, \"extc_rc_stats rs_inc=%lld rs_dec=%lld rs_live=%lld rs_hwm=%lld\"\n",
    "                    \" releases=%lld release_slots=%lld\\n\",\n",
    "            (long long)extc_rc_rsIncN, (long long)extc_rc_rsDecN,\n",
    "            (long long)(extc_rc_rsIncN - extc_rc_rsDecN), (long long)extc_rc_rsHwm,\n",
    "            (long long)extc_rc_relN, (long long)extc_rc_relSlots);\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_statsArm(void) {\n",
    "#if EXTC_RC_FOREIGN_GUARD\n",
    "    extc_rc_fgArm();\n",
    "#endif\n",
    "    static int armed;\n",
    "    if (armed) return;   /* skip:armed */\n",
    "    armed = 1;\n",
    "    if (getenv(\"EXTC_RC_STATS\")) atexit(extc_rc_statsDump);\n",
    "}\n",
    "\n",
    "/* Forced inline: with the cache lookup added, `-O1` decides **not** to inline this function (it becomes a 25.9 M Ir\n",
    " * separate function on its own and total instruction count grows 8% instead) -- it is the hot path of every assignment point and must be inlined; a bigger wrapper should not change that decision. */\n",
    "__attribute__((always_inline)) __attribute__((unused)) static inline void extc_rc_storeRefOwned(void **slot, void *v, void *owner) {\n",
    "    extc_rc_shade(v);\n",
    "    EXTC_RC_TICK(2);   /* per-component timing (`EXTC_RC_TIME=1`) */\n",
    "    extc_rc_shadeOld(slot);   /* delete barrier: local slots have no barrier, so the old edge must be shaded at the delete point */\n",
    "    if (slot) {\n",
    "        /* Look up the registration table once per distinct pointer: owner / old value / new value, one each; afterwards all bookkeeping goes through\n",
    "         * the `*Slab` variants. The three chains could look up the same pointers up to 7 times (once each + rsInc/rsDec\n",
    "         * + again inside inc/dec), and the lookup itself became the most expensive thing on the assignment path. */\n",
    "#if EXTC_RC_NOCOUNT\n",
    "        if (extc_rc_partN > 1) {\n",
    "            ExtcRcSlab *so   = owner ? extc_rc_ownSlab(owner) : (ExtcRcSlab *)0;\n",
    "            ExtcRcSlab *sv   = v     ? extc_rc_ownSlab(v)     : (ExtcRcSlab *)0;\n",
    "            if (so) {\n",
    "                ExtcRcRegion *r = so->region;\n",
    "                if (sv && sv->region != r) { extc_rc_rsIncSlab(sv, v); r->foreign = 1; }\n",
    "                if (r->foreign) { void *old = *slot; ExtcRcSlab *sold = old ? extc_rc_ownSlab(old) : (ExtcRcSlab *)0; if (sold && sold->region != r) extc_rc_rsDecSlab(sold, old); }\n",
    "#if EXTC_RC_FOREIGN_GUARD\n",
    "                if (!r->foreign) { void *old = *slot; if (old) { extc_rc_fgChecks++; { ExtcRcSlab *_gs = extc_rc_ownSlab(old); if (_gs && _gs->region != r) extc_rc_fgBad++; } } }\n",
    "#endif\n",
    "            }\n",
    "        }\n",
    "#else\n",
    "        ExtcRcSlab *so   = owner ? extc_rc_ownSlab(owner) : (ExtcRcSlab *)0;\n",
    "        void       *old  = *slot;                    /* must be read before the write */\n",
    "        ExtcRcSlab *sold = old ? extc_rc_ownSlab(old) : (ExtcRcSlab *)0;\n",
    "        ExtcRcSlab *sv   = v   ? extc_rc_ownSlab(v)   : (ExtcRcSlab *)0;\n",
    "        if (so) {\n",
    "            ExtcRcRegion *r = so->region;\n",
    "            if (sv && sv->region != r) { extc_rc_rsIncSlab(sv, v); r->foreign = 1; }\n",
    "            if (r->foreign && sold && sold->region != r) extc_rc_rsDecSlab(sold, old);\n",
    "        }\n",
    "#endif\n",
    "        *slot = v;\n",
    "#if !EXTC_RC_NOCOUNT\n",
    "        /* When `sold`/`sv` is null this count has no effect (the first line of holdUpd is the same lookup). */\n",
    "        if (sv)   extc_rc_holdUpdSlab(sv, v, +1);\n",
    "        if (sold) extc_rc_holdUpdSlab(sold, old, -1);\n",
    "#endif\n",
    "        return;\n",
    "    }\n",
    "    /* NULL slot: there is no slot to update. */\n",
    "}\n",
    "\n",
        "/* ---- Slots whose host cannot be proven: pin the value itself as a root [rt:pin] ---------------------------------------\n",
    " *\n",
    " * The **host** of a view element (`v[0].kids[0] = r`) or of a pool buffer slot cannot be traced at compile time, but the value stored in the slot is\n",
    " * an rc object. The old scheme put the whole **target region** into noSweep (permanently out of sweeping, relying on count-to-zero). Instead, pin the value as\n",
    " * a root: during marking the pinned value is a seed and the target region is swept as usual; on overwrite the old value's pin is removed. Granularity therefore moves from\n",
    " * \"region\" down to \"pointed-to object\" -- garbage in the same region that no such slot points to is still collected.\n",
    " *\n",
    " * Structure: an **open-addressed hash table** (key = value pointer, load <= 1/2, deletion by Knuth backward shift). In a shape the pin table\n",
    " * can grow to hundreds of thousands of entries (one new object per view element), so a linear scan would make \"register n\" O(n^2); each entry\n",
    " * also stores an `rg` (computed once by ownSlab at registration), so round start / region death only compares region pointers, no per-entry lookup.\n",
    " *\n",
    " * Direction: only when pinning is impossible (allocation failure) fall back to noSweep -- better to collect less than to free live objects with an incomplete seed set.\n",
    " * Threads: the pin table is process-wide (a region may be swept by another worker), so insert/remove and round start take the lock; only the cold\n",
    " * unknown-host assignment path and the start of a whole mark round touch it, the hot paths (ordinary reference assignments, allocation) never look at it. */\n",
    "typedef struct ExtcRcPin { void *v; ExtcRcRegion *rg; size_t n; } ExtcRcPin;\n",
    "static ExtcRcPin *extc_rc_pins;\n",
    "static size_t extc_rc_pinN, extc_rc_pinCap;   /* pinCap is a power of two; pinN = number of occupied cells */\n",
    "static int    extc_rc_pinLock;\n",
    "static inline void extc_rc_pinLockAcq(void) {\n",
    "    while (__atomic_exchange_n(&extc_rc_pinLock, 1, __ATOMIC_ACQUIRE)) { }\n",
    "}\n",
    "static inline void extc_rc_pinUnlock(void) {\n",
    "    __atomic_store_n(&extc_rc_pinLock, 0, __ATOMIC_RELEASE);\n",
    "}\n",
    "static inline size_t extc_rc_pinHashOf(void *v) {\n",
    "    return (size_t)((((uintptr_t)v >> 3) * (uintptr_t)0x9E3779B97F4A7C15ull) >> 32);\n",
    "}\n",
    "/* Delete cell i: Knuth backward shift, keeping the probe chain intact (same method as the block registry). */\n",
    "static __attribute__((unused)) void extc_rc_pinEraseAt(size_t i) {\n",
    "    size_t cap = extc_rc_pinCap, mask = cap - 1, hole = i, j = i;\n",
    "    for (;;) {\n",
    "        j = (j + 1) & mask;   /* scan position advances independently; hole is the cell to fill */\n",
    "        if (!extc_rc_pins[j].v) break;\n",
    "        size_t k = extc_rc_pinHashOf(extc_rc_pins[j].v) & (cap - 1);\n",
    "        /* Only the probe chain matters: if k falls in (hole, j], moving it would break its probe chain */\n",
    "        int inRange = (hole <= j) ? (k > hole && k <= j) : (k > hole || k <= j);\n",
    "        if (!inRange) { extc_rc_pins[hole] = extc_rc_pins[j]; hole = j; }\n",
    "    }\n",
    "    extc_rc_pins[hole].v = (void *)0; extc_rc_pins[hole].rg = (ExtcRcRegion *)0;\n",
    "    extc_rc_pins[hole].n = 0; extc_rc_pinN--;\n",
    "}\n",
    "/* Double the capacity and rehash (returns 0 on failure; the caller falls back to noSweep). */\n",
    "static __attribute__((unused)) int extc_rc_pinGrow(void) {\n",
    "    size_t cap = extc_rc_pinCap ? extc_rc_pinCap * 2 : 128, mask = cap - 1;\n",
    "    ExtcRcPin *p = (ExtcRcPin *)calloc(cap, sizeof *p);\n",
    "    if (!p) return 0;   /* skip:pin-oom */\n",
    "    for (size_t i = 0; i < extc_rc_pinCap; i++) {\n",
    "        if (!extc_rc_pins[i].v) continue;\n",
    "        size_t h = extc_rc_pinHashOf(extc_rc_pins[i].v) & mask;\n",
    "        while (p[h].v) h = (h + 1) & mask;\n",
    "        p[h] = extc_rc_pins[i];\n",
    "    }\n",
    "    free(extc_rc_pins);\n",
    "    extc_rc_pins = p; extc_rc_pinCap = cap;\n",
    "    return 1;\n",
    "}\n",
    "/* Returns 0 = cannot pin (out of memory). The caller must fall back to the conservative direction. */\n",
    "__attribute__((unused)) static int extc_rc_pinAdd(void *v) {\n",
    "    if (!v || !extc_rc_owns(v)) return 1;   /* not a live slot of this runtime, so not a reference and nothing to pin */   /* skip:pin-not-obj */\n",
    "    extc_rc_pinLockAcq();\n",
    "    if ((extc_rc_pinN + 1) * 2 > extc_rc_pinCap && !extc_rc_pinGrow()) {\n",
    "        extc_rc_pinUnlock();\n",
    "        return 0;\n",
    "    }\n",
    "    size_t mask = extc_rc_pinCap - 1;\n",
    "    size_t h = extc_rc_pinHashOf(v) & mask;\n",
    "    while (extc_rc_pins[h].v && extc_rc_pins[h].v != v) h = (h + 1) & mask;\n",
    "    if (extc_rc_pins[h].v) {\n",
    "        extc_rc_pins[h].n++;\n",
    "    } else {\n",
    "        ExtcRcSlab *ps = extc_rc_ownSlab(v);\n",
    "        extc_rc_pins[h].v = v;\n",
    "        extc_rc_pins[h].rg = ps ? ps->region : (ExtcRcRegion *)0;\n",
    "        extc_rc_pins[h].n = 1;\n",
    "        extc_rc_pinN++;\n",
    "    }\n",
    "    extc_rc_pinUnlock();\n",
    "    return 1;\n",
    "}\n",
    "static __attribute__((unused)) void extc_rc_pinSub(void *v) {\n",
    "    if (!v) return;   /* skip:pin-null */\n",
    "    extc_rc_pinLockAcq();\n",
    "    if (extc_rc_pinN) {\n",
    "        size_t mask = extc_rc_pinCap - 1;\n",
    "        size_t h = extc_rc_pinHashOf(v) & mask;\n",
    "        while (extc_rc_pins[h].v && extc_rc_pins[h].v != v) h = (h + 1) & mask;\n",
    "        if (extc_rc_pins[h].v) {\n",
    "            if (extc_rc_pins[h].n > 1) extc_rc_pins[h].n--;\n",
    "            else extc_rc_pinEraseAt(h);\n",
    "        }\n",
    "    }\n",
    "    extc_rc_pinUnlock();\n",
    "}\n",
    "/* Region is dying: objects it owns need no pinning (leaving the entries would only make marking walk dead values). */\n",
    "static __attribute__((unused)) void extc_rc_pinDropRegion(ExtcRcRegion *r) {\n",
    "    if (__atomic_load_n(&extc_rc_pinN, __ATOMIC_ACQUIRE) == 0) return;   /* skip:pin-empty */\n",
    "    extc_rc_pinLockAcq();\n",
    "    size_t i = 0;\n",
    "    while (i < extc_rc_pinCap) {\n",
    "        if (!extc_rc_pins[i].v) { i++; continue; }   /* skip:pin-hole */\n",
    "        if (extc_rc_pins[i].rg == r) { extc_rc_pinEraseAt(i); continue; }   /* skip:pin-dead */\n",
    "        i++;\n",
    "    }\n",
    "    extc_rc_pinUnlock();\n",
    "}\n",
    "/* Round start: pinned values are **roots** -- they are references stored in other slots, only the slots themselves are not in an rc slab.\n",
    " * Push only objects of this region; objects of other regions are handled by their own round. */\n",
    "/* An empty table is **the common case** (the vast majority of programs have no host-less slot at all): this line reads pinN once atomically and returns.\n",
     " * Why not inline it into markBegin: inline makes markBegin longer, and GCC's inlining and scheduling of the whole mark/allocation chain change\n",
     " * with it -- owed_home pays +2 Ir per allocation (145,022,121 -> 147,581,549, +1.76%),\n",
     " * while the pin table is **never used** in that shape. With noinline it returns to the baseline bit for bit (145,022,214). */\n",
     "static __attribute__((unused)) __attribute__((noinline)) void extc_rc_pinSeed(ExtcRcRegion *r) {\n",
    "    if (__atomic_load_n(&extc_rc_pinN, __ATOMIC_ACQUIRE) == 0) return;   /* skip:pin-empty */\n",
    "    extc_rc_pinLockAcq();\n",
    "    for (size_t i = 0; i < extc_rc_pinCap; i++) {\n",
    "        if (!extc_rc_pins[i].v) continue;   /* skip:pin-hole */\n",
    "        if (extc_rc_pins[i].rg == r) extc_rc_markPush(r, extc_rc_pins[i].v);\n",
    "    }\n",
    "    extc_rc_pinUnlock();\n",
    "}\n",
"/* Reference assignment whose host cannot be proven (`f()->f = v`, view element `a[i] = v`, ...): the registration site is unknown (the source object\n",
    " * is not known), and the static root table has no such slot either. Pin the value as a root (see above); only when pinning fails, make **the region the target lives in**\n",
    " * leave sweeping entirely: better to collect less than to free objects that are still pointed to while the seed set is incomplete. */\n",
    "__attribute__((unused)) static void extc_rc_storeRefUnknown(void **slot, void *v) {\n",
    "    if (!slot) return;   /* skip:slot-null: no slot to update */\n",
    "    extc_rc_shade(v);\n",
    "    void *old = *slot;\n",
    "    if (old) extc_rc_pinSub(old);   /* overwrite deletes the old edge: no slot points at the old value any more */\n",
    "    if (!extc_rc_pinAdd(v)) {\n",
    "        ExtcRcRegion *r = extc_rc_regionOfOwn(v);\n",
    "        if (r) r->noSweep = 1;\n",
    "    }\n",
    "    extc_rc_storeRef(slot, v);\n",
    "}\n",
    "\n",
    "/* Slot-address reverse lookup: which registered rc slab's data area contains this **arbitrary byte address**.\n",
    " *\n",
    " * ownSlab only accepts a slot start (it answers \"is this some object's slot\", verifying `k * ss == off`); when the host expression\n",
    " * cannot be proven (`(*id(s)).kids[0] = v`) the question is the weaker \"which region owns this memory\" --\n",
    " * a slab's data area belongs entirely to one region, so no slot start is needed. Huge blocks (payload not in an aligned block) cannot be located by mask\n",
    " * so return 0 and let the caller fall back to the conservative path. */\n",
    "__attribute__((unused)) static ExtcRcSlab *extc_rc_slabOfInterior(void *p) {\n",
    "    void *base = (void *)((uintptr_t)p & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1));\n",
    "    ExtcRcSlab *s = extc_rc_ownHot;\n",
    "    if (s && (void *)s != base) s = (ExtcRcSlab *)0;\n",
    "    if (!s) {\n",
    "        s = extc_rc_ownMap[extc_rc_ownHashOf(base)];\n",
    "        if (!s || (void *)s != base) {\n",
    "            s = extc_rc_ownProbeFast(base, 0);\n",
    "        }\n",
    "    }\n",
    "    if (!s) return (ExtcRcSlab *)0;   /* skip:host-slab */\n",
    "    if (extc_rc_offOf(s, p) >= (size_t)s->nslots * s->ss) return (ExtcRcSlab *)0;   /* skip:host-slab */\n",
    "    return s;\n",
    "}\n",
    "\n",
    "/* The host expression cannot be proven, but **the slot address itself** falls inside an rc slot (`(*id(s)).kids[0] = v`): the slab the slot\n",
    " * belongs to tells us the region that holds it, so this edge is bookkept as \"host known\" as usual (cross-region registration, old-value undo),\n",
    " * without making the target region leave sweeping entirely. Only when the slot is not in an rc slab either (view data, C/pool buffers) does it fall back\n",
    " * to the conservative direction of `storeRefUnknown`. Cost is the same order as the fallback path: that path looks up `ownSlab` anyway. */\n",
    "__attribute__((unused)) static inline void extc_rc_storeRefSlot(void **slot, void *v) {\n",
    "    if (!slot) return;   /* skip:slot-null: no slot to update */\n",
    "    ExtcRcSlab *ss = (slot ? extc_rc_slabOfInterior((void *)slot) : (ExtcRcSlab *)0);\n",
    "    if (ss && ss->region) { extc_rc_storeRefOwnedReg(slot, v, ss->region); return; }\n",
    "    extc_rc_storeRefUnknown(slot, v);\n",
    "}\n",
    "\n",
    "/* Entry for bookkeeping of whole-value stores (struct / fixed-size array **copied by value**) that carry reference leaves, when the leaves **cannot be enumerated**\n",
    " * (an enumerated payload, a generic argument carrying references): the whole block is already copied, so here every word in the target that \"is a live slot\"\n",
    " * is treated as a candidate reference -- **increment only, never decrement** + register cross-region edges (when the host is unprovable, instead let those target regions leave\n",
    " * sweeping). The direction matches the marking of `EXTC_RC_CONSERVATIVE`: misreading one word must cost \"keep it longer\",\n",
    " * never \"count one fewer reference\" (one fewer means freeing early). The old value is therefore not decremented -- better reclaimed late.\n",
    " *\n",
    " * Enumerable whole-value stores do not come here: codegen emits `initRef` / `storeRefOwned` /\n",
    " * `storeRefUnknown` per leaf, the same path as a direct reference-slot assignment (decrement the old, increment the new). */\n",
    "__attribute__((unused)) static void extc_rc_storeStructCons(void *dst, size_t size,\n",
    "                                                            void *owner, int hostKnown) {\n",
    "    ExtcRcRegion *r = hostKnown ? extc_rc_regionOfOwn(owner) : (ExtcRcRegion *)0;\n",
    "    extc_rc_notePart(r);   /* this path also registers cross-region edges, so the host must be counted in the participating-region number\n",
    "                            * (rule R1 of `tools/check_note_part.py` guards exactly this) */\n",
    "    size_t words = size / sizeof(void *);\n",
    "    for (size_t i = 0; i < words; i++) {\n",
    "        void *nw = ((void **)dst)[i];\n",
    "        extc_rc_shade(nw);   /* a struct copy also writes references: shade leaf by leaf, otherwise incremental marking misses them */\n",
    "        if (!extc_rc_owns(nw)) continue;          /* not a live slot of this runtime, so not a reference */\n",
    "        ExtcRcRegion *rv = extc_rc_regionOfOwn(nw);\n",
    "        /* Guard aligned word for word with storeRefOwned / storeRefUnknown: register only when the host **really proves a region**\n",
    "         * (`r == 0` = local/static slot, a registration bit there could never be undone; the root table is its seed); when unprovable, make the target region\n",
    "         * leave sweeping. Without the `r` test, a conservative store into a local would leave a registration bit that is never undone. */\n",
    "        if (hostKnown) { if (r && rv && rv != r) { extc_rc_rsInc(nw); r->foreign = 1; } }\n",
    "        else if (rv) rv->noSweep = 1;\n",
    "        extc_rc_inc(nw);\n",
    "    }\n",
    "}\n",
    "\n",
    "/* Entry for a whole-value store into a **local variable registered in the root table** (`var m: maybe = ...`): the leaves cannot be enumerated\n",
    " * (an enumerated payload), but their references are all in this value's own words. Treat each word as a candidate reference and increment only -- the only difference from\n",
    " * `extc_rc_storeStructCons`'s `hostKnown = 0` path is that the target region is **not** made to leave\n",
    " * sweeping: the caller has already registered this value's reference leaves as roots, statically expanded for **every** enum variant (the TY_ENUM branch\n",
    " * of `rcRootLeaves`), so the references are claimed by both \"counting\" and \"root-table seeds\" and the region is swept as usual.\n",
    " *\n",
    " * No cross-region edges registered: the host is a local on the stack, with no registration bit to undo; cross-region reachability is covered by the root-table seed\n",
    " * (the same reason as the conservative side of `extc_rc_storeStructCons`). */\n",
    "__attribute__((unused)) static void extc_rc_storeStructRooted(void *dst, size_t size) {\n",
    "    size_t words = size / sizeof(void *);\n",
    "    for (size_t i = 0; i < words; i++) {\n",
    "        void *nw = ((void **)dst)[i];\n",
    "        extc_rc_shade(nw);   /* a struct copy also writes references: shade leaf by leaf, otherwise incremental marking misses them */\n",
    "        if (!extc_rc_owns(nw)) continue;          /* not a live slot of this runtime, so not a reference */\n",
    "        extc_rc_inc(nw);\n",
    "    }\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static uint16_t extc_rc_hold(void *p) {\n",
    "#if EXTC_RC_NOCOUNT\n",
    "    (void)p;\n",
    "    return 0;   /* no-count tier: the `hold` array does not exist (nothing allocates it since the sixteenth cut) */\n",
    "#else\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(p);\n",
    "    if (!s) return 0;   /* skip:not-own */\n",
    "    size_t i = extc_rc_slotOf(s, p);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return 0;   /* skip:occ-free */\n",
    "    return s->hold[i];\n",
    "#endif\n",
    "}\n",
    "\n",
    "/* Read-only accessor for the cross-region in-edge count (`rscnt`): the criterion uses it to check the \"sticks at the ceiling\" guard --\n",
    " * a count wrapping to 0 would make \"there are still live in-edges\" false, and the target could be swept while it still has in-edges. */\n",
    "__attribute__((unused)) static uint16_t extc_rc_rsCount(void *p) {\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(p);\n",
    "    if (!s) return 0;   /* skip:not-own */\n",
    "    size_t i = extc_rc_slotOf(s, p);\n",
    "    if (!(s->occ[extc_rc_word(i)] & extc_rc_bit(i))) return 0;   /* skip:occ-free */\n",
    "    if (!s->rscnt) return 0;   /* skip:rscnt-none */\n",
    "    return s->rscnt[i];\n",
    "}\n",
    "\n",
    "/* Cross-region registration: set a bit in the **target slot's** registration bitmap. Dedup means repeated registration costs nothing;\n",
    " * the bit is cleared by extc_rc_freeSlot when the slot is released, so no stale entry (obligations 2, 5). */\n",
    "__attribute__((unused)) static void extc_rc_register(void *p) {\n",
    "    if (!extc_rc_owns(p)) return;    /* not a live slot of this runtime, so registration does not apply */   /* skip:not-own */\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(p);\n",
    "    size_t i = extc_rc_slotOf(s, p);\n",
    "    if (s->rsbit[extc_rc_word(i)] & extc_rc_bit(i)) return;   /* skip:reg-dup */\n",
    "    s->rsbit[extc_rc_word(i)] |= extc_rc_bit(i); s->region->seedAny = 1;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static int extc_rc_isRegistered(void *p) {\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(p);\n",
    "    if (!s) return 0;   /* skip:not-own */\n",
    "    size_t i = extc_rc_slotOf(s, p);\n",
    "    return (s->rsbit[extc_rc_word(i)] >> (i & 63)) & 1;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static int extc_rc_isLive(void *p) {\n",
    "    return extc_rc_owns(p);\n",
    "}\n",
    "\n",
    "/* Resolution region: bump allocation, O(1); reset moves the pointer back and returns the whole span. A bump object is not a slab slot,\n",
    " * so it cannot enter inc/dec/register and does not count toward region occupied bytes (the span goes back on reset). */\n",
    "__attribute__((unused)) static void *extc_rc_bump(ExtcRcRegion *r, size_t n) {\n",
    "    /* `notePart` is **not** recorded here: bump slots never set the occupied bit, and `rsIncSlab`/`rsDecSlab` always\n",
    "     * return early for them, so per-slot registration does not apply to bump objects anyway (their reclamation is a whole-span reset). Since registration\n",
    "     * can never happen on a bump slot, the gate skipping it for them is equivalent -- recording it would only disable the fast path for nothing. */\n",    "    size_t ss = extc_rc_slotSize(n);\n",
    "    if (!r->bump || (size_t)(r->bump_end - r->bump) < ss) {\n",
    "        ExtcRcSlab *s = extc_rc_slabNew(r, ss);\n",
    "        s->next = r->slabs;\n",
    "        r->slabs = s;\n",
    "        r->bumpSlab = s;\n",
    "        r->bump = EXTC_RC_SLAB_DATA(s);\n",
    "        r->bump_end = r->bump + (size_t)s->nslots * s->ss;\n",
    "    }\n",
    "    void *p = r->bump;\n",
    "    r->bump += ss;\n",
    "    memset(p, 0, ss);\n",
    "    return p;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_bumpReset(ExtcRcRegion *r) {\n",
    "    if (!r->bumpSlab) return;   /* skip:no-bumpslab */\n",
    "    r->bump = EXTC_RC_SLAB_DATA(r->bumpSlab);\n",
    "    r->bump_end = r->bump + (size_t)r->bumpSlab->nslots * r->bumpSlab->ss;\n",
    "}\n",
    "\n",
    "/* Region: the type descriptor goes to the runtime with the slot, so here only a number is claimed. */\n",
    "static void extc_rc_thrUpd(ExtcRcRegion *r);   /* threshold recompute: defined in the shouldSweep section */\n",
    "__attribute__((unused)) static ExtcRcRegion *extc_rc_regionNew(int32_t rid) {\n",
    "    EXTC_RC_TICK(6);   /* per-component timing (`EXTC_RC_TIME=1`) */\n",
    "    ExtcRcRegion *r = (ExtcRcRegion *)calloc(1, sizeof(ExtcRcRegion));\n",
    "    if (!r) extc_rc_oops(\"region allocation failed\");\n",
    "    r->rid = rid;\n",
    "    r->floor = EXTC_RC_FLOOR;\n",
    "    extc_rc_thrUpd(r);\n",
    "    extc_rc_statsArm();   /* with EXTC_RC_STATS=1 print cross-region registration statistics at process exit */\n",
    "    return r;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_regionFloor(ExtcRcRegion *r, int64_t bytes) {\n",
    "    r->floor = bytes > 0 ? bytes : 1;\n",
    "    extc_rc_thrUpd(r);\n",
    "}\n",
    "\n",
    "/* One O(live set) traversal (region sweep **or** targeted release on overwrite) must be paid for by \"new allocations since the last traversal\".\n",
    " * Without this, targeted release means \"one reference assignment costs one full live-set mark\", so N assignments = O(N^2).\n",
    " * Sweeping already satisfies it (the trigger line `thr = max(2*live, floor)*scale >= need`), the only breach is release.\n",
    " * `live` is the live bytes after the previous sweep; when a region has never been swept live = 0, and the lower bound `floor` takes over.\n",
    " * Failure direction: with too little credit, collect **less** (garbage lingers, memory grows), never a dangling pointer. */\n",
    "__attribute__((unused)) static int extc_rc_budgetOk(const ExtcRcRegion *r) {\n",
    "    int64_t need = r->live > r->floor ? r->live : r->floor;\n",
    "    return r->allocBytes - r->visitedBytes >= need;\n",
    "}\n",
    "\n",
    "/** @brief When a region is dying, **cancel** the round in flight (mark + sweep), do not drain.\n",
    " *\n",
    " * Why cancellation is allowed: `regionFree` frees all of this region's slabs right afterwards, so\n",
    " * every object in the region **has ceased to exist** and \"finished marking / finished sweeping\" changes no observable fact:\n",
    " *   - `mstk` is a **work list**, not a root: its entries (including objects of other regions) hold no ownership,\n",
    " *     they can vanish with `free(r->mstk)`; other regions' mark stacks are unaffected.\n",
    " *   - mark bits and the sweep cursor live in this region's slabs and are freed with them.\n",
    " *   - cross-region registrations (`rsbit`/`rscnt`) are undone via `occ` + `unlinkChildren`, which **do not read mark bits**, so\n",
    " *     cancelling marking does not affect the bulk undo below.\n",
    " *   - the accounts (`sweeps`/`freedSlots`/`live`) have only this region as reader, and `r` is freed right after.\n",
    " * The one thing that must be preserved is the **global barrier participant count** `extc_rc_wb` (R3): it is +1 in `extc_rc_begin` and\n",
    " * -1 by `extc_rc_finish` when leaving marking. Cancelling must -1 too, otherwise the barrier (`shade`'s first branch)\n",
    " * stays open forever, so every later assignment pays one more `ownSlab` lookup. The direction is **performance**, not safety, but it is a real\n",
    " * invariant, so this function's **paired self-check** guards it: `r->marking` true means this region contributed a +1,\n",
    " * so the **old value** of the atomic decrement must be >= 1: the old value is the count seen before decrementing, 0 means no +1 was contributed or the update was lost (underflow).\n",
    " * Note the criterion **cannot** be \"wb == 0 on exit\": a program need not `regionDrop` (digraph has no drop point,\n",
    " * regions go back to the OS when the process ends), and then wb > 0 is legal -- the invariant is **pairing**, not zero. */\n",
    "__attribute__((unused)) static void extc_rc_abort(ExtcRcRegion *r) {\n",
    "    if (r->marking) {\n",
    "        int _wb0;\n",
    "        r->marking = 0;\n",
    "        r->markDone = 0;\n",
    "        _wb0 = extc_rc_wbAdd(-1);\n",
    "        if (_wb0 < 1) extc_rc_oops(\"R4: barrier participant underflow on region drop\");\n",
    "    }\n",
    "    r->sweeping = 0;   /* the sweep cursor vanishes with the slabs */\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_regionFree(ExtcRcRegion *r) {\n",
    "    if (!r) return;   /* skip:no-region */\n",
    "    extc_rc_shadeNextGen();   /* slab payload goes back to malloc: the address may be reused by another object, so black records are void */\n",
    "    /* R3: a **run-time guard** on the participating-region number (cold path; one predictable branch while `part` is true).\n",
    "     * `part == 0` yet there are still occupied slots means some path that \"hands out an rc slot\" did not record participation, and the single-region\n",
    "     * fast path would be wrongly disabled while cross-region in-edges exist; the failure direction is **unsafe**. Slots can only come from\n",
    "     * `extc_rc_alloc`, so this guard has the same source as static rule R2 (see check_note_part.py). */\n",
    "    if (!r->part) {\n",
    "        ExtcRcSlab *q = r->slabs;\n",
    "        while (q) {\n",
    "            for (size_t _w = 0; _w < q->nwords; _w++)\n",
    "                if (q->occ[_w]) extc_rc_oops(\"R3: occupied slot in a region with part == 0\");\n",
    "            q = q->next;\n",
    "        }\n",
    "    }\n",
    "    extc_rc_abort(r);   /* region is dying: cancel the round in flight, do not drain (see extc_rc_abort) */\n",
    "    extc_rc_pinDropRegion(r);   /* region is dying: objects of it in the pin table are not needed */\n",
    "    ExtcRcSlab *s = r->slabs;\n",
    "    while (s) {\n",
    "        ExtcRcSlab *n = s->next;\n",
    "        /* Bulk undo of the cross-region edges held by objects still alive in the region: the bits do not stick, so the next sweep\n",
    "         * of another region will not keep these targets as seeds. Slots already dead in the count (occ=0) are skipped.\n",
    "         *\n",
    "         * `extc_rc_rsIncN == 0` means **no cross-region registration ever happened** in this process, so there are no edges to undo and\n",
    "         * the whole walk is busywork (on a pure read-traversal shape this is a fixed per-object cost). */\n",
    "        if (extc_rc_rsIncN) for (uint32_t w = 0; w < s->nwords; w++) {\n",
    "            uint64_t bits = s->occ[w];\n",
    "            while (bits) {\n",
    "                uint32_t b = (uint32_t)__builtin_ctzll(bits);\n",
    "                bits &= bits - 1;\n",
    "                extc_rc_unlinkChildren(s, (size_t)w * 64 + b);\n",
    "            }\n",
    "        }\n",
    "        extc_rc_ownDel(s);   /* take it out of the registry first: this memory is about to stop being a slab */\n",
    "        free(s->occ); free(s->mark); free(s->rsbit); free(s->hold); free(s->rscnt);\n",
    "        free(s->tid); free(s->ttab); free(s->thash);\n",
    "        if (s->big) free(s->data);   /* a huge block's payload is a separate allocation, returned along with the region drop */\n",
    "        free(s);\n",
    "        s = n;\n",
    "    }\n",
    "    for (uint32_t b = 0; b < EXTC_RC_CLS_BUCKETS; b++) {\n",
    "        while (r->clsBkt[b]) {\n",
    "            ExtcRcClass *c = r->clsBkt[b];\n",
    "            r->clsBkt[b] = c->next;\n",
    "            free(c);\n",
    "        }\n",
    "    }\n",
    "    free(r->mstk);\n",
    "    free(r);\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_markPush(ExtcRcRegion *r, void *o) {\n",
    "    if (r->msp == r->mscap) {\n",
    "        size_t want = r->mscap ? r->mscap * 2 : 1024;\n",
    "        void **grown = (void **)realloc(r->mstk, want * sizeof(void *));\n",
    "        if (!grown) extc_rc_oops(\"mark stack allocation failed\");\n",
    "        r->mstk = grown;\n",
    "        r->mscap = want;\n",
    "    }\n",
    "    r->mstk[r->msp++] = o;\n",
    "}\n",
    "/* Push fast path: when `mstk` still has room, push directly (removes \"capacity check + call\" from every child object). */\n",
    "__attribute__((unused)) static inline void extc_rc_markPushFast(ExtcRcRegion *r, void *o) {\n",
    "    __builtin_prefetch(o, 0, 1);\n",
    "    if (r->msp < r->mscap) r->mstk[r->msp++] = o;\n",
    "    else extc_rc_markPush(r, o);\n",
    "}\n",
    "/* Forced push: set the low bit. The pop side (`markStep`) sees the low bit and skips the \"already marked so continue\" dedup,\n",
    " * so **an object shaded by the barrier is also scanned once**, and its white children are not missed; the push volume is unchanged, so\n",
    " * `wbDebt` and the shade dedup semantics are unchanged word for word from good-17. */\n",
    "__attribute__((unused)) static void extc_rc_markPushForce(ExtcRcRegion *r, void *o) {\n",
    "    extc_rc_markPush(r, (void *)((uintptr_t)o | (uintptr_t)1));\n",
    "}\n",
    "\n",
    "/* ---- Frame-root chain: replace the static value table with a chain maintained on the stack [rt:chain] ------------------------------\n",
    " *\n",
    " * Problem: roots are now materialized on the spot by codegen on every trigger path as a value table (copying the value of every reference slot in the current scope\n",
    " * into an array). Copying is itself a traversal, and the copies may already be out of step with the slots. The chain registers\n",
    " * slot addresses instead of values: every live reference slot is pushed together with its host frame, marking dereferences along the chain and reads the value at the moment it is used --\n",
    " * reassignments in the frame are visible automatically, and no table has to be generated per trigger path.\n",
    " *\n",
    " * Only the data structure goes into the emitted text for now; no emitter pushes onto the chain yet (see the frameRoots parameter of reclaimEmitRuntime),\n",
    " * so the chain is always empty and marking still uses only the static value table, word for word the same behavior as without this code. Wiring changes the emitter.\n",
    " *\n",
    " * bad = this frame's slot enumeration is incomplete (coroutine frames / ext frames / pool elements / view elements / match bindings, where the compiler cannot obtain\n",
    " * the complete slot list), so seeds would be missing and the whole chain refuses to sweep; nobody sets it yet, it will be set when wired. */\n",
    "typedef void **ExtcRcSlot;   /* address of one reference slot (addr[k] is the slot, *addr[k] is the value) */\n",
    "typedef struct ExtcRcFrameRoot {\n",
    "    ExtcRcSlot *addr;    /* array of slot addresses */\n",
    "    size_t  n;\n",
    "    struct ExtcRcFrameRoot *parent;\n",
    "    int     bad;\n",
    "} ExtcRcFrameRoot;\n",
    "static _Thread_local ExtcRcFrameRoot *extc_rc_chainTop;\n",
    "__attribute__((unused)) static void extc_rc_framePush(ExtcRcFrameRoot *fr, ExtcRcSlot *addr, size_t n) {\n",
    "    fr->addr = addr; fr->n = n; fr->bad = 0; fr->parent = extc_rc_chainTop;\n",
    "    extc_rc_chainTop = fr;\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_framePop(void) {\n",
    "    if (extc_rc_chainTop) extc_rc_chainTop = extc_rc_chainTop->parent;\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_frameBad(void) {\n",
    "    if (extc_rc_chainTop) extc_rc_chainTop->bad = 1;\n",
    "}\n",
    "/* whether the chain has a frame whose enumeration is incomplete, so seeds are incomplete and sweeping is refused (same decision as noSweep). */\n",
    "__attribute__((unused)) static int extc_rc_chainBad(void) {\n",
    "    for (ExtcRcFrameRoot *fr = extc_rc_chainTop; fr; fr = fr->parent)\n",
    "        if (fr->bad) return 1;   /* skip:chain-bad */\n",
    "    return 0;\n",
    "}\n",
    "\n",
    "/* ---- Owner depth of the thread-local arena [rt:tlsdepth] ------------------------------------------------\n",
    " *\n",
    " * Every allocation on a parallel::run worker chain goes through extc_tls_arena (the thread-local arena), and the whole chain shares one\n",
    " * region. Who may trigger a sweep on that region? The worker entry frame -- its only caller is the C runtime (there are no live references\n",
    " * in an outer extC frame), so its static root table at statement boundaries is a complete seed set. Inner frames' root tables cannot see the calling frame's live\n",
    " * references and can only record an owed reclaim, settled by the owner at its own call site (isomorphic to subset B of the home arena). The depth is\n",
    " * maintained by codegen in the prologue/epilogue of every worker chain: the entry frame reads 0, so it is the owner. One copy per thread; trap/exit\n",
    " * end the process directly, so no compensation is needed. */\n",
    "static _Thread_local int32_t extc_rc_tlsDepth __attribute__((unused));\n",
    "/* ---- Marking: start from roots and this region's registration bitmap, walk the region in steps [rt:mark] --------------------------------\n",
    " *\n",
    " * Walk only objects inside the region: stop at the region boundary and do not write the other region's mark bits -- leaving objects of another region marked would make it\n",
    " * skip them in its next sweep and free things that are still live; anything outside the region is treated as live.\n",
    " *\n",
    " * A pointer must pass owns before slabOf: roots and fields can both hold board/pool/stack/C pointers, and applying the mask\n",
    " * directly would read unrelated memory. */\n",
    "/** @brief Start a mark round: clear the stack, push roots, push cross-region seeds. */\n",
    "__attribute__((unused)) static void extc_rc_markBegin(ExtcRcRegion *r, void *const *roots, size_t nroots) {\n",
    "    r->msp = 0;\n",
    "    r->scanObj = (void *)0; r->scanOff = 0;   /* new round: the previous round's segment cursor does not carry over */\n",
    "    for (size_t i = 0; i < nroots; i++)\n",
    "        if (roots[i] && extc_rc_owns(roots[i])) extc_rc_markPush(r, roots[i]);\n",
    "    extc_rc_pinSeed(r);\n",    "    /* Frame-root chain seeding is switched on in **step 3**: step 2 only pushes the chain and trigger points still use the old root table; reading the chain here now\n",
    "     * would change semantics as soon as step 2 pushes (the design doc puts \"the chain really takes effect\" in step 3 and requires scan completeness to be accepted only then). */\n",
    "    r->seedSlab = r->slabs;   /* seeds are now pushed **in steps**: here only the cursor is set */\n",
    "    r->seedWord = 0;\n",
    "    r->seedBits = 0;   /* \"remaining bits of the current word\" for the unified budget: cleared at round start */\n",
    "    r->seedsDone = (r->slabs == NULL) || !r->seedAny;   /* no seed ever registered, so there is nothing to push and the whole scan is skipped */\n",
    "}\n",
    "/** @brief Stepped marking: scan at most budget objects; returns how many were scanned this round (empty stack = marking done). */\n",
    /* Same-slab dedupe of a sub-object looks only at the **mark bit** of the slot containing
       the address; it does not validate the slot start and does not check occ. A set mark means
       the slot was already blackened this round (walked, or blackened by alloc when allocated
       during marking), and the pop side rejects it on the same mark bit, so the early continue
       loses no reachability. Skipping the occ check is sound as well: with an empty slot whose
       mark is set, the push would be dropped by the pop side's occ check anyway, so the
       reachable set is the same. A non-slot-start pointer is judged a non-object by ownSlab on
       the pop side (skipped as out of region); deduping it early leaves the reachable set
       unchanged and saves the multiply-check per same-slab sub-object. */
    "/* The object-processing body is a macro: the batch path (deep stack) and the shallow fast path share one body. Batching (arrays, up to four, take the min,\n",
    " * fill loop, scan-batch loop) only amortizes well when the stack holds enough objects; when stack depth does not exceed\n",
    " * EXTC_RC_MARK_SHALLOW it is pure fixed cost, so a shallow stack pops and scans one directly. The macro takes no part in performance decisions,\n",
    " * it only lets both expansions share one body (two hand copies drift).\n",
    " *\n",
    " * Threshold choice: the shallow path processes one at a time and scans **immediately**, children are marked black and pushed on the spot, so duplicate pushes are deduped at the source;\n",
    " * batching defers \"mark black\" until the whole batch is popped, so duplicate pushes increase. A larger threshold makes dedup effective sooner, but with a mid-depth stack\n",
    " * it also gives up batch prefetch lead time -- it is a trade-off of \"dedup gain vs prefetch gain\", tuned per shape\n",
    " * (cyclic_pressure: 8 -> 88,852,305; 32 -> 87,922,567; 64 -> 87,823,666; 128 -> 87,910,790;\n",
    " * (256 -> 87,901,977 Ir, so 64 is best; deep-stack shapes like P5 almost always take the batch path and D1mr/DLmr are unchanged bit for bit). */\n",
    "#ifndef EXTC_RC_MARK_SHALLOW\n",
    "#define EXTC_RC_MARK_SHALLOW 64\n",
    "#endif\n",
    "/* Segment the scan of large objects: when one object holds very many pointers (a large array field, or a struct whose length is only known at run time),\n",
    " * scanning it is **single-step indivisible** work -- the single-step pause is proportional to object length. Segment it by EXTC_RC_SCAN_CHUNK:\n",
    " * this step walks one segment, records the position in the region cursor, and the next full step continues with another segment.\n",
    " *\n",
    " * Only **conservative scans** are segmented: a descriptor scan's length is the number of pointer fields in the struct (a compile-time constant, on the order of a few to a few thousand),\n",
    " * and the segmentation gain does not pay for one more comparison per object; large arrays / unknown shapes use the conservative scan (word-wise over the whole slot), which is the path where the pause\n",
    " * grows linearly with object length.\n",
    " *\n",
    " * Granularity is 65536 pointers: this scan is bandwidth-bound, about 1.1 ns per pointer here, so the single-step bound is about 72 us, 15 times lower than the 1126 us\n",
    " * for a 1M-pointer chase array without segmentation. Smaller segments pay a fixed pop/locate/account cost per segment\n",
    " * (promote: 65536 -> +0.20%, 16384 -> +0.59%, 8192 -> +0.99%, 1024 -> +3.6%); to get a tighter\n",
    " * bound, lower it at compile time and pay according to the table. The criterion is the driver's t_scanChunk (deterministic cursor assertion); the red self-test\n",
    " * raises the bound to a billion so the step scans everything at once and no cursor appears. */\n",
    "#ifndef EXTC_RC_SCAN_CHUNK\n",
    "#define EXTC_RC_SCAN_CHUNK 65536\n",
    "#endif\n",
    "#if EXTC_RC_SCAN_CHUNK < 1\n",
    "#error \"EXTC_RC_SCAN_CHUNK must be >= 1\"\n",
    "#endif\n",
    "#define EXTC_RC_MARK_CHILD(_child) do { \\\n",
    "    void *child = (_child); \\\n",
    "    if (child) { \\\n",
    "        int _dup = 0; \\\n",
    "        uintptr_t _cb = (uintptr_t)child & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1); \\\n",
    "        if (_cb == (uintptr_t)s) {   /* same block: jump by the dedup bit of \"the slot containing this address\" */ \\\n",
    "            size_t _off = extc_rc_offOf(s, child); \\\n",
    "            size_t _ci = extc_rc_slotOfOff(s, _off); \\\n",
    "            if (_ci < s->nslots) { \\\n",
    "                size_t _cw = extc_rc_word(_ci); \\\n",
    "                _dup = (int)((s->mark[_cw] & extc_rc_bit(_ci)) != 0);   /* dedup only looks at the mark bit */ \\\n",
    "            } \\\n",
    "        } \\\n",
    "        if (!_dup) extc_rc_markPushFast(r, child);   /* already black: the pop side is also blocked by the same bit */ \\\n",
    "    } \\\n",
    "} while (0)\n",

    "#define EXTC_RC_MARK_SCAN(_rawIn) do { \\\n",
    "    uintptr_t _raw = (_rawIn); \\\n",
    "        void *o = (void *)(_raw & ~(uintptr_t)1);   /* low bit = \"must scan\" tag set by the barrier */ \\\n",
    "        int _force = (int)(_raw & (uintptr_t)1); \\\n",
    "        ExtcRcSlab *s = (lastS && ((uintptr_t)o & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1)) == (uintptr_t)lastS) \\\n",
    "                          ? lastS : (ExtcRcSlab *)0; \\\n",
    "        size_t i = 0; \\\n",
    "        int _haveK = 0;   /* the same-block check already computed the slot number, so do not compute it again below */ \\\n",
    "        if (s) { \\\n",
    "            size_t _off = extc_rc_offOf(s, o); \\\n",
    "            size_t _k = extc_rc_slotOfOff(s, _off); \\\n",
    "            if (_k < s->nslots && _k * s->ss == _off) { i = _k; _haveK = 1; } \\\n",
    "            else s = (ExtcRcSlab *)0; \\\n",
    "        } \\\n",
    "        if (!s) s = extc_rc_ownSlabMark(o); \\\n",
    "        if (s) lastS = s; \\\n",
    "        if (!s || s->region != r) continue;        /* outside the region / not rc: treat as live and stop */ \\\n",
    "        if (!_haveK) i = extc_rc_slotOf(s, o); \\\n",
    "        uint64_t bit = extc_rc_bit(i); \\\n",
    "        size_t wi = extc_rc_word(i);   /* occ and mark share a word: compute the coordinate once (every object is scanned once) */ \\\n",
    "        if (!_force && (s->mark[wi] & bit)) continue;   /* forced entries are still scanned */ \\\n",
    "        if (!(s->occ[wi] & bit)) continue;   /* a free slot is not an object */ \\\n",
    "        s->mark[wi] |= bit; \\\n",
    "        marked++; \\\n",
    "        r->markedBytes += (int64_t)s->ss; \\\n",
    "        const ExtcRcType *t = extc_rc_typeOf(s, i); \\\n",
    "        if (t == EXTC_RC_CONSERVATIVE) {           /* fallback: treat every word in the slot as a candidate pointer */ \\\n",
    "            size_t words = s->ss / sizeof(void *); \\\n",
    "            if (words > (size_t)EXTC_RC_SCAN_CHUNK) {   /* very long: this step only records the cursor, the next full step continues with a segment */ \\\n",
    "                r->scanObj = o; r->scanOff = 0; _split = 1; \\\n",
    "                continue; \\\n",
    "            } \\\n",
    "            for (size_t w2 = 0; w2 < words; w2++) { \\\n",
    "                void *child = ((void **)o)[w2]; \\\n",
    "        if (child) { \\\n",
    "            uintptr_t _cb = (uintptr_t)child & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1); \\\n",
    "            if (_cb == (uintptr_t)s) {   /* same block: jump by the dedup bit of \"the slot containing this address\" */ \\\n",
    "                size_t _off = extc_rc_offOf(s, child); \\\n",
    "                size_t _ci = extc_rc_slotOfOff(s, _off); \\\n",
    "                if (_ci < s->nslots) { \\\n",
    "                    uint64_t _cbit = extc_rc_bit(_ci); \\\n",
    "                    size_t _cw = extc_rc_word(_ci);   /* dedup only looks at the mark bit */ \\\n",
    "                    if (s->mark[_cw] & _cbit) continue;   /* already black: the pop side is also blocked by the same bit */ \\\n",
    "                } \\\n",
    "            } \\\n",
    "            extc_rc_markPushFast(r, child); \\\n",
    "        } \\\n",
    "            } \\\n",
    "            continue; \\\n",
    "        } \\\n",
    "        if (!t) continue;                          /* no reference fields, so no pointers to walk */ \\\n",
    "        const uint32_t *_op = t->off; const uint32_t *_oend = _op + t->nptr;   /* obligation 4: walk by the object's own descriptor */ \\\n",
    "        for (; _op < _oend; ++_op) { \\\n",
    "            void *child = *(void **)((char *)o + *_op); \\\n",
    "        if (child) { \\\n",
    "            uintptr_t _cb = (uintptr_t)child & ~(uintptr_t)(EXTC_RC_SLAB_SIZE - 1); \\\n",
    "            if (_cb == (uintptr_t)s) {   /* same block: jump by the dedup bit of \"the slot containing this address\" */ \\\n",
    "                size_t _off = extc_rc_offOf(s, child); \\\n",
    "                size_t _ci = extc_rc_slotOfOff(s, _off); \\\n",
    "                if (_ci < s->nslots) { \\\n",
    "                    uint64_t _cbit = extc_rc_bit(_ci); \\\n",
    "                    size_t _cw = extc_rc_word(_ci);   /* dedup only looks at the mark bit */ \\\n",
    "                    if (s->mark[_cw] & _cbit) continue;   /* already black: the pop side is also blocked by the same bit */ \\\n",
    "                } \\\n",
    "            } \\\n",
    "            extc_rc_markPushFast(r, child); \\\n",
    "        } \\\n",
    "        } \\\n",
    "} while (0)\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_markResume(ExtcRcRegion *r) {\n",
    "    /* Continuation: the previous step left a cursor on a large object (scanObj/scanOff). This whole step walks one segment, so single-step work is\n",
    "     * independent of object length; clear the cursor when done, otherwise record the new cursor. The cursor takes **no stack space** (see the region struct comment).\n",
    "     * Only a conservative scan leaves a cursor (descriptor scans are not segmented). */\n",
    "    void *o = r->scanObj;\n",
    "    ExtcRcSlab *s = extc_rc_ownSlabMark(o);\n",
    "    if (!s || s->region != r) { r->scanObj = (void *)0; return; }\n",
    "    size_t words = s->ss / sizeof(void *);\n",
    "    size_t st = (size_t)r->scanOff;\n",
    "    size_t en = st + (size_t)EXTC_RC_SCAN_CHUNK;\n",
    "    if (en > words) en = words;\n",
    "    for (size_t w2 = st; w2 < en; w2++) { EXTC_RC_MARK_CHILD(((void **)o)[w2]); }\n",
    "    if (en < words) { r->scanObj = o; r->scanOff = (uint32_t)en; }\n",
    "    else r->scanObj = (void *)0;\n",
    "}\n",
    "__attribute__((unused)) static size_t extc_rc_markStep(ExtcRcRegion *r, size_t budget) {\n",
    "    long long _mt0 = 0; int _hot = 0;   /* diagnostics: slice timing + whether this step is a **bounded hot-path** step */\n",
    "    if (extc_rc_pauseOn > 0) { _mt0 = extc_rc_pauseNow(); _hot = budget <= EXTC_RC_MARK_BATCH_MAX; }\n",
    "    size_t _b0 = budget;   /* the budget as given (a drain is 0xffffffff, and after `budget--` it cannot be restored) */\n",
    "    size_t marked = 0, pops = 0;   /* `marked` really-marked count; `pops` popped count (including duplicates/early exits) */\n",
    "    size_t pushes = 0, words = 0;   /* work done: how many slots were pushed + how many rsbit words were scanned */\n",
    "    /* Continuation: the previous step left a cursor on a large object (scanObj/scanOff). This whole step walks one segment, so single-step work is\n",
    "     * independent of object length. After walking it (or a segment) budget is zero and neither seeding nor walking runs -- this step's budget\n",
    "     * is that segment. The cursor is not on the stack, so this **does not pop** (the stack top may be a force entry just pushed by the write barrier). */\n",
    "    if (r->scanObj) {\n",
    "        extc_rc_markResume(r);\n",
    "        pops++;\n",
    "        budget = 0;\n",
    "        _b0 = 0;\n",
    "    }\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "    /* Unified total: seed scanning/pushing and walking all deduct from this one counter, so this step's total work <= W (guaranteed by construction). */\n",
    "    size_t wleft = _b0 < (size_t)EXTC_RC_WORK_BUDGET ? _b0 : (size_t)EXTC_RC_WORK_BUDGET;\n",
    "#define EXTC_RC_MS_SEED (r->seedSlab && wleft > 0)\n",
    "#define EXTC_RC_MS_WALK (r->msp && wleft > 0)\n",
    "#else\n",
    "#define EXTC_RC_MS_SEED (r->seedSlab)\n",
    "#define EXTC_RC_MS_WALK (r->msp)\n",
    "#endif\n",
    "    ExtcRcSlab *lastS = (ExtcRcSlab *)0;   /* local same-slab cache */\n",
    "    int _split = 0;   /* this step saw a large-object segment, so end the step now (see the end of the MARK_SCAN section) */\n",
    "    if (!r->seedsDone) {   /* stepped seed push: each step pushes at most SEED_PUSHES slots and scans at most SEED_WORDS words */\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "        /* Unified budget: the bits of the current word **not yet pushed** stay in `seedBits`, and the cursor **stops on this word**\n",
    "         * (`seedSlab`/`seedWord` unchanged), so pushing can recompute the slot address and a word is never dropped halfway\n",
    "         * (dropping bits = incomplete seeds = unsafe), and completeness is not bought with a `+63` overshoot either, so the step total is exactly <= W. */\n",
    "        while (pushes < EXTC_RC_SEED_PUSHES && words < EXTC_RC_SEED_WORDS && EXTC_RC_MS_SEED) {\n",
    "            ExtcRcSlab *ss = r->seedSlab;\n",
    "            if (!r->seedBits) {   /* entering this word: scanning counts as 1 unit, then take a bit */\n",
    "                r->seedBits = ss->rsbit[r->seedWord] & ss->occ[r->seedWord];\n",
    "                words++;\n",
    "                wleft--;\n",
    "            }\n",
    "            while (r->seedBits && wleft > 0 && pushes < EXTC_RC_SEED_PUSHES) {\n",
    "                uint32_t b = (uint32_t)__builtin_ctzll(r->seedBits);\n",
    "                r->seedBits &= r->seedBits - 1;\n",
    "                extc_rc_markPush(r, EXTC_RC_SLAB_DATA(ss) + ((size_t)r->seedWord * 64 + b) * ss->ss);\n",
    "                pushes++;\n",
    "                wleft--;\n",
    "            }\n",
    "            if (r->seedBits) break;   /* total/slot quota used up with bits left, so stop on this word and continue pushing next step */\n",
    "            r->seedWord++;            /* advance the cursor only after this word is fully pushed */\n",
    "            if (r->seedWord >= ss->nwords) { r->seedSlab = ss->next; r->seedWord = 0; }\n",
    "        }\n",
    "#else\n",
    "        while (pushes < EXTC_RC_SEED_PUSHES && words < EXTC_RC_SEED_WORDS && EXTC_RC_MS_SEED) {\n",
    "            ExtcRcSlab *ss = r->seedSlab;\n",
    "            uint64_t sb = ss->rsbit[r->seedWord] & ss->occ[r->seedWord];\n",
    "            while (sb) {\n",
    "                uint32_t b = (uint32_t)__builtin_ctzll(sb);\n",
    "                sb &= sb - 1;\n",
    "                extc_rc_markPush(r, EXTC_RC_SLAB_DATA(ss) + ((size_t)r->seedWord * 64 + b) * ss->ss);\n",
    "                pushes++;\n",
    "            }\n",
    "            r->seedWord++;\n",
    "            if (r->seedWord >= ss->nwords) { r->seedSlab = ss->next; r->seedWord = 0; }\n",
    "            words++;\n",
    "        }\n",
    "#endif\n",
    "        if (!r->seedSlab) r->seedsDone = 1;\n",
    "    }\n",
    "    /* Pop at most EXTC_RC_MARK_BATCH_POP objects first, prefetch them together, then scan one by one.\n",
    "     * Why: popping one at a time LIFO is a **serial pointer chain** -- the next object depends on the previous step's payload read,\n",
    "     * so a whole cache-miss latency lands on one object; collecting a batch first lets this batch's payload misses\n",
    "     * overlap in flight, so latency is amortized. The **pop order is unchanged** (first popped is scanned first); only the scan is deferred until the batch is popped. */\n",
    "    while (EXTC_RC_MS_WALK && budget > 0 && !_split) {\n",
    /* Shallow stack: no batching, and the shallow stack is drained in one pass. The fixed cost
     * of batching (array, four-way min, fill, batch scan) is pure loss at stack depth about 1;
     * batching exists to give payload misses prefetch lead time, which only pays off once enough
     * objects accumulate. Draining in the loop also avoids re-evaluating the while and
     * shallow-stack conditions in the outer loop after every pop. */
    "        if ((size_t)r->msp <= (size_t)EXTC_RC_MARK_SHALLOW && budget > 0\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "            && wleft > 0\n",
    "#endif\n",
    "           ) {\n",
    "            do {\n",
    "                void *_one = r->mstk[--r->msp];\n",
    "                budget--; pops++;\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "                wleft--;\n",
    "#endif\n",
    "                EXTC_RC_MARK_SCAN((uintptr_t)_one);\n",
    "            } while (r->msp > 0 && (size_t)r->msp <= (size_t)EXTC_RC_MARK_SHALLOW && budget > 0 && !_split\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "                     && wleft > 0\n",
    "#endif\n",
    "                    );\n",
    "            continue;\n",
    "        }\n",
    "        uintptr_t _batch[EXTC_RC_MARK_BATCH_POP]; size_t _nb = 0;\n",
    "        /* Compute this batch's limit once, then pop: a batch averages fewer than 2 objects, and re-testing\n",
    "         * four conditions and decrementing budget and quota per pop does not amortize the fixed cost; the limit is the min of four quantities,\n",
    "         * computed once. Budget/quota are deducted once by _nb after the whole batch is popped. */\n",
    "        size_t _lim = EXTC_RC_MARK_BATCH_POP;\n",
    "        if (budget < _lim) _lim = budget;\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "        if (wleft < _lim) _lim = wleft;\n",
    "#endif\n",
    "        void **_stk = r->mstk; size_t _sp = r->msp;   /* hoist the stack head into a local: the pop loop does not keep re-reading r */\n",
    "        if (_sp < _lim) _lim = _sp;\n",
    "        while (_nb < _lim) {\n",
    "            _batch[_nb] = (uintptr_t)_stk[--_sp];\n",
    "            __builtin_prefetch((void *)(_batch[_nb] & ~(uintptr_t)1), 0, 1);   /* prefetch while collecting: saves one loop pass */\n",
    "            _nb++;\n",
    "        }\n",
    "        r->msp = _sp;   /* put it back: scanning this batch pushes children and changes r->msp */\n",
    "        budget -= _nb; pops += _nb;\n",
    "#if EXTC_RC_WORK_BUDGET > 0\n",
    "        wleft -= _nb;   /* 1 popped object = 1 unit (the children it pushes count inside this one object) */\n",
    "#endif\n",
    "        size_t _b = 0;\n",
    "        for (; _b < _nb && !_split; _b++) { EXTC_RC_MARK_SCAN(_batch[_b]); }\n",
    "        if (_split) {   /* segmentation cut the step short: stack entries in this batch **not yet scanned** must be pushed back (they were already popped from the mark stack;\n",
    "                         * dropping them would miss reachable objects). The cursor entry is not on the stack, so there is no\n",
    "                         * \"continuation entry buried\" problem -- just push back and the next step's entry continues from the cursor. */\n",
    "            while (_nb > _b) {\n",
    "                --_nb;\n",
    "                uintptr_t _raw = _batch[_nb];\n",
    "                if (_raw & (uintptr_t)1) extc_rc_markPushForce(r, (void *)(_raw & ~(uintptr_t)1));\n",
    "                else extc_rc_markPush(r, (void *)(_raw & ~(uintptr_t)1));\n",
    "            }\n",
    "        }\n",
    "    }\n",
    "    if (extc_rc_pauseOn > 0) {\n",
    "        long long _d = extc_rc_pauseNow() - _mt0;\n",
    "        extc_rc_stepNote(_d);\n",
    "        /* `EXTC_RC_SLOWSTEP=<us>`: print **every** slow step above the threshold with its components, so a long tail can be told apart in one run\n",
    "         * as \"outside interference\" (components at the cap, time 10-800x) or \"a genuinely heavy object/allocation\" (components large too).\n",
    "         * Off by default. */\n",
    "        if (extc_rc_slowUs > 0 && _d > extc_rc_slowUs)\n",
    "            fprintf(stderr, \"[slow] step_n=%lld kind=mark why=%s dur_us=%.1f pops=%lld marked=%lld words=%lld pushes=%lld mscap=%lld msp=%lld budget=%lld\\n\",\n",
    "                    extc_rc_stepN, extc_rc_why, _d / 1000.0, (long long)pops, (long long)marked, (long long)words,\n",
    "                    (long long)pushes, (long long)r->mscap, (long long)r->msp, (long long)_b0);\n",
    "        if (_d > extc_rc_worstNs) {   /* worst step: keep every field (kind/why/budget/walk/scan/push) */\n",
    "            extc_rc_worstNs = _d; extc_rc_worstKind = \"mark\"; extc_rc_worstWhy = extc_rc_why;\n",
    "            extc_rc_worstBudget = (long long)_b0; extc_rc_worstPops = (long long)pops;\n",
    "            extc_rc_worstMarked = (long long)marked; extc_rc_worstWords = (long long)words;\n",
    "            extc_rc_worstPushes = (long long)pushes;\n",
    "            extc_rc_worstSwWords = -1; extc_rc_worstSwFreed = -1;\n",
    "        }\n",
    "        if (!_hot) {   /* unbounded step: listed separately, it does not enter the bounded `[work]` bounds */\n",
    "            extc_rc_wUbN++;\n",
    "            if (strcmp(extc_rc_why, \"settle\") == 0) extc_rc_ubSettleN++;\n",
    "            else if (strcmp(extc_rc_why, \"collect\") == 0) extc_rc_ubCollectN++;\n",
    "            else if (strcmp(extc_rc_why, \"release\") == 0) extc_rc_ubReleaseN++;\n",
    "            else extc_rc_ubOtherN++;\n",
    "            /* `EXTC_RC_TRACE_UB=1`: print every unbounded drain together with **the step number at the time**, so \"once per round inside a hot loop\"\n",
    "             * and \"once at process exit\" can be told apart directly by step number (not by reasoning). */\n",
    "            if (getenv(\"EXTC_RC_TRACE_UB\"))\n",
    "                fprintf(stderr, \"[ubtrace] step_n=%lld kind=mark why=%s walk=%lld scan=%lld push=%lld budget=%lld\\n\",\n",
    "                        extc_rc_stepN, extc_rc_why, (long long)marked, (long long)words,\n",
    "                        (long long)pushes, (long long)_b0);\n",
    "            if ((long long)marked > extc_rc_wUbWalkMax) extc_rc_wUbWalkMax = (long long)marked;\n",
    "            if ((long long)words > extc_rc_wUbScanMax) extc_rc_wUbScanMax = (long long)words;\n",
    "            if ((long long)pushes > extc_rc_wUbPushMax) extc_rc_wUbPushMax = (long long)pushes;\n",
    "        }\n",
    "    }\n",
    "    if (_hot) extc_rc_workNote(marked, words, pushes);\n",
    "    if (extc_rc_pauseOn > 0) {   /* mark stack high-water mark: `mscap` only grows, so a sample is the peak */\n",
    "        if ((long long)r->mscap > extc_rc_mscapMax) extc_rc_mscapMax = (long long)r->mscap;\n",
    "        if ((long long)r->msp > extc_rc_mspMax) extc_rc_mspMax = (long long)r->msp;\n",
    "    }\n",
    "    return marked;\n",
    "}\n",
    "/** @brief Single-pass full marking (callers such as `releaseOld` keep their existing semantics). */\n",
    "__attribute__((unused)) static size_t extc_rc_mark(ExtcRcRegion *r, void *const *roots, size_t nroots) {\n",
    "    extc_rc_markBegin(r, roots, nroots);\n",
    "    size_t marked = 0;\n",
    "    while (!r->seedsDone || r->msp || r->scanObj) marked += extc_rc_markStep(r, 0xffffffffu);\n",
    "    return marked;\n",
    "}\n",
    "\n",
    "/* ---- Targeted release at overwrite: \"overwriting this slot\" itself proves the old value's tree dead [rt:release] ----------------\n",
    " *\n",
    " * The caller (`extc_rc_storeRefOwnedRelease`) has already checked: the old value is in a region **owned by this frame** and\n",
    " * that region is sweepable (no `noSweep` / no debt). What happens here is a **narrowed sweep**:\n",
    " *\n",
    " *   1. first mark from the **other roots** (the root table with the overwritten cell removed) + this region's cross-region seeds -- the same\n",
    " *      seed set as `extc_rc_collect`, so \"live\" is decided identically, word for word;\n",
    " *   2. then walk from the old value along the **type descriptors**, releasing only slots that are reachable and unmarked. Stop at a marked\n",
    " *      object: another root/seed points to it, so it is live, and everything below it was already marked in step 1.\n",
    " *\n",
    " * Safety argument (the whole basis of this mechanism): the released set is a **subset** of what `collect` would release at the **same point with the same seed set** --\n",
    " * so even if the static criterion \"no other live holder right now\" is wrong, an object pointed to by another live root/seed\n",
    " * is not freed (the lightweight form of a trial deletion). The criterion only decides \"is this pass worth it\".\n",
    " *\n",
    " * Direction: releasing less (a wrong criterion means something that should be freed is not) is conservative; releasing more can only come from **incomplete roots/seeds**,\n",
    " * and that is exactly the precondition of `collect`, guarded by the caller with `noSweep`/`owe`/frame ownership.\n",
    " *\n",
    " * Mark bits must be cleared before returning: `extc_rc_sweep` is the only place that clears them, so neither sweeping nor clearing here would leave\n",
    " * marks for the next `collect` (those slots would be taken as live, so objects are not reclaimed). */\n",
    "__attribute__((unused)) static size_t extc_rc_releaseOld(ExtcRcRegion *r, void *old,\n",
    "                                                         void *const *roots, size_t nroots) {\n",
    "    if (!r || !old) return 0;   /* skip:no-pointer */\n",
    "    extc_rc_why = \"release\";\n",
    "    extc_rc_mark(r, roots, nroots);\n",
    "    r->scanObj = (void *)0;   /* mark above has drained; defensive: the cursor does not carry across this release */\n",
    "    r->msp = 0;\n",
    "    extc_rc_markPush(r, old);\n",
    "    size_t freed = 0;\n",
    "    while (r->msp) {\n",
    "        void *o = r->mstk[--r->msp];\n",
    "        ExtcRcSlab *s = extc_rc_ownSlab(o);\n",
    "        if (!s || s->region != r) continue;   /* outside the region / not rc: treat as live and stop */\n",
    "        size_t i = extc_rc_slotOf(s, o);\n",
    "        uint64_t bit = extc_rc_bit(i);\n",
    "        if (!(s->occ[extc_rc_word(i)] & bit)) continue;   /* a free slot is not an object */\n",
    "        if (s->mark[extc_rc_word(i)] & bit) continue;   /* reachable from another root/seed, so live: stop */\n",
    "        const ExtcRcType *t = extc_rc_typeOf(s, i);\n",
    "        /* Push the children before releasing this cell: descriptor and fields are still intact (`freeSlot` overwrites the payload head). */\n",
    "        if (t == EXTC_RC_CONSERVATIVE) {\n",
    "            size_t words = s->ss / sizeof(void *);\n",
    "            for (size_t w = 0; w < words; w++) {\n",
    "                void *c = ((void **)o)[w];\n",
    "                if (c) extc_rc_markPush(r, c);\n",
    "            }\n",
    "        } else if (t) {   /* no reference fields, so there are no children to walk */\n",
    "            for (uint32_t k = 0; k < t->nptr; k++) {\n",
    "                void *c = *(void **)((char *)o + t->off[k]);\n",
    "                if (c) extc_rc_markPush(r, c);\n",
    "            }\n",
    "        }\n",
    "        extc_rc_freeSlot(s, i);\n",
    "        freed++;\n",
    "    }\n",
    "    extc_rc_shadeNextGen();   /* the narrowed sweep clears the whole mark span below: black records are void */\n",
    "    for (ExtcRcSlab *s = r->slabs; s; s = s->next)\n",
    "        memset(s->mark, 0, (size_t)s->nwords * sizeof(uint64_t));\n",
    "    extc_rc_relN++;\n",
    "    extc_rc_relSlots += (int64_t)freed;\n",
    "    return freed;\n",
    "}\n",
    "\n",
    "/* Reference-slot overwrite with one **targeted release**: when the old value's whole tree is proven dead at the overwrite point, there is no need to wait for the region sweep.\n",
    " *\n",
    " * The `home` given by the caller (codegen) is **the region the new object being stored into this slot lives in**, and it is guaranteed to be the one this frame\n",
    " * owns (`rcFrameOwnsArena`). If the old value is not in `home` the whole section is skipped -- then there is no static basis for \"this frame's root table is complete for that\n",
    " * \"region\", so better not to release (conservative direction).\n",
    " *\n",
    " * All three guards are required:\n",
    " *   - `noSweep`: this region has in-edges whose host cannot be traced, so seeds are incomplete and the region may not be swept at all;\n",
    " *   - `owe`: an inner frame has allocated into this region, so its root table may not be complete at this moment (same reason as `checkOwed`);\n",
    " *   - `sold->region != home`: the old value is not in the statically given region (for instance it was just moved by another path).\n",
    " *\n",
    " * After releasing, the ordinary `storeRefOwned` runs: the old value slot it reads is already free, and `rsDecSlab`/`holdUpdSlab`\n",
    " * both return at the occupied-bit line, so nothing is settled twice, and writing the new value plus its increment happens as usual. */\n",
    "__attribute__((unused)) static void extc_rc_releaseDead(ExtcRcRegion *home, void *old,\n",
    "                                                        void *const *roots, size_t nroots) {\n",
    "    if (!home || !old) return;   /* skip:no-pointer */\n",
    "    if (home->noSweep || home->owe) return;   /* skip:nosweep */\n",
    "    ExtcRcSlab *s = extc_rc_ownSlab(old);\n",
    "    /* the old value is not in the statically given region (for instance it was just moved by another path), so do not release (conservative). */\n",
    "    if (s && s->region == home) {\n",
    "        if (!extc_rc_budgetOk(home)) return;   /* skip:release-budget */\n",
    "        extc_rc_releaseOld(home, old, roots, nroots);\n",
    "        home->visitedBytes = home->allocBytes;   /* account for the traversal */\n",
    "    }\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static void extc_rc_storeRefOwnedRelease(void **slot, void *v, void *owner,\n",
    "                                                                 ExtcRcRegion *home,\n",
    "                                                                 void *const *roots, size_t nroots) {\n",
    "    extc_rc_shade(v);\n",
    "    if (slot) extc_rc_releaseDead(home, *slot, roots, nroots);\n",
    "    extc_rc_storeRefOwned(slot, v, owner);\n",
    "}\n",
    "\n",

    "/* Sweep: dead slot = occupied & ~marked. Walk 64-bit words in order, chase no pointers, free nothing individually; clear the mark bitmap sequentially over the whole span.\n",
    " * Releasing does not go back and fix other objects' counts: a released object is unreachable this round, references to it are released too, and other counts can only be too high\n",
    " * so better reclaimed late than freed early. */\n",
    "/* ---- Stepped (interruptible) sweep: one word (64 slots) per step, cursor kept in the region [rt:sweep] ----\n",
    " *\n",
    " * Sweeping a whole region in one go makes the pause proportional to the region's contents. Here it is cut into \"N words per step\":\n",
    " *   - `sweepBegin` sets the cursor and bumps the round number; `sweepWord` sweeps one word (releases unmarked objects,\n",
    " *     clears that word's mark bits, and stamps a slab with this round's number once it is fully swept);\n",
    " *   - `sweepStep(budget)` sweeps at most budget words; only on reaching the end does it settle the accounts (self-tuning multiplier, `live`,\n",
    " *     threshold, `sweeps++`);\n",
    " *   - objects **allocated during sweep are marked black at the allocation point**, only at positions the cursor has not reached (see `extc_rc_alloc`);\n",
    " *   - while a sweep is unfinished, trigger points only continue it and never start a new mark (marking relies on \"the mark bitmap is clear\");\n",
    " *   - obligation 7 (`noSweep`) regions are **abandoned**: the round in flight is voided on the spot and not one byte is swept afterwards;\n",
    " *   - account queries (`extc_rc_bytes` etc.) and the debt-settling points first \"settle\": they push the round in flight to the end,\n",
    " *     so that \"the accounts of one collection\" are final when observed.\n",
    " *\n",
    " * The final accounts do not recompute occupied payload: `bytes` is maintained incrementally by `extc_rc_alloc` (+ss) and `extc_rc_freeSlot`\n",
    " * (-ss), so recomputing is pure waste. */\n",
    "/** @brief Start a stepped sweep round: the cursor points at the first slab and the round number is bumped. */\n",
    "__attribute__((unused)) static void extc_rc_sweepBegin(ExtcRcRegion *r) {\n",
    "    extc_rc_shadeNextGen();   /* the sweep clears mark bits slab by slab: the shading cache is void */\n",
    "    r->sweeping = 1;\n",
    "    r->swId++;\n",
    "    r->swSlab = r->slabs;\n",
    "    r->swWord = 0;\n",
    "    r->swFreed = 0;\n",
    "}\n",
    "/** @brief Sweep **one word** at the cursor; returns 1 when the whole region has been swept. */\n",
    "__attribute__((unused)) static int extc_rc_sweepWord(ExtcRcRegion *r) {\n",
    "    ExtcRcSlab *s = r->swSlab;\n",
    "    uint32_t w = r->swWord;\n",
    "    uint64_t dead = s->occ[w] & ~s->mark[w];\n",
    "    if (dead) {   /* word-wise bulk release (see extc_rc_freeSlotWord): per slot only the head insertion, the rest once per word */\n",
    "        r->swFreed += (int64_t)extc_rc_freeSlotWord(s, (size_t)w, dead);\n",
    "    }\n",
    "    s->mark[w] = 0;\n",
    "    if (++r->swWord >= s->nwords) { s->swEpoch = r->swId; r->swSlab = s->next; r->swWord = 0; }\n",
    "    return r->swSlab == NULL;\n",
    "}\n",
    "/* Per-step pause (printed when `EXTC_RC_PAUSE=1`), to gauge the effect of the step granularity;\n",
    " * the counters and threshold buckets are declared before `markStep` (they are recorded there too). */\n",
    "/** @brief Stepped sweep: sweep at most budget words; on reaching the end settle the accounts and return 1, otherwise 0. */\n",
    "__attribute__((unused)) static int extc_rc_sweepStep(ExtcRcRegion *r, uint32_t budget) {\n",
    "    if (!r->sweeping) return 0;   /* skip:not-sweeping */\n",
    "    long long _t0 = extc_rc_pauseOn > 0 ? extc_rc_pauseNow() : 0;   /* do not pay for the clock call when the switch is off */\n",
    "    uint32_t _b0 = budget, _left = budget;\n",
    "    long long _f0 = (long long)r->swFreed;\n",
    "    while (_left > 0 && r->swSlab) { _left--; if (extc_rc_sweepWord(r)) break; }\n",
    "    if (extc_rc_pauseOn > 0) {   /* sweep components: how many words this step swept, how many slots it released */\n",
    "        long long _d = extc_rc_pauseNow() - _t0;\n",
    "        long long _sw = (long long)_b0 - (long long)_left, _fr = (long long)r->swFreed - _f0;\n",
    "        extc_rc_stepNote(_d);\n",
    "        if (extc_rc_slowUs > 0 && _d > extc_rc_slowUs)\n",
    "            fprintf(stderr, \"[slow] kind=sweep why=%s dur_us=%.1f sw_words=%lld freed=%lld budget=%lld\\n\",\n",
    "                    extc_rc_why, _d / 1000.0, _sw, _fr, (long long)_b0);\n",
    "        if (_d > extc_rc_worstNs) {\n",
    "            extc_rc_worstNs = _d; extc_rc_worstKind = \"sweep\"; extc_rc_worstWhy = extc_rc_why;\n",
    "            extc_rc_worstBudget = (long long)_b0; extc_rc_worstPops = -1; extc_rc_worstMarked = -1;\n",
    "            extc_rc_worstWords = -1; extc_rc_worstPushes = -1;\n",
    "            extc_rc_worstSwWords = _sw; extc_rc_worstSwFreed = _fr;\n",
    "        }\n",
    "        if (_b0 > EXTC_RC_MARK_BATCH_MAX) {   /* whole-round drain (the sweep tail of settle/finish) is listed separately */\n",
    "            extc_rc_wUbSwN++;\n",
    "            if (_sw > extc_rc_wUbSwWordsMax) extc_rc_wUbSwWordsMax = _sw;\n",
    "            if (_fr > extc_rc_wUbSwFreedMax) extc_rc_wUbSwFreedMax = _fr;\n",
    "            if (getenv(\"EXTC_RC_TRACE_UB\"))\n",
    "                fprintf(stderr, \"[ubtrace] step_n=%lld kind=sweep why=%s words=%lld freed=%lld budget=%u\\n\",\n",
    "                        extc_rc_stepN, extc_rc_why, _sw, _fr, _b0);\n",
    "        }\n",
    "    }\n",
    "    if (r->swSlab) return 0;   /* skip:sweep-continue */\n",
    "    r->sweeping = 0;\n",
    "    if (r->swFreed == 0) {\n",
    "        r->scale = (r->scale > 0 ? r->scale : 1) * EXTC_RC_SCALE_MUL;\n",
    "        if (r->scale > EXTC_RC_SCALE_MAX) r->scale = EXTC_RC_SCALE_MAX;\n",
    "    } else {\n",
    "        r->scale = 0;\n",
    "    }\n",
    "    /* live was fixed when marking completed; sweep completion only closes the round */\n",
    "    extc_rc_thrUpd(r);\n",
    "    r->sweeps++;\n",
    "    return 1;\n",
    "}\n",
    "/** @brief Push the round of stepped sweep in flight to the end: used by account queries and settling points (not on the hot path).\n",
    " *  A region under obligation 7 is voided on the spot (abandoned) and not one byte is swept further. */\n",
    "__attribute__((unused)) static void extc_rc_settle(ExtcRcRegion *r) {\n",
    "    if (!r) return;   /* skip:no-region */\n",
    "    extc_rc_why = \"settle\";\n",
    "    if (r->marking && !r->noSweep) {   /* a round in flight must be closed too: query and destroy sites are the last backstop */\n",
    "        while (!r->seedsDone || r->msp || r->scanObj) extc_rc_markStep(r, 0xffffffffu);\n",
    "        extc_rc_finish(r);\n",
    "    }\n",
    "    if (!r->sweeping) return;   /* skip:not-sweeping */\n",
    "    if (r->noSweep) { r->sweeping = 0; return; }   /* skip:nosweep-abandon */\n",
    "    while (!extc_rc_sweepStep(r, 0xffffffffu)) { }\n",
    "}\n",
    "/** @brief Sweep everything in one pass (budget is infinite): a reference entry equivalent to the stepped sweep. */\n",
    "__attribute__((unused)) static size_t extc_rc_sweep(ExtcRcRegion *r) {\n",
    "    extc_rc_sweepBegin(r);\n",
    "    extc_rc_settle(r);\n",
    "    return r->swFreed;\n",
    "}\n",
    "\n",
    "/* Trigger: memory pressure, with a self-tuning retreat. Counting already reclaims everything that is not a cycle, so occupancy ~= live, hence\n",
    " * \"occupancy > max(2 x live after the last sweep, floor) x multiplier\" holds only when cycles really pile up.\n",
    " * A sweep that finds nothing multiplies the multiplier by EXTC_RC_SCALE_MUL (learning \"no cycles here\"); a real find resets it. */\n",
    "/* The threshold only moves when live / floor / scale change (see the three call sites of `thrUpd`), so cache it;\n",
    " * every allocation then does one `bytes > thr` comparison. The overflow case is expressed as `thr = 0` (= sweep as soon as anything was allocated). */\n",
    "__attribute__((unused)) static void extc_rc_thrUpd(ExtcRcRegion *r) {\n",
    "    int64_t scale = r->scale > 0 ? r->scale : 1;\n",
    "    int64_t thr = r->live * 2;\n",
    "    if (thr < r->floor) thr = r->floor;\n",
    "    if (scale > 1 && thr > INT64_MAX / scale) { r->thr = 0; return; }\n",
    "    r->thr = thr * scale;\n",
    "}\n",
    "/* Round credit: separate from the targeted-release credit -- release spends visitedBytes every time, so sharing one counter would starve round start. */\n",
    "/* Both are asked once per op (targeted-release points in generated code), so `inline` lets the call site flatten them\n",
    " * and saves a call/return; no `always_inline`, the compiler decides stack depth per call site. */\n",
    "__attribute__((unused)) static inline int extc_rc_roundOk(const ExtcRcRegion *r) {\n",
    "    int64_t need = r->live > r->floor ? r->live : r->floor;\n",
    "    return r->allocBytes - r->roundVisitedBytes >= need;\n",
    "}\n",
    "__attribute__((unused)) static inline int extc_rc_shouldSweep(const ExtcRcRegion *r) {\n",
    "    if (r->noSweep) return 0;   /* an in-edge whose host cannot be traced: this region is reclaimed by counting only */   /* skip:nosweep */\n",
    "#if EXTC_RC_SWEEP_FREE\n",
    "    /* The whole program is proven **acyclic**: every unreachable object is eventually released on the spot when its count hits zero, so a sweep has nothing to do, so\n",
    "     * do not sweep. Erring this way means \"should have swept but did not\", so memory grows (not a dangling pointer). */\n",
    "    return 0;   /* skip:sweepfree */\n",
    "#else\n",
    "    /* Triggering looks only at pressure: credit is not a trigger, it only decides whether targeted release should do one O(live set) walk */\n",
    "    return r->bytes > r->thr && extc_rc_roundOk(r);   /* round credit: a separate counter, targeted release does not spend it */\n",
    "#endif\n",
    "}\n",
    "\n",
    "#include <time.h>\n",
    "/* EXTC_RC_PAUSE=1: accumulate the duration of every **real sweep** (coarse: take the clock before and after), printed at process exit.\n",
    " * The accounting matches the prototype-reclaim/sim.c pauses (max + total + count). If the platform exposes a monotonic clock use\n",
    " * it, otherwise fall back to ISO C `clock()` (CPU time, which underestimates time blocked on page faults/IO). Off by default. */\n",
    "static long long extc_rc_pauseMax, extc_rc_pauseTotal, extc_rc_pauseN;\n",
    "static int extc_rc_pauseOn = -1;\n",
    "static long long extc_rc_pauseNow(void) {\n",
    "#if defined(CLOCK_MONOTONIC)\n",
    "    struct timespec t;\n",
    "    t.tv_sec = 0; t.tv_nsec = 0;\n",
    "    (void)clock_gettime(CLOCK_MONOTONIC, &t);   /* on failure leave 0: the reading is 0 rather than skipped */\n",
    "    return (long long)t.tv_sec * 1000000000LL + t.tv_nsec;\n",
    "#else\n",
    "    return (long long)clock() * 1000000000LL / (CLOCKS_PER_SEC ? CLOCKS_PER_SEC : 1);\n",
    "#endif\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_pauseDump(void) {\n",
    "    fprintf(stderr, \"[pause] collects=%lld max_us=%.1f total_us=%.1f\\n\",\n",
    "            extc_rc_pauseN, extc_rc_pauseMax / 1000.0, extc_rc_pauseTotal / 1000.0);\n",
    "    fprintf(stderr, \"[step] n=%lld max_us=%.1f total_us=%.1f over16=%lld over64=%lld over256=%lld over1ms=%lld\\n\",\n",
    "            extc_rc_stepN, extc_rc_stepMax / 1000.0, extc_rc_stepTotal / 1000.0,\n",
    "            extc_rc_stepB64us + extc_rc_stepB256us + extc_rc_stepB1ms + extc_rc_stepBge1ms,\n",
    "            extc_rc_stepB256us + extc_rc_stepB1ms + extc_rc_stepBge1ms,\n",
    "            extc_rc_stepB1ms + extc_rc_stepBge1ms,\n",
    "            extc_rc_stepBge1ms);\n",
    "    /* Per-step **work** (deterministic) -- next to `[step]` wall clock: wall clock is affected by preemption, work is not. */\n",
    "    fprintf(stderr, \"[work] n=%lld walk_max=%lld scan_max=%lld push_max=%lld walk_gt16=%lld walk_gt64=%lld walk_gt256=%lld scan_gt16=%lld scan_gt64=%lld scan_gt256=%lld push_gt16=%lld push_gt64=%lld push_gt256=%lld\\n\",\n",
    "            extc_rc_wN, extc_rc_wWalkMax, extc_rc_wScanMax, extc_rc_wPushMax,\n",
    "            extc_rc_wWalkO16, extc_rc_wWalkO64, extc_rc_wWalkO256,\n",
    "            extc_rc_wScanO16, extc_rc_wScanO64, extc_rc_wScanO256,\n",
    "            extc_rc_wPushO16, extc_rc_wPushO64, extc_rc_wPushO256);\n",
    "    /* Measurement for the unified budget: `tot_max` = the largest single-step walk+scan+push (should be <= W);\n",
    "     * `assist_max` = the share taken by `wbDebt` assistance in that step (also counted in the same total). */\n",
    "    fprintf(stderr, \"[wbudget] W=%d tot_max=%lld assist_max=%lld mscap_max=%lld msp_max=%lld\\n\",\n",
    "            EXTC_RC_WORK_BUDGET, extc_rc_wTotMax, extc_rc_wAssistMax,\n",
    "            extc_rc_mscapMax, extc_rc_mspMax);\n",
    "    /* Components of the **worst step**: for kind=mark look at pops/marked/words/pushes; for kind=sweep look at\n",
    "     * sweep_words/freed. `why` is the entry label, so it is obvious who ran an unbounded drain. */\n",
    "    fprintf(stderr, \"[worst] kind=%s why=%s budget=%lld dur_us=%.1f pops=%lld marked=%lld words=%lld pushes=%lld sweep_words=%lld freed=%lld\\n\",\n",
    "            extc_rc_worstKind, extc_rc_worstWhy, extc_rc_worstBudget, extc_rc_worstNs / 1000.0,\n",
    "            extc_rc_worstPops, extc_rc_worstMarked, extc_rc_worstWords, extc_rc_worstPushes,\n",
    "            extc_rc_worstSwWords, extc_rc_worstSwFreed);\n",
    "    /* **Unbounded steps** (those not bounded by BATCH_MAX) get their work listed separately -- the `[work]` line above only covers bounded steps,\n",
    "     * where an unbounded drain is invisible (this is exactly the blind spot the Lead caught). */\n",
    "    fprintf(stderr, \"[ubwork] mark_n=%lld walk_max=%lld scan_max=%lld push_max=%lld sweep_n=%lld sw_words_max=%lld sw_freed_max=%lld settle_n=%lld collect_n=%lld release_n=%lld other_n=%lld\\n\",\n",
    "            extc_rc_wUbN, extc_rc_wUbWalkMax, extc_rc_wUbScanMax, extc_rc_wUbPushMax,\n",
    "            extc_rc_wUbSwN, extc_rc_wUbSwWordsMax, extc_rc_wUbSwFreedMax,\n",
    "            extc_rc_ubSettleN, extc_rc_ubCollectN, extc_rc_ubReleaseN, extc_rc_ubOtherN);\n",
    "    /* R4 barrier participant count (**for information**, not a criterion): 0 = every dropped region did a -1;\n",
    "     * >0 = some region was not dropped by `regionDrop` (legal: digraph has no drop point and memory is returned at process exit).\n",
    "     * The real criterion is the **pairing self-check** in `finish`/`abort`: a missed decrement triggers `extc_rc_oops` (rc!=0 + `trap:`). */\n",
    "    fprintf(stderr, \"[guard] r4_wb_open=%d\\n\", (int)extc_rc_wb);\n",
    "}\n",
    "__attribute__((unused)) static void extc_rc_pauseArm(void) {\n",
    "    if (extc_rc_pauseOn < 0) {\n",
    "        extc_rc_pauseOn = getenv(\"EXTC_RC_PAUSE\") != 0;\n",
    "        {   /* slow-step threshold (us); unset => -1 (off) */\n",
    "            const char *_ss = getenv(\"EXTC_RC_SLOWSTEP\");\n",
    "            extc_rc_slowUs = (_ss && *_ss) ? (long long)(atof(_ss) * 1000.0) : -1;\n",
    "        }\n",
    "        if (extc_rc_pauseOn) atexit(extc_rc_pauseDump);\n",
    "    }\n",
    "}\n",
    "/* Finish: marking is done but the round is still open, so close the barrier now and start a (stepped) sweep.\n",
    " * Only finish, **do not start a new round** -- going through collect would start a new round and immediately fill the space just reclaimed. */\n",
    "__attribute__((unused)) static void extc_rc_finish(ExtcRcRegion *r) {\n",
    "    if (!r->marking || !r->seedsDone || r->msp != 0 || r->scanObj) return;   /* skip:finish-early */\n",
    "    extc_rc_why = \"finish\";\n",
    "    r->marking = 0;\n",
    "    r->live = r->markedBytes > 0 ? r->markedBytes : r->live;\n",
    "    extc_rc_thrUpd(r);\n",
    "    r->markDone = 0;\n",
    "    {   /* R4 pairing self-check: a region marked true contributed +1; the **old value** of the atomic decrement must be >= 1.\n",
    "         * Old value 0 means underflow: this region never contributed +1, or its count lost an update to another thread's plain ++/--. */\n",
    "        int _wb0 = extc_rc_wbAdd(-1);\n",
    "        if (_wb0 < 1) extc_rc_oops(\"R4: barrier participant underflow on finish\");\n",
    "    }\n",
    "    r->visitedBytes = r->allocBytes;\n",
    "    r->roundVisitedBytes = r->allocBytes;\n",
    "    extc_rc_sweepBegin(r);\n",
    "    extc_rc_sweepStep(r, EXTC_RC_SWEEP_BUDGET);\n",
    "}\n",
    "/* Start a round: set \"in flight\", record round credit, push seeds. Shared by step / collect so the two cannot drift apart. */\n",
    "__attribute__((unused)) static void extc_rc_begin(ExtcRcRegion *r, void *const *roots, size_t nroots) {\n",
    "    extc_rc_shadeNextGen();   /* a new mark generation starts: all black records of the previous generation are void */\n",
    "    r->marking = 1;\n",
    "    r->visitedBytes = r->allocBytes;   /* starting a round spends the credit (otherwise credit would never run out when sweeps do not complete) */\n",
    "    r->roundVisitedBytes = r->allocBytes;\n",
    "    r->markedBytes = 0;\n",
    "    r->markTick = EXTC_RC_MARK_EVERY;\n",
    "    r->markStartAlloc = r->allocBytes;\n",
    "    extc_rc_wbAdd(1);   /* R3: participant count (multiple regions, possibly several threads marking at once) */\n",
    "    extc_rc_markBegin(r, roots, nroots);\n",
    "}\n",
    "/* Hot-path entry: **advance one step only**; finish on the spot once this round is done. The us window relies on this. */\n",
    "__attribute__((unused)) static size_t extc_rc_step(ExtcRcRegion *r, void *const *roots, size_t nroots) {\n",
    "    extc_rc_why = \"step\";\n",
    "    if (!r->marking) extc_rc_begin(r, roots, nroots);\n",
    "    extc_rc_markStep(r, extc_rc_stepBudget(r));\n",
    "    r->wbDebt = 0;\n",
    "    extc_rc_finish(r);\n",
    "    return r->swFreed;\n",
    "}\n",
    "/* Contract entry (API / unit tests / settle / account queries): **finish one round within the call**. */\n",
    "__attribute__((unused)) static size_t extc_rc_collect(ExtcRcRegion *r, void *const *roots, size_t nroots) {\n",
    "    EXTC_RC_TICK(3);   /* per-part timing (`EXTC_RC_TIME=1`) */\n",
    "    extc_rc_why = \"collect\";\n",
    "    if (!r->marking) extc_rc_begin(r, roots, nroots);\n",
    "    while (!r->seedsDone || r->msp || r->scanObj) extc_rc_markStep(r, 0xffffffffu);   /* drain marking */\n",
    "    r->wbDebt = 0;\n",
    "    extc_rc_finish(r);\n",
    "    extc_rc_settle(r);   /* go on until the sweep is done too: the contract is one full round */\n",
    "    return r->swFreed;\n",
    "}\n",
    "\n",
    "/* Collect only when pressure is reached: return the number of slots reclaimed; return -1 below the pressure line and touch nothing. */\n",
    "__attribute__((unused)) static int extc_rc_maybeCollect(ExtcRcRegion *r, void *const *roots, size_t nroots) {\n",
    "    extc_rc_why = \"maybe\";\n",
    "    if (r->marking && (r->msp != 0 || !r->seedsDone || r->scanObj)) {   /* advance; when done let it through so collect can finish with the root table */\n",
    "        extc_rc_markAdvance(r);   /* advance in batches */\n",
    "    }\n",
    "    if (r->marking && (r->msp != 0 || !r->seedsDone || r->scanObj)) return 0;   /* skip:marking-resume */\n",
    "    if (r->sweeping) {\n",
    "        if (r->noSweep) { r->sweeping = 0; return -1; }   /* skip:nosweep-abandon */\n",
    "        return (int)extc_rc_sweepStep(r, EXTC_RC_SWEEP_BUDGET);   /* skip:sweeping-resume */\n",
    "    }\n",
    "    if (!r->marking && (!extc_rc_shouldSweep(r) || !extc_rc_roundOk(r))) return -1;   /* skip:no-trigger */   /* start a round: pressure + round credit; in-flight/finishing always pass */\n",
    "    long long _p0 = 0, _p1 = 0;\n",
    "    int _pcr;\n",
    "    extc_rc_pauseArm();\n",
    "    if (extc_rc_pauseOn) { _p0 = extc_rc_pauseNow(); }\n",
    "    _pcr = (int)extc_rc_step(r, roots, nroots);   /* hot path: one step, then finish as soon as done */\n",
    "    if (extc_rc_pauseOn) {\n",
    "        _p1 = extc_rc_pauseNow();\n",
    "        extc_rc_pauseTotal += _p1 - _p0;\n",
    "        if (_p1 - _p0 > extc_rc_pauseMax) { extc_rc_pauseMax = _p1 - _p0; }\n",
    "        extc_rc_pauseN++;\n",
    "    }\n",
    "    return _pcr;\n",
    "}\n",
    "\n",
    "/* ---- Debt flag (subset B): an inner frame allocates into an outer region [rt:owe] ----\n",
    " *\n",
    " * The inner frame's static root table is incomplete for a region **owned by an outer frame** (live references from other frames on the call stack are not in the table),\n",
    " * so it cannot sweep that region; but it can record \"one collection owed\" on the region. The one that acts is **the frame that owns it**,\n",
    " * and it happens **before that frame's next call** -- at that moment it has no active callee subtree, and its own\n",
    " * static root table (this frame's locals + parameters + globals) is the complete seed set. Therefore frame-level \"roots unreliable\"\n",
    " * flags are **not needed**: those are only required for the whole runtime root stack.\n",
    " *\n",
    " * Under multiple threads this record needs no thread-local storage: it is only recorded and settled on call chains where `parTls` is false\n",
    " * (TLS ownership is ambiguous, so no debt is issued there), and those frames all sit on the main thread's single call chain.\n",
    " *\n",
    " * Better too little than wrong: if the owner frame never calls again (`main` calls a callee only once) the debt stays forever and the\n",
    " * region waits until the frame is destroyed -- a relaxed upper bound, not a dangling pointer. */\n",
    "__attribute__((unused)) static void extc_rc_owe(ExtcRcRegion *r) { r->owe = 1; }\n",
    "__attribute__((unused)) static int extc_rc_owed(const ExtcRcRegion *r) { return r->owe; }\n",
    "/* Owner-side settling point: collect once and clear the flag. `noSweep` regions are reclaimed by counting only (obligation 7),\n",
    " * and not one byte may be swept. */\n",
    "__attribute__((unused)) static int extc_rc_checkOwed(ExtcRcRegion *r, void *const *roots, size_t nroots) {\n",
    "    extc_rc_why = \"owed\";\n",
    "    /* The settling point is the **only** settlement point of the frame owning this region: the round in flight must **finish** here,\n",
    "     * otherwise after settling there may be no more allocations and the home region would never finish sweeping. Obligation 7 regions are abandoned and report -1. */\n",
    "    if (r->sweeping) {\n",
    "        if (r->noSweep) { r->sweeping = 0; return -1; }   /* skip:nosweep-abandon */\n",
    "        return (int)extc_rc_sweepStep(r, EXTC_RC_SWEEP_BUDGET);   /* skip:sweeping-resume */\n",
    "    }\n",
    "    if (!r->owe) return -1;   /* skip:no-owe */\n",
    "    if (r->noSweep) { r->owe = 0; return -1; }   /* skip:nosweep */\n",
    "    if (r->marking) {   /* in flight: advance in batches (the debt counts as paid), no separate pause recorded */\n",
    "        r->owe = 0;\n",
    "        extc_rc_markAdvance(r);\n",
    "        return 0;   /* skip:marking-resume */\n",
    "    }\n",
    "    if (r->roundVisitedBytes != 0 && !extc_rc_roundOk(r)) return -1;   /* skip:owe-credit */   /* settling point: the first round is paid unconditionally */\n",
    "    r->owe = 0;\n",
    "    long long _p0 = 0, _p1 = 0;\n",
    "    int _pcr;\n",
    "    extc_rc_pauseArm();\n",
    "    if (extc_rc_pauseOn) { _p0 = extc_rc_pauseNow(); }\n",
    "    _pcr = (int)extc_rc_step(r, roots, nroots);   /* settling point: advance; settlement relies on the hot path/settle as a backstop */\n",
    "    if (extc_rc_pauseOn) {\n",
    "        _p1 = extc_rc_pauseNow();\n",
    "        extc_rc_pauseTotal += _p1 - _p0;\n",
    "        if (_p1 - _p0 > extc_rc_pauseMax) { extc_rc_pauseMax = _p1 - _p0; }\n",
    "        extc_rc_pauseN++;\n",
    "    }\n",
    "    return _pcr;\n",
    "}\n",
    "\n",
    "__attribute__((unused)) static int64_t extc_rc_bytes(const ExtcRcRegion *r) { extc_rc_settle((ExtcRcRegion *)r); return r->bytes; }\n",
    "__attribute__((unused)) static int64_t extc_rc_live(const ExtcRcRegion *r) { extc_rc_settle((ExtcRcRegion *)r); return r->live; }\n",
    "__attribute__((unused)) static int64_t extc_rc_scale(const ExtcRcRegion *r) { extc_rc_settle((ExtcRcRegion *)r); return r->scale; }\n",
    "__attribute__((unused)) static size_t extc_rc_sweeps(const ExtcRcRegion *r) { extc_rc_settle((ExtcRcRegion *)r); return r->sweeps; }\n",
    "__attribute__((unused)) static size_t extc_rc_freedSlots(const ExtcRcRegion *r) { extc_rc_settle((ExtcRcRegion *)r); return r->freedSlots; }\n",
    "/* **Hint** used by the trigger path to pick \"which piece has the most garbage\": `bytes - live`, with **no settle**.\n",
    " * Why it must be separate: the contract of `extc_rc_bytes/live` is \"accounts are final when observed\", so settle first, and that would do an\n",
    " * **unbounded drain** of the round in flight. Segmented triggering evaluates every piece on each trigger, and this path sits in the mutator hot loop, so\n",
    " * every trigger would pay an O(round in flight) pause.\n",
    " * A trigger only needs an **order**: `live` from the last completed round is enough. Direction: an older `live` overestimates garbage,\n",
    " * so it triggers sooner and reclaims sooner (conservative), never later. */\n",
    "__attribute__((unused)) static int64_t extc_rc_garbageHint(const ExtcRcRegion *r) {\n",
    "    return r->bytes - r->live;\n",
    "}\n",
    "__attribute__((unused)) static size_t extc_rc_slabCount(const ExtcRcRegion *r) {\n",
    "    size_t n = 0;\n",
    "    for (ExtcRcSlab *s = r->slabs; s; s = s->next) n++;\n",
    "    return n;\n",
    "}\n",
};

/**
 * @brief Report a malformed directive in the bundled runtime text and stop.
 *
 * The text is a constant of this file, so a conditional it cannot balance is a generator
 * bug, never something the program under compilation caused. Emitting the text as-is would
 * hand the C compiler a file this generator never checked.
 *
 * @param lineNo 1-based entry index in RECLAIM_RT.
 * @param what   the malformed directive, for the message.
 * @return       never returns.
 */
static void rtTextBug(size_t lineNo, const char *what) {
    fprintf(stderr, "extc: internal error -- reclaim runtime text: %s (line %zu)\n", what, lineNo);
    exit(1);
}

/**
 * @brief Append the reclaim runtime's C text to `out`.
 *
 * Emission is split by this compile's tier: the three switch macros are defined first (the
 * `#if`s in the text and the code after the generated file are chosen by them), then the text is
 * concatenated line by line. Sections this tier does not use (counters, frame-root chain) and
 * `#if`s whose branch is fixed are dropped instead of emitted; dropping equals letting the
 * preprocessor discard them, except that the generated file keeps no code this tier can never
 * reach.
 *
 * @param a          unused: the runtime is pure text.
 * @param out        output buffer receiving the generated code.
 * @param noCount    EXTC_RC_NOCOUNT: counting entry points compile to no-ops.
 * @param timeOn     EXTC_RC_TIME: per-operation counters in the runtime.
 * @param sweepFree  EXTC_RC_SWEEP_FREE: event tier, shouldSweep is always 0.
 * @param localStore EXTC_RC_LOCALSTORE: store-only entry for local slots (meaningful only in the
 *                   no-count tier).
 * @param frameRoots frame-root chain: 1 emits chain push/lookup code; no emitter pushes onto the
 *                   chain, so callers pass 0.
 */
void reclaimEmitRuntime(Arena *a, Buf *out, int noCount, int timeOn, int sweepFree,
                        int localStore, int frameRoots) {
    (void)a;
    /* Define the macros first: which branch of #if EXTC_RC_NOCOUNT / #if EXTC_RC_TIME below is
     * taken is decided by them. EXTC_RC_NOCOUNT is normally 1 — counting entry points compile to
     * no-ops and reclaim relies on regional sweep alone. */
    bufPuts(out, noCount ? "#define EXTC_RC_NOCOUNT 1\n" : "#define EXTC_RC_NOCOUNT 0\n");
    bufPuts(out, timeOn ? "#define EXTC_RC_TIME 1\n" : "#define EXTC_RC_TIME 0\n");
    bufPuts(out, sweepFree ? "#define EXTC_RC_SWEEP_FREE 1\n" : "#define EXTC_RC_SWEEP_FREE 0\n");
    enum { RT_CFG_MAX_DEPTH = 16 };   /* #if nesting the tables below can track */
    int skipSec = 0;        /* drop the current section whole */
    int sup = 0;            /* inside a dropped #if layer: emit the current branch */
    int depth = 0;
    int resolvable[RT_CFG_MAX_DEPTH];     /* this #if layer's tier is known (known => the whole directive is dropped) */
    int skipped[RT_CFG_MAX_DEPTH];        /* known layer: is the current branch the dropped one */
    size_t nlines = sizeof RECLAIM_RT / sizeof RECLAIM_RT[0];
    for (size_t i = 0; i < nlines; i++) {
        const char *line = RECLAIM_RT[i];
        if (strstr(line, "[rt:") != NULL) skipSec = !rtSectionOn(line, timeOn, frameRoots);
        if (skipSec) continue;
        if (strncmp(line, "#if", 3) == 0) {
            if (depth == RT_CFG_MAX_DEPTH) {
                char msg[80];
                snprintf(msg, sizeof msg, "#if nesting deeper than the %d-layer table",
                         RT_CFG_MAX_DEPTH);
                rtTextBug(i + 1, msg);
            }
            /* `#ifdef`/`#ifndef` and conditions rtCfgIf cannot resolve are left to the
             * preprocessor: the layer is tracked (so its #else/#endif still pair up) but
             * emitted verbatim, marked by `known = -1`. */
            int known = -1;
            int v = 0;
            if (strncmp(line, "#ifdef", 6) != 0 && strncmp(line, "#ifndef", 7) != 0)
                known = rtCfgIf(line + 3, noCount, timeOn, sweepFree, &v);
            resolvable[depth] = known;
            skipped[depth] = known == 1 && !v;
            if (skipped[depth]) sup++;
            depth++;
            if (known != 1 && !sup) bufPuts(out, line);
            continue;
        }
        if (strncmp(line, "#else", 5) == 0) {
            if (depth == 0) rtTextBug(i + 1, "unbalanced #else");
            if (resolvable[depth - 1] == 1) {
                sup += skipped[depth - 1] ? -1 : 1;
                skipped[depth - 1] = !skipped[depth - 1];
                continue;
            }
            if (!sup) bufPuts(out, line);
            continue;
        }
        if (strncmp(line, "#endif", 6) == 0) {
            if (depth == 0) rtTextBug(i + 1, "unbalanced #endif");
            depth--;
            if (resolvable[depth] == 1) {
                if (skipped[depth]) sup--;
                continue;
            }
            if (!sup) bufPuts(out, line);
            continue;
        }
        if (!sup) bufPuts(out, line);
    }
    /* A leftover layer means the text ends inside a conditional: the emitted file would
     * silently keep whatever a missing #endif swallowed, so stop instead. */
    if (depth != 0) rtTextBug(nlines, "unterminated #if");
    /* EXTC_RC_LOCALSTORE (compile-time, off by default): store-only entry for local and
     * parameter slots. In the no-count tier, storeRefOwned(slot, v, owner=0) does two ownSlab
     * checks and then does nothing because so == 0, so those two lookups are wasted. This entry
     * skips them; it is meaningful only in the no-count tier. */
    if (localStore && noCount) {
        bufPuts(out,
            "/* Write-only store entry for a local/param slot: in the no-count tier the two\n"
            " * ownSlab probes would find no owner, so skip them (the slot is not an rc slot).\n"
            " * No barrier: shadeOld covers the old edge that the overwrite deletes. */\n"
            "__attribute__((unused)) static inline void extc_rc_storeRefLocal(void **slot, void *v) {\n"
            "    if (!slot) return;   /* skip:slot-null: no slot to update */\n"
            "    *slot = v;\n"
            "}\n");
    }
}
